window.__D("text/likkutei-sichot/c011",{"p":[[1301430092,"<h3>שיחה ג</h3>\nא. ברמב\"ם סוף הלכות ספר תורה<sup data-n=\"322\">1</sup>: כל<sup data-n=\"323\">2</sup> מי שיושב לפני ספר תורה ישב<sup data-n=\"324\">3</sup> בכובד ראש באימה ופחד<sup data-n=\"325\">4</sup> שהוא העד הנאמן לכל<sup data-n=\"326\">5</sup> באי עולם שנאמר<sup data-n=\"327\">6</sup> והי' שם בך לעד, ויכבדהו כו'<sup data-n=\"328\">7</sup>.\nתוכן הדין ד\"אימה ופחד\" לפני ספר תורה מצינו בירושלמי<sup data-n=\"329\">8</sup> — שאמר ר\"ש בר\"י (כשראה אחד עומד ומתרגם התורה והי' סומך עצמו על העמוד) \"כשם ש­ניתנה באימה וביראה<sup data-n=\"330\">9</sup> כך אנו צריכין לנהוג בה באימה וביראה<sup data-n=\"330\">9</sup>\".\nאבל הרמב\"ם לא כתב טעם זה \"כשם שניתנה כו'\", ובפשטות י\"ל — כי דין זה ברמב\"ם אינו הדין שבירושלמי:\nמ\"ש בירושלמי \"צריכין לנהוג בה באימה וביראה\" קאי בשעת קריאת ה­תורה<sup data-n=\"332\">10</sup> ותרגומה [וע\"ד מה שלמדין בבבלי<sup data-n=\"333\">11</sup> שלימוד התורה צ\"ל באימה — \"מה להלן באימה (דכתיב<sup data-n=\"334\">12</sup> וירא העם וינועו וגו'. רש\"י) וביראה וברתת<sup data-n=\"335\">13</sup> ובזיע אף כאן באימה וביראה וברתת ובזיע\"], ודין זה אכן הובא ברמב\"ם לעיל (בהל' תפלה<sup data-n=\"336\">14</sup>) \"ואין התורגמן נשען לא לעמוד ולא לקורה אלא עומד באימה וביראה\". משא\"כ ברמב\"ם כאן איירי בהחיוב של כובד ראש ואימה ופחד לא (רק) בזמן שקורא או לומד מתוך ספר התורה אלא לגבי \"כל מי שיושב לפני ספר תורה\", היינו שגם הישיבה לפני ס\"ת צ\"ל בכובד ראש וכו', ולכן לא כתב \"כשם שניתנה כו' כך צריכים לישב באימה כו'\", אלא הביא טעם אחר.\nאבל עדיין אין הענין מיושב:\nתוכן פרק זה ברמב\"ם הוא בדיני כבוד ס\"ת, והזהירות היתירה שלא לנהוג",[["322","1","פ\"י הי\"א."],["323","2","בטור ושו\"ע יו\"ד ר\"ס רפב נעתק לשון הרמב\"ם בשינויים קלים, כדלקמן בהערות."],["324","3","בטור שם ישחה לפניו."],["325","4","בטור \"ובאימה (ועד\"ז הוא בכת\"י התימנים דהרמב\"ם — ראה רמב\"ם הוצאת קאפח כאן) (ומוסיף —) וביראה ובפחד\". בשו\"ע \"וביראה וב­פחד\" וליתא \"באימה\". וכבפנים איתא גם בקרית ספר להמבי\"ט סוף הל' ס\"ת. וראה בהנסמן בהערה 13."],["326","5","בטור ושו\"ע: על כל. וכ\"ה בכת\"י הרמב\"ם הנ\"ל."],["327","6","וילך לא, כו."],["328","7","ראה לקמן סוס\"ג ובהנסמן שם."],["329","8","מגילה רפ\"ד (הובא בכמה ראשונים בשינוי לשון)."],["330","9","ברי\"ף מגילה פ' הקורא עומד (פ\"ד), וברא\"ש שם (רפ\"ג) ליתא תיבת \"וביראה\". ועד\"ז הוא בהגה\"מ להל' תפלה פי\"ב הי\"א אות ט. ובעוד ראשונים."],["330","9","ברי\"ף מגילה פ' הקורא עומד (פ\"ד), וברא\"ש שם (רפ\"ג) ליתא תיבת \"וביראה\". ועד\"ז הוא בהגה\"מ להל' תפלה פי\"ב הי\"א אות ט. ובעוד ראשונים."],["332","10","ועד\"ז במס' סופרים פ\"ג הי\"ב (ראה מגדל עוז כאן) שנוסף לזה שהמדובר שם בעיקר הוא בשלילת הבזיון, הרי הדין הוא כשקורא בו, כלשון המ\"ס \"(אלא) אוחז בידיו באימה וקורא בו\". ועד\"ז מה שציין בביאור הגר\"א בשו\"ע יו\"ד שם סק\"ז על דין הנ\"ל (ברמב\"ם ובשו\"ע) \"כמ\"ש בפ\"ב דשבת (ל, ב) לענין רבו\" — הרי שם לא מדובר ע\"ד הישיבה לפני רבו, אלא כשלומד מפי רבו, כמפורש בהמשך הגמ' שם."],["333","11","ברכות כב, א. וש\"נ."],["334","12","יתרו כ, טו."],["335","13","ראה ע\"ד ב' לשונות אלו אם כולם בוא\"ו או \"ביראה\" ו\"ברתת\" בלא וא\"ו ושינוי הגירסאות בזה — לקו\"ש חכ\"ה ע' 71. וש\"נ."],["336","14","פי\"ב הי\"א. וראה כס\"מ שם: ירושלמי (הנ\"ל). . וכתבו ההגהות כו' דכ\"ש שהקורא אסור לישען בשעת קריאת התורה."]]],[1301430093,"בו מנהג בזיון ח\"ו, וא\"כ מהו החידוש המיוחד שבדין זה (שהישיבה לפני ספר תורה צ\"ל \"בכובד ראש באימה ופחד\"), שהרמב\"ם הוצרך להביא ע\"ז טעם חדש ומיוחד — \"שהוא העד הנאמן כו'\"?\nיתירה מזו: בהלכה שלפנ\"ז<sup data-n=\"337\">15</sup> כ' הרמב\"ם \"מצוה לייחד לספר תורה מקום ולכבדו ולהדרו יותר מדאי, דברים שב­לוחות הברית הן הן שבכל ספר וספר, לא ירוק אדם כנגד ספר תורה כו' ולא יחזיר אחוריו לספר תורה כו'\" — הרי שכבר כתב הרמב\"ם שהטעם על כבוד ס\"ת (\"לכבדו ולהדרו יותר מדאי\") שייך ל\"דברים שבלוחות הברית. . שבכל ספר\", ומהי ההוספה בזה שס\"ת \"הוא ה­עד הנאמן לכל באי עולם\", שדוקא מפני זה צריך לישב לפני ס\"ת \"בכובד ראש באימה ופחד\"<sup data-n=\"338\">16</sup>.\nב. גם יל\"ע לכאורה במ\"ש שס\"ת \"הוא העד הנאמן לכל באי עולם\":\nענין העדות מצינו גם במצות תפילין שנאמר בה<sup data-n=\"339\">17</sup> \"והי' לך לאות על ידך\"<sup data-n=\"340\">18</sup> (והביאו הרמב\"ם לעיל בהל' תפילין<sup data-n=\"341\">19</sup>), שהאות ענינה עדות<sup data-n=\"342\">20</sup> [וי\"א<sup data-n=\"343\">21</sup> שתפילין הוא \"לשון ויכוח. . על שם שהם עדות והוכחה שהשם נקרא עליו ויראים ממנו כמו דאמרינן לקמן<sup data-n=\"344\">22</sup> וראו כל עמי ה­ארץ כי שם ה' נקרא עליך גו'<sup data-n=\"345\">23</sup> אלו תפלין שבראש\"], ומ\"מ לא כתב הרמב\"ם שה\"אות\" והעדות גורמים דינים מיוחדים בישיבה לפני התפילין.\nאיברא שמצינו ברמב\"ם<sup data-n=\"346\">24</sup> אריכות ב­דיני קדושת תפילין (נוסף על דיני זהי­רות מלבזותן), וכתב שם<sup data-n=\"347\">25</sup> \"קדושת תפי­לין קדושתן גדולה היא כו'\", אבל בד\"א בזמן קיום המצוה (כשהתפילין מונחים עליו) — \"שכל זמן שהתפילין בראשו של אדם ועל זרועו הוא עניו וירא שמים ואינו נמשך בשחוק ובשיחה בטילה ואינו מהרהר מחשבות רעות כו', לפיכך צריך אדם להשתדל להיותן עליו כל היום\"; אבל לא כתב א) שיש דין מיוחד על הזהירות בכבודם (גם) כשאינם עליו, ב) שדין זה הוא מטעם שהן אות ועדות.\nודורש ביאור טובא, מאי שנא ס\"ת, שלהיותו \"עד הנאמן כו'\" ה\"ה מחייב הנהגה של \"ישב בכובד ראש כו'\" גם כשאינו עוסק בו?\nג. וי\"ל הביאור בכל זה ע\"פ דיוק לשון הרמב\"ם \"כל מי שיושב לפני ספר תורה ישב בכובד ראש כו'\" — דלכאורה הול\"ל בלשון קצרה<sup data-n=\"348\">26</sup> \"וישב לפני ס\"ת בכובד ראש כו'\", ומהי אריכות הלשון \"כל מי שיושב לפני ס\"ת ישב כו'\"?",[["337","15","פ\"י ה\"י."],["338","16","ולהעיר: בתחלת ההלכה בשו\"ע שם: \"מצוה לייחד לו (לס\"ת) מקום כו' ולא ירוק כנגד כו', ולא יגלה כו' ולא יפשוט כו' ולא יניחנו כו' אלא ישב לפניו בכובד ראש כו'\", ומשמיט (כברוב המקומות) הטעם שברמב\"ם \"דברים שבלוחות הברית הן הן שבכל ספר וספר\"<sup data-n=\"e9\">*</sup>. ולפי פשטות המשך הלשון משמע, שמ\"ש בסוף ההלכה \"שהוא העד הנאמן על כל באי עולם\" הוא הטעם על כל הדינים שבהלכה זו. ואכ\"מ."],["339","17","בא יג, ט. שם, טז."],["340","18","עירובין צו, א. מנחות לו, ב (וראה מ\"ש בגליון שם)."],["341","19","פ\"ד ה\"י."],["342","20","ראה פרש\"י עירובין שם — הובא לקמן ס\"ד."],["343","21","תוד\"ה לטוטפות — מנחות לד, ב."],["344","22","מנחות לה, ב. ברכות ו, א. ועוד."],["345","23","תבא כח, יו\"ד."],["346","24","פ\"ד הי\"ד ואילך."],["347","25","שם הכ\"ה."],["348","26","ע\"ד הל' בטושו\"ע שם."],["e9","*","ובטור מביאו לאח\"ז. ואכ\"מ."]]],[1301430094,"ונראה לומר, שבזה מדגיש הרמב\"ם החידוש שבדין זה<sup data-n=\"349\">27</sup> לגבי הדינים דכבוד ס\"ת שלפנ\"ז (בפרק זה):\nהענין דכבוד ס\"ת (בפשטות) הוא ה­חיוב שחל על (הנהגת) האדם ביחס ל­ספר התורה: מכיון שס\"ת יש בו קדושה וכו', ה\"ז מחייבו להתנהג באופן של כבוד, לכבדו ולהדרו, ולא ירוק כנגד ס\"ת כו'. וזהו תוכן הדינים לפנ\"ז — פרטי דיני הכבוד ואופני הנהגה כלפי ס\"ת.\nמשא\"כ כאן אין המדובר ב\"כובד ראש וכו'\" \"הנמשכים\" מחיובי האדם ב­הנהגתו וגישתו לספר התורה, אלא אדרבה — ב\"כובד ראש וכו'\" שספר התורה מעורר ופועל בהגברא. דגם כ­אשר המדובר הוא בשעה (שאינו עומד להתעסק באיזה אופן שהוא בשייכות לס\"ת, אלא) שהוא (סתם) \"יושב לפני ס\"ת\", זה לבד צריך לפעול עליו ש\"ישב בכובד ראש באימה ופחד\".\nולכן מדייק הרמב\"ם \"כל מי שיושב לפני ספר תורה ישב בכובד ראש באי­מה ופחד\", ולא כ' בקיצור \"וצריכים לישב לפני ס\"ת בכובד ראש כו'\" (וע\"ד לשון הירושלמי הנ\"ל \"אנו צריכין לנהוג בה באימה וביראה\") — כי אין כוונתו כאן להחיוב בהנהגת האדם לכבד התו­רה, אלא בנוגע לפעולת התורה בהאדם (ב\"כל מי שיושב לפני ס\"ת\").\n[ועפ\"ז מובן גם המשך דברי הרמב\"ם, שלאחרי דין זה ממשיך \"ויכבדהו לפי כוחו כו' כל המכבד את התורה גופו מכובד על הבריות כו'\" — שקאי ג\"כ בפעולת התורה על הגברא, שע\"י התורה \"גופו מכובד על הבריות\", כדלקמן סעיף ח].\nד. ולכן הוזקק הרמב\"ם להביא טעם חדש ומיוחד — \"שהוא העד הנאמן כו'\":\nגם גבי תפילין הביא הרמב\"ם (כנ\"ל) ע\"ד פעולת התפילין בהאדם המניחן — שעי\"ז \"הוא עניו וירא שמים ואינו נמשך בשחוק כו'\", אבל שם אין צורך להביא ע\"ז טעם מיוחד, מאחר שהמדובר הוא בשעה שהתפילין על האדם, שכאשר האדם מקיים מצות תפילין ומניחן על גופו, הרי מובן מאליו שקדושת התפילין הגדולה והחמורה פועלת על האדם ה­מניח תפילין.\nמשא\"כ גבי ס\"ת שהרמב\"ם מדייק לומר \"כל היושב לפני ס\"ת\" — אף שאינו עוסק בתורה — הרי עליו לישב בכובד ראש כו', היינו, שהמצאו של ספר התו­רה לפני האדם צריך לפעול בו שישב \"בכובד ראש באימה ופחד\" — ובמה הוא כח פעולתו המיוחד הזה של ספר ה­תורה?\nע\"ז מבאר הרמב\"ם כי ספר תורה \"הוא העד הנאמן לכל באי עולם שנאמר והי' שם בך לעד\".\nוהביאור בזה:\nהרמב\"ם מדייק כאן שס\"ת \"הוא העד הנאמן לכל באי עולם\"<sup data-n=\"350\">*27</sup> — ולכאורה, הרי מפשטות המשך הכתובים משמע, דמ\"ש \"והי' שם בך לעד\", הכוונה שהס\"ת הוא עדות בישראל, עדות והתראה לבנ\"י על שמירת התורה והמצות<sup data-n=\"351\">28</sup>.",[["349","27","להעיר שבכת\"י תימן מתחילה כאן הלכה בפ\"ע (ראה רמב\"ם הוצאת קאפח)."],["350","*27","היינו גם אומות העולם. וראה לקו\"ש חי\"ג ע' 230 בהערות. חכ\"ז ע' 246 ובהערה 74. חכ\"ח ע' 104 הערה 4."],["351","28","כפשטות הכתובים ומפרשי התורה שם (וילך לא, כו)."]]],[1301430095,"ומזה מובן, שכוונת הרמב\"ם בענין ה\"עד\" שבס\"ת היא (לא כדמשמע לכאו­רה מפשטות הכתוב \"והי' שם בך לעד\", עדות והתראה לבנ\"י על שמירת התומ\"צ — כ\"א) עדות ע\"ז ש\"בחר בנו מכל העמים ונתן לנו את תורתו\". כלומר: המציאות של ס\"ת ה\"ה \"עד\" על בחירת הקב\"ה ב­עם ישראל<sup data-n=\"352\">29</sup>. ולכן, כשאיש ישראל יושב לפני ס\"ת, הרי ידיעה זו שספר התורה הוא \"עד\" צריכה לפעול בו כובד ראש ואימה ופחד מפני הקב\"ה ש\"בחר בנו מכל העמים\" להיות לו לעם סגולה כו'.\nוזהו גם החידוש בהעדות דס\"ת לגבי האות דתפלין:\nבענין האות דתפילין כ' רש\"י<sup data-n=\"353\">30</sup> \"ש­ישראל צריכים להעמיד אות על עצמן להכיר שהם מחזיקים בתורתו של הקב\"ה\", ולכן זה קשור דוקא עם הפעו­לה דהנחת תפילין, שהיא דוקא ביום ולא בלילה, ולא בשבת ויו\"ט<sup data-n=\"354\">31</sup>, ואינה שייכת לנשים וקטנים<sup data-n=\"355\">32</sup>. ולכן לא שייך בזה הדין דישיבה בכובד ראש באימה ופחד מצד גוף התפילין.\nאבל העדות דס\"ת אינה מצד פעולת האדם, קריאתו בתורה וכיו\"ב, אלא גוף החפצא של הס\"ת עצמו \"הוא העד הנאמן לכל באי עולם\", שבנ\"י מובדלים משאר העמים בזה שהם העם שבהם בחר ה'; ולכן ה\"ז בכל עת ובכל זמן ולכל אחד ואחת מישראל, וכדיוק לשון הרמב\"ם \"כל מי שיושב כו'\". כי הבדלה זו ד\"אתה בחרתנו מכל העמים. . ורוממתנו מכל הלשונות\" כוללת כאו\"א מבנ\"י מבלי הבדל כלל.\nה. עפ\"ז מובן ג\"כ החילוק בין דברי הרמב\"ם כאן \"שהוא העד הנאמן כו'\" ומ\"ש בהלכה שלפנ\"ז \"מצוה לייחד ל­ספר תורה מקום ולכבדו ולהדרו יותר מדאי דברים שבלוחות הברית הן הן ש­בכל ספר וספר\" (כלומר, דין זה הוא מטעם שהספר (וכל ספר שבספר זה) מכיל \"דברים שבלוחות הברית\"):\nההפרש בין \"ברית\" ו\"עדות\" בפשטות הוא: \"ברית\" הוא שם התואר לדבר ה­פועל קשר וחיבור בין שני בעלי הברית, ועדות ענינה רק הוכחה וראי' על ענין (הברית שכבר נכרת בין שני בעלי ברית).\nוזהו החילוק בין \"לוחות הברית\" ו­ספר תורה ש\"הוא העד הנאמן כו'\"<sup data-n=\"356\">33</sup>:\n(עיקר) ענינם של הלוחות הוא זה שהם \"לוחות הברית\"<sup data-n=\"357\">34</sup>, שנקראו כך לפי שהם הברית בין הקב\"ה ובנ\"י, כמ\"ש<sup data-n=\"358\">35</sup> \"לוחות הברית אשר כרת ה' עמכם\", היינו הברית על שמירת התורה והמצות, שעי\"ז נעשה קשר וברית בין הקב\"ה ובנ\"י<sup data-n=\"359\">36</sup>.\nולכן \"מצוה לייחד לספר תורה מקום",[["352","29","ראה מדרש לקח טוב (תרומה כה, טז) בפי' \"את העדות\": עדות התורה לעולם שהקב\"ה בחר בישראל ונתן להם את תורתו. וראה בהנסמן לקמן הערה 36."],["353","30","עירובין שם ד\"ה מי שצריכים."],["354","31","מקומות שצויינו בהערה 18; 19."],["355","32","רמב\"ם הל' תפילין פ\"א הי\"ג."],["356","33","החילוק והדיוק שבפנים בין ב' ההלכות י\"ל שמודגש בזה שאף שהלוחות נקראים לפעמים \"לוחות העדות\" (תשא לא, יח. לב, טו. לד, כט), ומ\"מ כותב הרמב\"ם \"לוחות הברית\" (עקב ט, ט. יא. טו)."],["357","34","עקב שם."],["358","35","עקב ט, ט."],["359","36","ראה רשב\"ם תרומה כה, טז. וראה גם ראב\"ע שם. בפרש\"י \"התורה שהיא עדות כו'\" ו­שקו\"ט במפרשי רש\"י (רא\"ם, גו\"א, לבוש, משכיל לדוד ועוד) אם הכוונה להלוחות (וכפרש\"י פקודי מ, כ) או להס\"ת. וראה לקו\"ש ח\"ט ע' 196 הערה 6."]]],[1301430096,"כו'\", שהוא (אחד) מחיובי האדם כלפי התורה, זה שהאדם צריך לכבד את ה­תורה. דמכיון שהתורה היא המקשרת את האדם עם הקב\"ה, צריך לכבד אותה.\nוהחידוש בהלכה זו (\"מצוה לייחד ל­ספר תורה מקום כו'\") — שמשו\"ז מוסיף הרמב\"ם כאן טעם מיוחד (\"דברים שב­לוחות הברית כו'\"): עד הלכה זו פירט הרמב\"ם החיובים דכבוד ס\"ת מצד ה­פעולה דקדושת התורה (וכלשונו בתחלת הפרק (הלכה ב ואילך) \"ס\"ת כשר נוהגין בו קדושה יתירה וכבוד גדול\" — וממ­שיך בכל החיובים של כבוד ס\"ת); וכאן מוסיף שיש דין כבוד מצד החפצא ד­תורה, שזה מחייב ומוסיף במצות כבוד ס\"ת דין \"מקום\"<sup data-n=\"360\">37</sup> — \"מצוה לייחד לספר תורה מקום ולכבדו ולהדרו כו'\" — וע\"ז מביא הטעם מפני ש\"דברים שבלוחות הברית הן הן שבכל ספר וספר\", דמכיון שספר תורה מכיל את ה\"דברים שב­לוחות הברית\", ה\"ז מחייב שיהי' לו מקום מיוחד.\nאבל מ\"מ, אף שדין זה הוא מצד ה­חפצא של הס\"ת — מ\"מ ה\"ז מחיובי הגברא כלפי התורה, שחייב לכבד את הס\"ת עי\"ז שמייחד לו מקום, והחפצא של ס\"ת, מכיון שהדברים שבו הן \"דב­רים שבלוחות הברית\", דורש שגם \"מקום\" התורה יהי' מכובד על האדם;\nמשא\"כ בהלכה שלאח\"ז לא איירי ה­רמב\"ם כלל בחיובי הגברא לכבד ה­תורה, אלא בפעולת התורה על הגברא, ולכן כותב הטעם — ש\"הוא העד הנאמן כו'\", כלומר, דמכיון שהחפצא דס\"ת הוא \"עד\"<sup data-n=\"361\">38</sup> על בחירת הקב\"ה בבנ\"י, לכן כשאדם יושב לפני ס\"ת צריך לישב \"בכובד ראש באימה ופחד\".\nו. ביאור הענין בסגנון תורת ה­חסידות:\nג' ענינים אלו שבס\"ת — קדושתה, לוחות הברית, עד הנאמן — מורים על ג' אופנים ומדריגות בהתקשרות בנ\"י עם הקב\"ה, שנעשו ובאו בשלמותם במ\"ת: א) קדושת ישראל, ב) התקשרות באופן של ברית, ג) התקשרות עצמית.\nוהביאור בזה:\nקדושת ישראל שנעשה במ\"ת ענינה הוא קדושת הנשמה שבכל או\"א מישר­אל. כי אף שמצד זה שהאבות הן הן ה­מרכבה<sup data-n=\"362\">39</sup> הורישו לכאו\"א מבניהם אחרי­הם עד סוף כל הדורות נשמה קדושה (שאינה באוה\"ע)<sup data-n=\"363\">40</sup> מ\"מ גמר ושלימות קדושת הנשמה נעשה במ\"ת. וכמו שהוא בכ\"א מישראל, שתיכף משנולד יש בו נפש קדושה, ו(אח\"כ) תחילת כניסת נפש זו דקדושה היא במצות מילה<sup data-n=\"364\">41</sup>, מ\"מ \"גמר ועיקר כניסת נפש הקדושה באדם הוא בי\"ג שנים ויום א' לזכר וי\"ב לנקבה שלכן נתחייבו אז במצות מן התורה ונעשו בני עונשים\"<sup data-n=\"365\">42</sup>.\nברית שבמ\"ת ענינה הוא ההתקשרות להקב\"ה שעל ידי שמירת התורה ו­",[["360","37","ראה לקו\"ש חכ\"ח ע' 56 ואילך."],["361","38","וגדר זה (\"עד הנאמן\") הוא דוקא בס\"ת שלימה ותמימה, משא\"כ בה\"י \"דברים שבלוחות הברית הן הן שבכל ספר וספר\" (שלכן מצוה לייחד לספר תורה מקום) הוא לא מצד החפצא דספר תורה כ\"א חפצא ד(דברי) תורה שבכתב, שחל גם על חל­קי התורה. ואכ\"מ."],["362","39","ב\"ר פמ\"ז, ו. פפ\"ב, ו."],["363","40","ראה תניא פי\"ח (כג, ב)."],["364","41","ראה שו\"ע אדה\"ז או\"ח מהד\"ת סוס\"ד: תחלת כניסת נפש זו דקדושה היא. . גם במצות מילה. וראה לקו\"ש ח\"ג ע' 4­763, שהדיוק הוא \"כניסת נפש כו'\"."],["365","42","שו\"ע אדה\"ז שם."]]],[1301430097,"מצותי'<sup data-n=\"366\">43</sup>. התורה היא הברית המחברת את ישראל עם הקב\"ה, וכמאמר הזהר<sup data-n=\"367\">44</sup> דישראל מתקשראן באורייתא ואורייתא בקוב\"ה, שע\"י התורה מתקשרים ישראל בקוב\"ה.\nהתקשרות עצמית שבמ\"ת הוא<sup data-n=\"366\">43</sup> מה שהקב\"ה בחר בנו מכל העמים<sup data-n=\"369\">45</sup>, דענין הבחירה אינו מצד קדושה או מעלה, אלא שרשו בעצומ\"ה ית' שלמעלה מכל הגדרים ומעלות<sup data-n=\"370\">46</sup>.\nוהחילוק בין ג' מדריגות אלו הוא: אף שכל ג' אופני התקשרות אלו ישנם תמיד בישראל, מ\"מ ישנם חילוקים ב­אופן פעולתם בישראל:\nבענין הקדושה שבישראל — ישנם מ­בנ\"י שקדושת נשמתם מאירה אצלם בגילוי, ואלו שאינה מאירה אצלם כ\"כ, ובאלו שמאירה בגילוי ישנם דרגות ואו­פנים שונים בהתגלות הקדושה בזמני ה­שנה — בימי החול, בש\"ק, ימים נוראים, מועדי השנה.\nוכן הוא בנוגע לענין הברית שבתו­רה, ההתקשרות עם הקב\"ה שע\"י שמירת התורה והמצוות, דאף שזה קיים תמיד בכ\"א מישראל, מבלי הבט על מעמדו ומצבו, כמרומז גם בתיבת \"ישראל<sup data-n=\"371\">47</sup> — ר\"ת יש ששים רבוא אותיות לתורה\"<sup data-n=\"372\">48</sup>, והיינו שבכל איש ישראל, באיזה מצב שהוא, ישנו הקשר לתורה (ועל ידה ל­קוב\"ה) ונמשך ע\"י האות שבתורה השייכת אליו, מ\"מ ישנם חילוקים בין אות לאות ובמילא בין בני ישראל וכן בגילוי ענין זה, וכן בכ\"א גופא, מזמן לזמן (בהתאם למעמדו ומצבו בלימוד ה­תורה וקיום המצות).\nאמנם ההתקשרות העצמית של בנ\"י בהקב\"ה, אין בה התחלקות ודרגות, כי היא ההתקשרות דעצם דישראל עם עצמותו ית'.\nז. וזהו תוכן הענין שהס\"ת \"הוא העד הנאמן לכל באי עולם\":\nידוע מש\"כ (אדה\"ז<sup data-n=\"373\">49</sup> וכו') שעדות היא על דבר הנסתר והנעלם, אבל על דבר הנגלה אין צריכים ענין העדות, ויתירה מזו אפילו על \"מילתא דעבידא לאגלויי\" לא הצריכה התורה עדות<sup data-n=\"374\">50</sup>, עדות היא דוקא על דבר הנעלם (כמבואר בארוכה (גם) בענין \"אתם עדי\"<sup data-n=\"375\">51</sup>).\nועפ\"ז מובן גם בעדות זו של התורה שהיא העד הנאמן על בנ\"י, שעדות זו אינה על דבר הגלוי, היינו על התקשרות זו דבנ\"י שע\"י התומ\"צ, שהוא דבר ה­ניכר ונראה שבנ\"י מובדלים בזה מ­אוה\"ע;\nוכן העדות אינה על קדושת ישראל — נפש הקדושה שבכ\"א מישראל, דאף שהקדושה אינה ניכרת תמיד באופן גלוי",[["366","43","ראה לקו\"ש חי\"ח ע' 407 ואילך. וש\"נ."],["367","44","ח\"ג עג, א."],["366","43","ראה לקו\"ש חי\"ח ע' 407 ואילך. וש\"נ."],["369","45","וכידוע ש\"ובנו בחרת\" הי' במ\"ת (שו\"ע אדה\"ז או\"ח סי' ס ס\"ד (ממג\"א שם) שכשיאמר ובנו בחרת יזכור מ\"ת)."],["370","46","להעיר מהפי' ב\"תלת קשרין כו' ישראל באורייתא ואורייתא בקוב\"ה\" (דלכאורה ישנם רק שני קשרים), דישנו קשר ג' ישראל וקוב\"ה (בלי ממוצע) ואורייתא — ראה לקו\"ש חי\"ח שם. סה\"מ מלוקט ח\"ג ע' קנה."],["371","47","דאע\"פ שחטא ישראל הוא (סנה' מד, רע\"א)."],["372","48","מג\"ע אופן קפו."],["373","49","לקו\"ת פקודי ד, סע\"א ואילך. וראה ג\"כ ד\"ה ויקם עדות ה'ש\"ת פ\"א. ועוד."],["374","50","ר\"ה כב, ב. וש\"נ. לקו\"ת שם. ד\"ה ויקם עדות שם."],["375","51","וראה בארוכה לקו\"ש חי\"ט ע' 190 ואילך."]]],[1301430098,"ומורגש, מ\"מ הרי זה בגדר מילתא ד­עבידא לאגלויי, שכ\"א מישראל מזמן לזמן מאירה אצלו נפש זו דקדושה, מתעוררת בו ומאירה בזמני רצון בשנה (או ע\"י בת­קול מלמעלה כידוע<sup data-n=\"376\">52</sup>),\nאלא העדות דס\"ת היא על הקשר ה­עצמי דישראל עם עצמותו ית' שהוא דבר הנעלם, אמנם קיים בכ\"א מישראל בכל מצב שהוא.\nועפ\"ז מובן גם דיוק לשון הרמב\"ם \"הוא העד הנאמן\": בהברית בין הקב\"ה וישראל על שמירת התורה ומצות הרי כאשר חסר ח\"ו בקיום התומ\"צ פוגע בה­ברית<sup data-n=\"377\">53</sup>; משא\"כ הקשר העצמי בין ישר­אל והקב\"ה הרי הוא דבר נצחי לעולם<sup data-n=\"378\">54</sup> ובאיזה מצב שהוא של בנ\"י, ולכן \"הוא העד הנאמן\".\nח. עפ\"ז יש לבאר ג\"כ (בפנימיות ה­ענין) דברי הרמב\"ם בהמשך ההלכה, שלאחרי דין זה מסיים (הלכות ס\"ת) \"ויכבדהו כפי כוחו אמרו חכמים ה­ראשונים<sup data-n=\"379\">55</sup> כל המחלל את התורה גופו מחולל על הבריות וכל המכבד את התורה גופו מכובד על הבריות\".\nדלכאורה יש לדייק בפרטי הלשונות:\nא) ענין זה שהאדם מכבד את התורה בשביל שכר (שיהא \"גופו מכובד על הבריות\") אינה דרגא נעלית בעבודת השם — שה\"ז עבודה שלא לשמה<sup data-n=\"380\">56</sup>. ותמוה: היתכן שלאחרי אריכות הביאור ע\"ד מעלתו וגדולתו של ספר תורה, שיש בו \"דברים שבלוחות הברית\", \"הוא העד הנאמן כו'\", יסיים הרמב\"ם בענין התועלת והשכר שיגיע לאדם עי\"ז ומזה שהוא מכבד את התורה?\nב) וגדלה התמי' — שבשכר גופא, בחר הרמב\"ם בהשכר ד\"גופו מכובד על הבריות\", היינו שהמדובר כאן לא ב­כבוד רוחני (השייך לנשמתו של אדם), אלא ש(גם) גופו (הגשמי) יהי' מכובד על הבריות [וי\"ל שזהו גם הדיוק \"גופו מכובד על הבריות\", כלומר המדובר כאן בכבוד שיכבדוהו בריות בעלמא<sup data-n=\"381\">57</sup> (ולא בעלי תורה ומעלה), שהכבוד הבא מ\"בריות\", שאין להם מושג בענינים רוחניים, שייך לגופו של האדם] — ואיך מתאים לסיים כל הלכות ספר תורה בשכר זה?!\nוע\"פ הנ\"ל יש לומר, שאין כוונתו ל­הודיע השכר שמגיע להאדם ע\"י שמכבד את התורה, אלא שזה בא בהמשך למ\"ש הרמב\"ם לפנ\"ז שהחפצא של תורה פועלת על הגברא, מפני ש\"הוא העד הנאמן לכל באי עולם\".\nוהביאור:\nעדות היא על דבר הנעלם — בכדי לגלות דבר נעלם זה; וכן בעניננו, שס\"ת מגלה את הקשר העצמי של ישראל וקוב\"ה, עד שעי\"ז ניכרת חשיבותם של ישראל בגלוי \"לכל באי עולם\".\nובהמשך לזה כותב הרמב\"ם (ומסיים הלכות ספר תורה) ב\"עדות\" זו של ס\"ת,",[["376","52","ראה לקו\"ת תצא לו, ד. האזינו עא, ד. המשך תרס\"ו ע' קכא. ד\"ה אריב\"ל בכ\"י ב\"ק כו' תש\"ב פ\"א. ועוד."],["377","53","וי\"ל שזה נתגלה בשבירת \"לוחות הברית\", כשראה משה מצב בנ\"י בירידתו מן ההר."],["378","54","ראה הלשון במדרש לקח טוב (הנ\"ל הערה 29) עדות התורה לעולם כו'."],["379","55","אבות פ\"ד מ\"ו (בסדר הפוך, ובפשטות שינה הרמב\"ם כדי לסיים בטוב)."],["380","56","כמ\"ש הרמב\"ם פ\"י מהל' תשובה."],["381","57","תניא פל\"ב."]]],[1301430099,"שמגלה מעלתם של ישראל לבאי עולם<sup data-n=\"382\">58</sup> — \"כל המכבד את התורה גופו מכובד על הבריות\", שע\"י שהאדם מכבד את התורה, ה\"ז פועל שגם \"בריות\" יכירו מעלתו, שזה מתבטא בזה שהם מכבדים את גופו<sup data-n=\"383\">59</sup>.\nט. והנה מובן ופשוט, שפעולת ה­עדות דס\"ת — לגלות ההתקשרות ה­עצמית עם הקב\"ה — היא לכל לראש בהאדם עצמו, שפועל בהאדם שבכל פעולותיו יתגלה ויורגש ענין זה, עד שיהי' ניכר בגופו הגשמי, ומזה נמשכת עדות זו גם לכל באי עולם.\nוזוהי הנתינת כח \"שלוקחים\" מזמן מתן תורתנו בחג השבועות, דנוסף על ההתעוררות בגילוי קדושת ישראל, נפש הקדושה שבו, ונוסף על התחזקות ב­\"(לוחות) הברית\" — ע\"י לימוד התורה וקיום המצות, הנה עוד ועיקר — שאז נוסף בגילוי התקשרות העצמית של ישראל עם הקב\"ה, שזה משפיע על עבו­דתו בכל כחותיו הפנימיים, ובמחשבה דבור ומעשה בכל ימי השנה,\nעד שיהי' ניכר ונגלה ב\"כל באי עולם\", שזה ישפיע ויפעול עליהם ש­יקיימו ז' מצות שלהם, שגם זה ניתן במ\"ת כמ\"ש הרמב\"ם<sup data-n=\"384\">60</sup> \"וכן צוה משה רבינו מפי הגבורה לכוף את כל באי העולם לקבל מצות שנצטוו בני נח. . כל המקבל שבע מצות ונזהר לעשותן הרי זה מחסידי אוה\"ע ויש לו חלק לעוה\"ב והוא שיקבל אותן ויעשה אותן מפני שצוה בהן הקב\"ה בתורה והודיענו על ידי משה רבינו שבני נח מקודם נצטוו בהן\",\nועי\"ז גם ממהרים ביאת משיח צדקנו ש\"יתקן<sup data-n=\"385\">61</sup> את העולם כולו לעבוד את ה' ביחד (אחד<sup data-n=\"386\">62</sup>) שנאמר<sup data-n=\"387\">63</sup> כי אז אהפוך אל עמים שפה ברורה לקרוא כולם בשם ה' ולעבדו שכם אחד\", במהרה בימינו ממש.\n<span data-k=\"q\">(משיחות ש\"פ שמיני תשמ\"ו; כ\"ה אייר תשד\"מ)</span>",[["382","58","צד השווה שבכל פרטי הבריאה, כמו התואר בריות."],["383","59","עוד י\"ל בדיוק \"גופו מכובד על הבריות\" — כי זה שהתורה \"הוא העד הנאמן כו'\" הוא על בחירת הקב\"ה בבנ\"י, וענין הבחירה הוא (בעיקר) שייך ב\"גוף החומרי הנדמה בחומריותו לגופי אוה\"ע\" (תניא פמ\"ט — ע, רע\"א)."],["384","60","הל' מלכים פ\"ח ה\"י­יא."],["385","61","רמב\"ם שם ספי\"א."],["386","62","ואולי י\"ל שזהו ע\"ד שמ\"ת לישראל הי' צ\"ל בהקדמת כאיש אחד בלב אחד (מכילתא יתרו יט, ב. הובא בפרש\"י עה\"פ. וראה ויק\"ר פ\"ט, ט. ועוד)."],["387","63","צפני' ג, ט. וראה לקו\"ש חכ\"ג ע' 103 בהערה."]]],[1301430100,"<h3>שיחה א</h3>\nא. איתא במדרש רבה ריש פרשתנו<sup data-n=\"388\">1</sup>: \"נשא את ראש בני גרשון וגו'<sup data-n=\"389\">2</sup> הה\"ד<sup data-n=\"390\">3</sup> יקרה היא מפנינים וכל חפציך לא ישוו בה. . חכם קודם למלך ישראל כו'<sup data-n=\"391\">4</sup>. . אם הי' ממזר ת\"ח קודם לכה\"ג עם הארץ שנאמר יקרה היא מפנינים. . אפילו מזה שהוא נכנס לפני ולפנים<sup data-n=\"392\">5</sup>, דבר אחר יקרה היא מפנינים מדבר בקהת וגרשון אע\"פ שגרשון בכור ומצינו שבכל מקום חלק הכתוב כבוד לבכור, לפי שהי' קהת טוען הארון ששם התורה הקדימו הכתוב<sup data-n=\"393\">6</sup> לגרשון כו'\".\nלפי פשוטו<sup data-n=\"394\">7</sup> הובא כאן הדרש הרא­שון בפירוש הפסוק \"יקרה היא מפנינים\" רק אגב הדרש השני (שהכתוב \"מדבר בקהת וגרשון\"), אבל מ\"מ מסתבר לומר, שכיון שדרש זה הובא כאן על הפסוק דפרשתנו, ומה גם שדרש זה הובא כאן בתור פירוש ראשון (לפני הפירוש ש­\"מדבר בקהת וגרשון\"), שגם דרש זה נוגע להבנת גדר מעלת התורה המרומז בפרשתנו (כדרש השני).\nב. ויובן בהקדים ביאור לשון ה­רמב\"ם, שהביא תוכן מאמר המדרש (ש­מקורו בש\"ס<sup data-n=\"395\">8</sup>) בהל' ת\"ת<sup data-n=\"396\">9</sup>, וז\"ל: \"ב­שלשה<sup data-n=\"397\">10</sup> כתרים נכתרו ישראל כתר תורה וכתר כהונה וכתר מלכות, כתר כהונה זכה בו אהרן כו' כתר מלכות זכה בו דוד כו' כתר תורה הרי מונח ועומד ומוכן לכל ישראל כו' שמא תאמר ש­אותם הכתרים גדולים מכתר תורה הרי הוא אומר<sup data-n=\"398\">11</sup> בי מלכים ימלוכו ורוזנים יחוקקו צדק בי שרים ישורו הא למדת שכתר תורה גדול משניהם\", ובהלכה הבאה ממשיך \"אמרו חכמים ממזר ת\"ח קודם לכהן גדול עם הארץ שנאמר יקרה היא מפנינים, מכהן גדול שנכנס לפני ולפנים\".\nוצריך ביאור: למה חילק הרמב\"ם זה ד\"אמרו חכמים ממזר ת\"ח קודם כו'\" בהלכה בפ\"ע<sup data-n=\"399\">12</sup>, דלכאורה מאמר זה אינו אלא סיום וראי' לתוכן ההלכה הקודמת ש\"כתר תורה גדול משניהם\"<sup data-n=\"400\">13</sup>. ומזה שהרמב\"ם כתבו בהלכה בפ\"ע משמע,",[["388","1","במדב\"ר פ\"ו, א."],["389","2","פרשתנו ד, כב."],["390","3","משלי ג, טו."],["391","4","מקורו בירושלמי הוריות פ\"ג ה\"ה (כצויין במת\"כ שם)."],["392","5","מקורו בהוריות יג, א (כצויין במת\"כ). וההוספה במדרש שם \"סברין מימר לפדות להחיות ולכסות הא לישיבה לא אמר רבי אבין אף לישיבה\" היא בירושלמי שם בסוף ההלכה וירושלמי שבת פי\"ב ה\"ג (כנסמן במדרש שם). וראה לקמן הערה 29."],["393","6","שנמנה בס\"פ במדבר — ד, א ואילך."],["394","7","ראה פי' מהרז\"ו כאן ד\"ה יקרה היא."],["395","8","ראה לעיל הערה 5."],["396","9","רפ\"ג."],["397","10","ראה ספרי קרח יח, כ. יומא עב, ב. קה\"ר פ\"ז, א (ב). מדרש שמואל (שוחר טוב) פכ\"ג. שמו\"ר פל\"ד, ב. תנחומא ויקהל ח בסופו. במדב\"ר פ\"ד, יג בסופו. פי\"ד, יו\"ד. יל\"ש משלי רמז תתקמא."],["398","11","משלי ח, טו­טז."],["399","12","דאף שבמקורם הם שני מרז\"ל במקומות שונים, הרי הרמב\"ם הביאם בהמשך ולראי' א' על השני. כבפנים."],["400","13","ובהל' ת\"ת לאדה\"ז רפ\"ד בא בהמשך אחד. ולכמה גירסאות כ\"ה גם ברמב\"ם שם (ראה רמב\"ם ספר המדע — ירושלים, תשכ\"ד. וראה שם עוד נוסחא שהלכה ב' היא \"שמא תאמר. . אמרו חכמים. . לפני ולפנים\")."]]],[1301430101,"שיש במאמר זה גם ענין והלכה בפ\"ע.\nוביותר אינו מובן: הרמב\"ם אינו מפרש במה \"ממזר ת\"ח קודם לכהן גדול ע\"ה\" — אע\"פ שמפורש במשנה<sup data-n=\"401\">14</sup>, שהובא שם ענין זה, ד\"כהן קודם ללוי לוי לישראל. . אימתי בזמן שכולם שווים אבל אם הי' ממזר ת\"ח וכה\"ג ע\"ה ממזר ת\"ח קודם\", בהמשך להדין<sup data-n=\"402\">15</sup> ד\"האיש קודם לאשה להחיות ולהשב אבידה כו'\"<sup data-n=\"403\">16</sup> — וברמב\"ם אין כאן שום הלכה כ\"א רק ראי' וחיזוק להלכה הקודמת.\nג. ויש לומר הביאור בזה<sup data-n=\"404\">17</sup>:\n\"כתר תורה\" מורה על ענין ה­\"רוממות\" שהתורה פועלת באדם הלומד תורה, כדברי ר' יוסף<sup data-n=\"405\">18</sup> בנוגע למ\"ת \"אי לא האי יומא דקא גרים כו'\", \"שלמדתי תורה ונתרוממתי\"<sup data-n=\"406\">19</sup> — ובזה יש ב' או­פנים (ומדריגות):\nא) התעסקות בדבר נעלה (כולל — בתורה) פועלת \"רוממות\" באדם, ולהיות שהתורה היא \"יקרה. . מפנינים\", ל­מעלה משאר הדברים הנעלים, לכן, ה­\"רוממות\" שעל ידי התורה היא למעלה משאר עניני \"רוממות\". ולפי זה, \"כתר תורה\" הוא באותו סוג וגדר של שאר ה\"כתרים\" אלא שהוא למעלה מהם.\nב) \"כתר תורה\" פועל \"רוממות\" שאין בערכה כלל בעולם, וזהו מה שארז\"ל \"מאן מלכי רבנן<sup data-n=\"407\">20</sup>. . דכתיב בי מלכים ימלוכו\", שרק \"רבנן\" הם הם ה\"מלכים\" האמיתיים<sup data-n=\"408\">21</sup>. ולפי זה שאר ה\"כתרים\" אינם נחשבים כלל בערך \"כתר תורה\".\nוכמבואר בתורה אור<sup data-n=\"409\">22</sup> במעלת עסק התורה על קיום המצות, שאדם המקיים מצוות הרי הוא \"כעבד המקיים מצות ה­מלך ועושה דבריו\", אבל בלימוד התורה באופן שמכוון לאמיתתה של תורה — דברי התורה הנלמדים הם דבר ה', דברי תורה שמוציא בפיו<sup data-n=\"410\">23</sup> הרי הם דברי ה', וכמ\"ש \"ואשים דברי בפיך<sup data-n=\"411\">24</sup>, דברי ממש כי דבר ה' זו הלכה<sup data-n=\"412\">25</sup> היא היא הנגלית בו והיא המדברת מתוך גרונו\".\nוזהו שלימות הענין ד\"כתר תורה\", שהרוממות וה\"מלכות\" אינן שלו, אלא של התורה עצמה (המתגלית על ידו), ובלשון אדה\"ז שם, ש\"לכן נאמר על ה­תורה בי מלכים ימלוכו ואמרינן מאן מלכי רבנן. . כי להיותו בביטול אל דבר ה' ורצונו וחכמתו, ואינו תופס מקום מצד עצמו כלל, הנה דבר המלך הוא השלטון<sup data-n=\"413\">26</sup> והוא בחי' מלך שגוזר ואומר כו'\".\nד. ויש לומר, שזהו תוכן החילוק בין שתי ההלכות ברמב\"ם:\nבהלכה הא' מדבר בפעולת עסק ה­תורה באדם שהיא בדומה לפעולת שאר דברים נעלים, שבאופן זה הרי כתר תורה הוא באותו סוג דכתר כהונה וכתר מלכות (שהמלך וכהן גדול מובדלים ונעלים משאר העם), עד שאפשרי קס\"ד",[["401","14","הוריות יג, א."],["402","15","במשנה הקודמת — הוריות שם."],["403","16","וקדימה זו הביא בהל' מתנות עניים ספ\"ח."],["404","17","ראה ג\"כ (באו\"א קצת) לקו\"ש חכ\"ח ע' 107 ואילך."],["405","18","פסחים סח, ב."],["406","19","פרש\"י שם."],["407","20","כ\"ה בתו\"א (דלקמן בפנים), ע\"פ גיטין סב, סע\"א."],["408","21","וראה זח\"ג רנג, ב."],["409","22","וישב כז, ב. ולהעיר מתניא פכ\"ג."],["410","23","ראה גם לקו\"ת פרשתנו כב, ריש ע\"ב. שם כה, ב. ועוד."],["411","24","ישעי' נא, טז."],["412","25","שבת קלח, ב."],["413","26","ע\"פ קהלת ח, ד."]]],[1301430102,"שאותם הכתרים גדולים מכתר תורה, וצריכים להודיע שכתר תורה גדול משניהם, הרוממות שע\"י התורה היא ל­מעלה מכהונה ומלכות.\nמשא\"כ בהלכה הב' מדבר באופן ה­שני ב\"כתר תורה\", שהוא סוג אחר ל­גמרי<sup data-n=\"414\">27</sup>, ולא מאותו הסוג דכתר כהונה וכתר מלכות<sup data-n=\"415\">28</sup>. וזהו הטעם שענין זה מודגש בכך ש\"ממזר ת\"ח קודם לכהן גדול עם הארץ שנאמר יקרה היא מפני­נים, מכהן גדול שנכנס לפני ולפנים\", היינו שיש מעלה בלימוד התורה על כניסת כה\"ג לפני ולפנים, דאע\"פ שזהו המקום הכי מקודש בעולם, ששם היא השראת השכינה, ובמילא מובן שזהו האופן הכי קרוב שאדם יכול להתקרב אל הקב\"ה, מ\"מ, אין זה בערך ללימוד התורה, כי הכניסה לפני ולפנים היא רק כעבד או שר הנכנס אל המלך וקרוב אל המלך, אבל ע\"י לימוד התורה בביטול הרי לומד התורה הוא בגדר \"מלך\" עצמו, \"מאן מלכי רבנן\", כנ\"ל<sup data-n=\"416\">29</sup>.\n[ועוד יש לומר, שזה מודגש גם בזה ש\"ממזר ת\"ח קודם לכה\"ג עם הארץ\", כי רק מצד העילוי שלא בערך הנפעל על ידי התורה, הרי גם גברא שהוא מה­ירודים ביותר שבעשרה יוחסין<sup data-n=\"417\">30</sup> שעליו נאמר \"לא יבא. . בקהל\"<sup data-n=\"418\">31</sup> — הוא ל­מעלה מכהן גדול (ע\"ה) הנכנס לפני ולפנים].\nה. ובזה יובן גם החילוק בין שתי הדרשות הנ\"ל שבמדרש בכתוב \"יקרה היא מפנינים\":\nלפירוש הא' שבמדרש, קאי על שלי­מות הרוממות שבתורה, שאין כערכה כלל בשום דבר בעולם<sup data-n=\"419\">32</sup>, וזהו מה ש­אומר בסיום הענין \"אם הי' ממזר ת\"ח קודם לכה\"ג עם הארץ שנאמר יקרה היא מפנינים. . אפילו מזה שהוא נכנס לפני ולפנים\", כנ\"ל.\nמשא\"כ לפירוש השני שבמדרש, קאי",[["414","27","ובפרט ע\"פ פי' הבאר שבע (הוריות שם ד\"ה וכהן גדול עם הארץ) — הובא בש\"ך יו\"ד (סרמ\"ו סקי\"ד. סרנ\"א סקט\"ו) — \"לאו דוקא עם הארץ אלא שאינו שוה בחכמה לישראל\" (וראה שו\"ת כנסת יחזקאל או\"ח ס\"ז). ומוכח דהא דממזר ת\"ח מדובר במדריגה נעלית ביותר בתורה, כבפנים."],["415","28","היינו בהחפצא דכתר כהונה וכתר מלכות בפ\"ע, אבל בפועל בנוגע לדוד קשורה מלכותו עם ביטולו (וראה לקמן ס\"ו), כמ\"ש \"אם לא שויתי ודוממתי\" (תהלים קלא, ב ובראב\"ע שם). וראה רמב\"ם סוף הל' לולב. לקו\"ת שבהערה 40."],["416","29","ולכן לא כתב הרמב\"ם דממזר ת\"ח קודם בהדינים הנאמרים בהוריות שם שהביא בהל' מת\"ע, כי כאן כוונתו \"קודם\" — לכבוד<sup data-n=\"e10\">*</sup>, ע\"ד מ\"ש בירו­שלמי ובמדב\"ר (שבהערה 5) \"אף לישיבה\". וזהו החילוק בין ההו\"א והמסקנא שם, שההו\"א \"סברין מימר לפדות להחיות ולכסות\", כי זהו בענינים שלא יאבד התועלת שישנו ע\"י הת\"ח, התורה שבו, אבל בענין הישיבה וכבוד סברין למימר שהכה\"ג הוא תחילה, כי קדושתו גדולה, וקמ\"ל \"אף לישיבה\", כי קדושת התורה שגדולה מכהן גדול היא באופן שהיא נעשית כל מציאותו של הת\"ח (עד שנעשה כ\"מלך\" עצמו, כבפנים)."],["417","30","קידושין רפ\"ד. וראה גם מקומות שבהערה 5."],["418","31","תצא כג, ג. ועפ\"ז יומתק הטעם שנקט \"ממזר\" ולא נתין או גר וכו' שלמטה מממזר בסדר דעשרה יוחסין (כנסמן בהערה הקודמת). ואכ\"מ."],["419","32","עפ\"ז יובן הטעם שדוקא בפי' הא' במדרש מביא גם המשך הכתוב \"וכל חפציך לא ישוו בה\", משא\"כ בפי' הב' שבמדרש מביא רק התחלת הכתוב \"יקרה היא מפנינים\", כי רק בפירוש הא' מדובר במעלת התורה שבאין ערוך לכל שאר ענינים, \"כל חפציך לא ישוו בה\"."],["e10","*","ולהעיר מהגירסא ברמב\"ם (הנ\"ל הערה 13) \"חשוב\" במקום \"קודם\"."]]],[1301430103,"פסוק זה על אופן הא' הנ\"ל ב\"רוממות\" דתורה, דגם כשאין לימוד התורה של ה­אדם בתכלית השלימות (עד שיהי' בגדר \"מאן מלכי רבנן\"), מ\"מ, עצם הענין ש­אדם לומד תורה פועל בו רוממות של­מעלה משאר כל סוגי רוממות שבעולם.\nוזהו שאומר בפירוש זה \"אע\"פ ש­גרשון בכור ומצינו שבכל מקום חלק הכתוב כבוד לבכור, לפי שהי' קהת טוען הארון ששם התורה הקדימו הכתוב לגרשון כו'\" — והיינו (א) ההשוואה היא (רק) לבכור, (ב) בזה גופא אומר רק ש\"הקדימו הכתוב\", (ג) מעלת קהת כאן היא (לא שהם לומדי תורה, אלא רק) \"טוען הארון\" — אלא שגדולה מעלת התורה כל כך, שאפילו מי שהוא \"טוען הארון ששם התורה\" יש בו מעלה גם על בכור (אף \"שבכל מקום חלק הכתוב כבוד לבכור\").\nועפ\"ז יש לומר, שזוהי כוונת המדרש כאן בהביאו ב' הפירושים ב\"יקרה היא מפנינים\", ומסיים \"ד\"א יקרה היא מפני­נים מדבר בקהת וגרשון כו'\", שתחילה מקדים שאמיתית ענין הרוממות שבתורה הוא ע\"ד הענין ד\"ממזר ת\"ח קודם לכהן גדול. . שהוא נכנס לפני ולפנים\", אבל מה שנוגע כאן (בקהת וגרשון) הוא רק המדריגה הפחותה במעלת התורה (כפי­רוש השני שבמדרש).\nוהטעם: בפסוק נאמר \"נשא את ראש בני גרשון גם הם\", ש\"נשא\" מורה על ענין ההתנשאות<sup data-n=\"420\">33</sup> ורוממות, וכיון שגם אצל בני גרשון (אף שאין ענינם תורה) ישנו ענין ההתנשאות (אלא שהם טפלים בזה אל בני קהת, \"גם הם\") — עכצ\"ל, שהכוונה לרוממות כזו שהיא בערך ל­שאר עניני רוממות, אלא שהיא למעלה מהם, כנ\"ל.\nו. ובעומק יותר יש לומר, שגם הפי­רוש הראשון שבמדרש בא לפרש כתוב דילן ד\"נשא את ראש בני גרשון גם הם\".\nויובן זה בהקדם תוספת ביאור ב­חילוק בין שני האופנים הנ\"ל, בענין ה­רוממות הנפעל על ידי לימוד התורה.\nשני אופנים אלה, אף שבכללות שני­הם באים על ידי לימוד התורה, הרי ב­פרטיות ישנו הפרש ביניהם: הענין הא' בא (בעיקר) ע\"י עצם לימוד התורה בהבנה והשגה; אבל הענין הב' תלוי בזה שהאדם לומד תורה בתכלית הביטול<sup data-n=\"421\">*33</sup>, שרק אז הדברי תורה שלומד הם גילוי דבר ה'.\nוזהו הטעם שהוצרכה להיות הקדמת נעשה לנשמע קודם קבלת התורה<sup data-n=\"422\">34</sup>, וכן צ\"ל הקדמת נעשה לנשמע לפני לימוד התורה בכל עת ובכל מקום, וכביאור",[["420","33","ראה במדב\"ר פ\"ד, יב: אינו אומר פקוד אלא נשא את ראש לשון נשיאות כו'. וראה אברבנאל ס\"פ במדבר. גו\"א על פרש\"י ריש פרשתנו. מפרשי התורה ר\"פ תשא. ועוד. וראה בכל הנ\"ל אוה\"ת פרשתנו (כרך ו) ע' א'תשלה ואילך."],["421","*33","להעיר מעירובין (יג, ב): \"מפני מה זכו ב\"ה לקבוע הלכה כמותן מפני שנוחין ועלובין היו כו' ולא עוד אלא שמקדימין דברי ב\"ש לדבריהן\", שמצד הביטול הגיעו לאמיתתה של תורה (ראה בארוכה לקו\"ש חכ\"א ע' 114 ואילך), והוא אמיתית הענין ד\"כתר תורה\" (ראה אגה\"ק סכ\"ט, ע\"פ מגילה כח, ב)."],["422","34","ובפרטיות יותר מצינו בהקדמה למ\"ת שני ענינים: א) אמירת ה' (יתרו יט, ו) \"ואתם תהיו לי ממלכת כהנים וגו'\", שהוא הקדמה לענין הא' שבכתר תורה (ראה רש\"י שם \"שרים\", ובמדרשים \"כהנים\", \"כהן גדול\" — ראה מכילתא עה\"פ. אגדת בראשית פע\"ט (פ). בעה\"ט עה\"פ). ב) הקדמת נעשה לנשמע, שהיא הקדמה והכנה לענין הב' שבכתר תורה — שבא ע\"י ביטול דוקא."]]],[1301430104,"רבינו הזקן<sup data-n=\"423\">35</sup> ד\"מלת נשמע הוא להיות בטל לדבר תורה המדברת בפיו שהיא רצונו וחכמתו יתברך, כאילו שומע שה­שכינה מדברת מתוך גרונו כמ\"ש<sup data-n=\"424\">36</sup> תען לשוני אמרתך. . ביטול רצון לגמרי\", וביטול זה בא ע\"י הקדמת \"נעשה\", שזהו ענין הביטול \"לבעל הרצון. . בעצמו\".\nוזהו מה שארז\"ל<sup data-n=\"425\">37</sup> גדול לימוד ש­מביא לידי מעשה, שהגדלות שבלימוד הוא מה שמביא לידי מעשה (מלשון \"מעשין על הצדקה\"<sup data-n=\"426\">38</sup>), שהו\"ע הכפי' והביטול.\nובפשטות: הבחינה שלימוד התורה הוא בביטול אמיתי היא בזה שהלימוד עצמו מביאו שינתק את עצמו מלימודו (אף שיש בזה הרבה תענוג וחיות) וית­עסק בענינים של מעשה. ואז ישנה ה­גדלות שבלימוד, כי כאשר לומד מתוך ביטול, אזי דברי תורה שלומד הם דבר ה' המתגלה על ידו, והוא בגדר \"מלך\", מאן מלכי רבנן.\n[ובעומק יותר יש לפרש מרז\"ל גדול לימוד שמביא לידי מעשה, דכאשר לומד בביטול גמור, ה\"ז פועל גם על המעשה שלו, שקיום המצוות שלו יהי' באותו הביטול כמו לימוד התורה, שאינו מקיים המצוות רק כעבד המקיים מצוות המלך (שאין זה ביטול לגמרי, כי ישנה מציאות העבד, אלא שהוא עושה גזירת המלך, כנ\"ל ס\"ג), אלא שהוא בתכלית הביטול, ע\"ד מרז\"ל<sup data-n=\"427\">39</sup> \"מנפשי' כרע\", ד­היינו שאין זה — שישנו אדם העושה רצון ה', אלא שזהו כאילו שרצון ה' נעשה מאליו בלי \"גברא\" העושה זאת, כי האדם בטל בתכלית אל רצון השם, עד שכאילו אין שום מציאות מלבד רצונו יתברך]<sup data-n=\"428\">40</sup>.\nז. וע\"פ זה יש לומר, שענין זה מוד­גש ב\"נשא את ראש בני גרשון גם הם\":\nזה שאמיתית הרוממות של תורה נפעלת ע\"י לימוד התורה בביטול, שזהו כאשר הלימוד מביא לידי מעשה דוקא — נראה בזה שאחרי בני קהת באים בני גרשון, דגרשון מורה על קיום המצות, כמבואר בכ\"מ<sup data-n=\"429\">41</sup> (והם נשאו את היריעות כו', ודוקא לאחר הקמת המשכן ע\"י בני גרשון ובני מררי באו בני קהת והכניסו את הארון והכלים בתוך המשכן<sup data-n=\"430\">42</sup>), ולכן דוקא לאחרי שישנו ענינם של בני גרשון, ה\"ז מדגיש אמיתית נשיאות \"בני קהת\" (תורה).\nוזהו שהכתוב מדייק \"נשא את ראש בני גרשון גם הם\", שאין המדובר ב­מעלת בני גרשון כשלעצמם (דהיינו מצד קיום המצוות עצמו), אלא בזה שהם טפלים ובטלים אל בני קהת, ענין ה­מעשה הבא כתוצאה מלימוד [ועוד זאת, ד\"גם הם\" פירושו, שגם ב\"מעשה\" נמשך הביטול שבתורה, כנ\"ל].\nוע\"פ הנ\"ל יש לבאר ג\"כ הרמז בזה שדוקא פרשה זו, המדברת בבני גרשון, נקראת בשם \"נשא\" סתם — אף שה\"נשא\" דבני קהת הוא למעלה יותר מדבני",[["423","35","לקו\"ת שה\"ש כב, א."],["424","36","תהלים קיט, קעב."],["425","37","קידושין מ, ב. ב\"ק יז, א."],["426","38","ראה ב\"י לטיו\"ד סרמ\"ח."],["427","39","ירושלמי ברכות פ\"ב סה\"ד, הובאה בתוד\"ה עיון — שבת קיח, ב."],["428","40","ראה לקו\"ת ברכה (צט, ג) שגם כללות ענין הנשיאות הוא ענין שלא ע\"פ טעם ודעת (הבורח מן הכבוד כו'), ומקשר זה שם עם ענין הקדמת נעשה לנשמע. עיי\"ש. וי\"ל, שכיון ש\"בי מלכים ימלוכו\", לכן כל נשיאות קשורה דוקא עם ענין הביטול (הבורח מן הכבוד כו')."],["429","41","ראה לקו\"ת פרשתנו כג, ג. ובכ\"מ."],["430","42","ראה פרש\"י בהעלותך י, כא."]]],[1301430105,"גרשון (כמודגש בקרא עצמו, \"נשא את ראש בני גרשון גם הם\") — כי רק לאחרי שישנה גם עבודת בני גרשון (באופן ד\"גם הם\"), מתגלה אמיתית ענין ה­\"נשיאות\" ורוממות שעל ידי תורה, כנ\"ל בארוכה<sup data-n=\"431\">43</sup>.\nח. והנה פרשת נשא קורין תמיד ב­סמיכות לחג השבועות, זמן מתן תורתנו, וע\"פ דברי השל\"ה<sup data-n=\"432\">44</sup> הידועים ש\"המוע­דים של כל השנה. . בכולן יש שייכות לאותן הפרשיות שחלות בהן\", מובן, שיש בפרשה זו רמז ולימוד הנוגע לחג השבועות, זמן מתן תורתנו.\n[ואף שבפשטות שייך חג השבועות לפרשת במדבר, כפסק ההלכה שלעולם קורין פ' במדבר לפני עצרת<sup data-n=\"433\">45</sup>, וכמשנ\"ת במ\"א בארוכה<sup data-n=\"434\">46</sup>, מ\"מ, יש בפ' נשא קשר מיוחד לחג השבועות (גם יותר מפ' במדבר), שהרי פ' במדבר (א) קורין לפני עצרת, (ב) לפעמים אינה בשבת שלפני חג השבועות, אלא בשבת שלפנ\"ז<sup data-n=\"435\">47</sup> — משא\"כ פרשת נשא, אשר (א) לפעמים ( — ברובם)<sup data-n=\"436\">48</sup> קורין אותה אחרי חג ה­שבועות, ונמצא שחג השבועות חל ב­שבוע דפ' נשא, (ב) תמיד קורין אותה בשבת הסמוכה לחג השבועות, אם ב­שבת שלאחרי', שבה עולים ונכללים ימי העצרת, או בשבת שלפני'<sup data-n=\"437\">*48</sup>, שממנה מתברכין ימי חג השבועות].\nולכאורה: מבין שלשת משפחות בני לוי, קהת גרשון ומררי, עיקר מעלת התורה נמצא אצל בני קהת דוקא (שלכן הם היו טועני הארון), וא\"כ למה קורין לעולם פ' נשא (דוקא) בסמיכות לחג השבועות?\nוע\"פ משנת\"ל מובן, שאדרבה, היא הנותנת: עיקר החידוש דמתן תורה הוא (לא הבנת והשגת דברי תורה, אלא) גילוי תורת הוי', \"נתן לנו את תורתו\", והכלי לקבל תורת הוי' הוא על ידי ענין הביטול, הקדמת נעשה לנשמע<sup data-n=\"438\">49</sup>, ולימוד באופן המביא לידי מעשה (כנ\"ל) — ודוקא אז פועלת התורה ענין של \"התנשאות\" ורוממות אמיתית, \"נשא את ראש\". ולכן קורין תמיד פרשת \"נשא את ראש בני גרשון\" בסמיכות לחג השבו­עות, כיון שכאן באה לידי ביטוי מעלת התורה הנלמדת בביטול דוקא, כנ\"ל ב­ארוכה.\nט. ענין זה (מעלת לימוד התורה ב­ביטול) נרמז גם באמצע הפרשה<sup data-n=\"439\">50</sup>, בפ' קרבנות הנשיאים, שאיתא ברש\"י, שזה שנאמר \"הקריב\" שתי פעמים אצל",[["431","43","בביאור דברי המדרש כו' — ראה גם כלי יקר ריש פרשתנו. של\"ה פרשתנו שמט, ב ואילך."],["432","44","ר\"פ וישב."],["433","45","רמב\"ם הל' תפלה פי\"ג ה\"ב. טושו\"ע או\"ח סתכ\"ח ס\"ד."],["434","46","ראה לקו\"ש ח\"ח ע' 1. וש\"נ. לקו\"ש חי\"ח ע' 18 ובהערות שם."],["435","47","בקביעות \"ה\"ח\" ו\"ה\"ש\" מעוברת — כשר\"ה הוא ביום ה', בין כשחדשי חשון וכסלו הם חסרים או שלמים (טור שם). וראה פר\"ח שם סק\"ד."],["436","48","ראה לוחות שבטור שם. וידוע השקו\"ט בנוגע ללוחות אלו (פר\"ח לאו\"ח הל' ר\"ח ועוד — הובאו ונסמנו בלקו\"ש חי\"ח ע' 381 בשוה\"ג)."],["437","*48","כבקביעות שבהערה 47."],["438","49","ראה תו\"א וארא (נו, א) שזהו החידוש דמשה שאמר ונחנו מה, ביטול לגמרי (נוסף על עבודת ה­אבות שנק' עדיין עבודת עבד), ו\"לפיכך זכה שנתנה תורה על ידו בבחי' דבור. . שכינה מדברת מתוך גרונו\". ע\"ש בארוכה."],["439","50","להעיר ג\"כ שבפרשתנו מדובר אודות יום הקמת המשכן (ז, א) שהוא יום חתונתו (ראה פרש\"י עה\"פ. ובבמדב\"ר פי\"ב, ח (בסופו) ביום חתונתו זה אוהל מועד. . שחיתונין היו כו'), ובתענית (כו, ב — במשנה. וראה גם במדב\"ר שם בפי' הא') יום חתונתו זה מ\"ת."]]],[1301430106,"\"נתנאל בן צוער\"<sup data-n=\"440\">51</sup>, הוא כי<sup data-n=\"441\">52</sup> \"בשביל ב' דברים זכה להקריב שני לשבטים, אחת שהיו יודעים בתורה שנאמר<sup data-n=\"442\">53</sup> ומבני יששכר יודעי בינה לעתים (ואחת שהם נתנו עצה לנשיאים להתנדב קרבנות הללו)\".\nובמדרש רבה בפרשה זו<sup data-n=\"443\">54</sup> איתא \"בא נשיא יששכר והקריב על שם התורה, לפי שהם אהבו את התורה יותר מכל השבטים שנאמר ומבני כו' לדעת מה יעשה ישראל באיזה יום יעשו מועדים ראשיהם מאתיים אלו מאתיים ראשי סנהדראות שהי' שבט יששכר מעמיד וכל אחיהם על פיהם שהיו מסכימים הלכה על פיהם ואומר<sup data-n=\"444\">55</sup> ויט שכמו לסבול שהיו סובלים עול תורה ויהי למס עובד שכל מי שהי' טועה בהלכה היו שואלים אותה לשבט יששכר והם מבארים אותה להם\".\nאבל מ\"מ, אף שנשיא יששכר הקריב תחלה (מצד מעלת התורה), גם לפני שבט ראובן הבכור<sup data-n=\"445\">56</sup>, מ\"מ הקריב שני לשבטים, ולא ביום ראשון.\nוהביאור בזה:\nאף שיששכר הקריב על שם התורה, כנ\"ל, מ\"מ הרי עיקר מעלת התורה ה­מביאה לידי גדלות ונשיאות הוא כאשר הלימוד קשור עם ביטול מציאותו של ה­לומד [וכמו שהי' ביששכר, דכתיב בי'<sup data-n=\"444\">55</sup> \"ויט שכמו לסבול\", שהיו סובלים עול התורה, וכמרומז גם בכוונה של \"ולזבח השלמים בקר שנים — כנגד שתי תורות המקרא והמשנה שכל מי שמבקר וזובח יצרו לעשות ככל הכתוב בהן הוא עושה שני שלומות שלום למעלה ושלום ל­מטה\"<sup data-n=\"447\">57</sup>], וביטול זה של יששכר התבטא בזה שהוא הקריב שני, והמקריב הראשון הי' נחשון בן עמינדב שהו\"ע (נחשון — היינו) המסירת נפש, \"למה נקרא שמו נחשון על שם שירד תחלה לנחשול שבים\" ש\"קפץ נחשון לתוך גלי הים וירד\"<sup data-n=\"448\">58</sup>, כי ידע ש\"בהוציאך את העם מ­מצרים תעבדון את האלקים על ההר הזה\"<sup data-n=\"449\">59</sup>, ולכן קפץ במסירת נפש לים כדי להתקרב לקראת הר סיני לקבלת ה­תורה<sup data-n=\"450\">60</sup>.\nיו\"ד. ויש לומר, שזהו הרמז בג' אופני הקביעות דקריאת פרשת נשא: א) לפעמים קורין נשא לפני חג השבועות, ב) ברוב השנים לאחרי חג השבועות, ג) כאשר פ' נשא היא ב' שבועות שלמים, וחג השבועות חל (בחו\"ל) ביום ו' ויום ש\"ק<sup data-n=\"451\">61</sup>:\nקריאת פ' נשא לפני חג השבועות הוא הוראה ונתינת כח שבכדי להגיע ל­הגדלות ו\"נשיאות ראש\" דתורה צריך להיות לפנ\"ז תוס' התחזקות בענין הבי­טול שלפני מ\"ת, הקדמת נעשה לנשמע; קריאת פ' נשא אחרי חג השבועות הוא הוראה ונתינת כח על הביטול שבמעשה שלאחרי מ\"ת, שהגדלות והנשיאות שב­תורה צריכה לבוא בביטול שבמעשה; וכאשר חג השבועות הוא ביום ועש\"ק",[["440","51","פרשתנו ז, יח­יט."],["441","52","וראה ספרי זוטא שם, יח."],["442","53","דה\"א יב, לב."],["443","54","פי\"ג, טו­טז."],["444","55","ויחי מט, טו."],["445","56","כבספרי מדרש ורש\"י עה\"פ."],["444","55","ויחי מט, טו."],["447","57","פרשתנו שם, כג. במדב\"ר פי\"ג שם."],["448","58","במדב\"ר שם, ז. שם, ד."],["449","59","שמות ג, יב."],["450","60","גם בנוגע ליהודה נאמר שמצד ההודאה והביטול שלו הקריב ראשון (במדב\"ר שם, ג). אבל לא מודגש בזה שהביטול קשור לתורה."],["451","61","כקביעות שנה זו (תשמ\"ט) — שנת הדפסת השיחה."]]],[1301430107,"וש\"ק היינו שפ' נשא היא הן בשבוע שלפני חג השבועות והן בשבוע שלאחרי חג השבועות, ה\"ז הוראה על חיבור שני הענינים יחד, וזוהי השלימות דנשיאות התורה, שישנו הביטול דהקדמת נעשה לנשמע שלפני מ\"ת, והביטול שבמעשה (גדול לימוד שמביא לידי מעשה) לאחרי מ\"ת.\n<span data-k=\"q\">(משיחת ש\"פ נשא תשל\"ה)</span>"],[1301430108,"<h3>שיחה ב</h3>\nא. בפסוק<sup data-n=\"452\">1</sup> \"יברכך ה' וישמרך\" נאמרו בחז\"ל (ספרי, תנחומא, במדבר רבה ועוד) הרבה פירושים בתוכנה של הברכה ד\"יברכך\" \"וישמרך\"<sup data-n=\"453\">2</sup>, אבל רש\"י בפירושו על התורה בחר באחד מהם, כדלקמן. וביחד עם זה הזכיר ומסיים \"שהרבה מדרשים דרשו בו\" — ומגדירם שהם מדרש.\nב. בתחלת הכתוב מעתיק רש\"י יברכך ומפרש שיתברכו נכסיך.\nולכאורה יש לתמוה: גם ע\"פ פשוטו של מקרא מסתבר לומר שברכת כהנים היא ברכה כללית ביותר — ומדוע איפוא בחר רש\"י בפירוש זה \"שיתברכו נכ­סיך\", ברכה המוגבלת רק לנכסי האדם, ולא פירש שהיא ברכה כללית, שהאדם יתברך בכל עניניו<sup data-n=\"454\">3</sup>?\nוביותר תמוה: הפירוש הראשון ב­ספרי כאן עה\"פ הוא \"יברכך ה', בברכה המפורשת [בתורה, במקום אחר]. . ברוך<sup data-n=\"455\">4</sup> אתה בעיר וברוך אתה בשדה וגו' ברוך טנאך ומשארתך ברוך אתה בבואך וגו' ובאו<sup data-n=\"456\">5</sup> עליך כל הברכות האלה והשיגוך אימתי כי תשמע בקול ה' אלקיך\" — ולפ\"ז הרי ב\"יברכך\" נכללת הברכה לא רק בנכסי האדם<sup data-n=\"457\">6</sup>, אלא גם בנוגע לגופו ולפרי בטנו<sup data-n=\"458\">7</sup>; ועוד זאת — גם ברכות על ענינים רוחניים של ה­מתברכים (כמ\"ש שם בהמשך הכתובים<sup data-n=\"459\">8</sup> \"יקימך ה' לו לעם קדוש גו'\" ועוד). ואמאי שבק רש\"י פירוש זה, התואם, לכ­אורה, לפשט הכתוב (שהמדובר בברכות השם המפורשות בתורה (במקום אחר), ובברכות כלליות ביותר) — ומביא הפי­רוש \"שיתברכו נכסיך\"<sup data-n=\"460\">9</sup>?\nגם יש לדייק בלשון רש\"י \"שיתברכו נכסיך\": מקורו של פירוש זה הוא ב­ספרי כאן, אבל שם הלשון \"יברכך ב­נכסים\". ואינו מובן, א) מה ראה רש\"י לשנות מלשון הספרי ומתוכנו ולכתוב \"יברכך, שיתברכו נכסיך\" שכבר יש לך, ב) מהו שחוזר עוה\"פ \"שיתברכו\", ג) מצינו כעין זה בפרש\"י לעיל<sup data-n=\"461\">10</sup>, גבי אב­רהם, שפירש \"ואברכך — בממון\", ולכ­אורה הו\"ל לפרש בשני המקומות בשווה.",[["452","1","פרשתנו ו, כד."],["453","2","וכן בשאר הברכות דברכת כהנים."],["454","3","ראה מדרש לקח טוב כאן. ועוד. ולהעיר מתיב\"ע כאן \"בכל עסקך\". וראה הערה 20."],["455","4","תבא כח, ג­ו. ובבמדב\"ר כאן מביא לפנ\"ז גם כתוב דפ' עקב (ז, יד) \"ברוך תהי' מכל העמים\". וראה הערה הבאה."],["456","5","תבא שם, ב. וראה מפרשי הספרי והמדרש שם בנוגע לסדר הכתובים."],["457","6","ראה בכור שור כאן. מלבי\"ם. ועוד."],["458","7","תבא שם, ד."],["459","8","שם, ט."],["460","9","להעיר, שבדפוס ראשון דפרש\"י (ועד\"ז ב­שני כת\"י רש\"י שתח\"י), בסיום ד\"ה \"וישמרך\" איתא \"ד\"א יברכך בבנים וישמרך בבנות שהבנות צריכות שימור\" (והוא מתנחומא ובמדב\"ר כאן).\n[ולהוסיף, שלגירסא זו נמצא, שכוונת רש\"י בסיום פירושו — \"והרבה מדרשים כו' בספרי\", היינו גם על \"יברכך\" (אבל בא' מכת\"י רש\"י הנ\"ל הובא פירוש זה (\"יברכך בבנים כו'\") אחרי שמסיים \"ו­הרבה מדרשים כו'\", ומשמע להיפך, שקאי רק על \"וישמרך\"). וראה לקמן הערה 30]."],["461","10","לך יב, ב ד\"ה ואברכך. וראה שם ד\"ה ואעשך."]]],[1301430109,"ג. ויש לומר הביאור בזה:\nכבר מפורש לעיל בפ' בחוקותי רי­בוי הברכות המגיעות לבנ\"י כשמקיימים תומ\"צ. וכאשר לומדים ע\"ד מצות ברכת כהנים, שיש ברכה מיוחדת שעל הכהנים לברך את בנ\"י — מתעוררת השאלה: מהו החידוש בברכת כהנים לגבי ה­ברכות שהקב\"ה כבר הבטיח להם ב­תורתו<sup data-n=\"462\">11</sup>?\nואין לומר שכל החידוש בברכת כהנים הוא, שבה מתברכים גם אלה מבנ\"י שמצד הנהגתם בשמירת התומ\"צ אינם ראויים לברכה — כי פשיטא שיש חידוש בברכת כהנים גם לשומרי תומ\"צ, המובטחים בכל הברכות המנויות בפ' בחוקותי; ואדרבה — מסתבר שלהם ית­רון בברכה מיוחדת זו<sup data-n=\"462\">11</sup>.\nוזהו הטעם שלא פירש רש\"י \"יברכך\" כהפירוש (הראשון) בספרי, דקאי על \"ברכה המפורשת\" — דאדרבה, היא ה­נותנת שאאפ\"ל (ע\"ד הפשט) שזוהי ה­ברכה דברכת כהנים: מכיון שזוהי ברכה \"מפורשת\" (שהקב\"ה הבטיח בתו­רתו ברכה זו) — הרי מובן שאין זו ה­ברכה שהכהנים מברכים את בני ישראל.\nאמנם מטעם זה גם אין מקום לפרש \"יברכך בנכסים\" (או \"בממון\", או אפילו \"בעושר\") כבבמדב\"ר ובתנחומא — כי גם ברכה זו כבר כלולה בברכות המנויות בפ' בחוקותי; ויתירה מזו — לעיל בפר­שתנו<sup data-n=\"464\">12</sup> נאמר שהשכר על נתינת מתנות כהונה הוא — \"לו יהי' ממון הרבה\".\nולכן פרש\"י \"שיתברכו נכסיך\", ו­היינו, שבנכסים שיש לו להאדם כבר (\"נכסיך\"), תשרה ברכה מיוחדת, שית­ברכו ויתרבו יותר מכפי מידתם וטבעם הם, והיינו ברכה והשפעה שלמעלה מדרכי הטבע. ע\"ד שמצינו ביצחק — \"וימצא בשנה ההיא מאה שערים\"<sup data-n=\"465\">13</sup>, דאע\"פ ש\"הארץ קשה והשנה קשה\", \"עשתה על אחת שאמדוה מאה\"<sup data-n=\"466\">14</sup> — ברכה שלמעלה מדרך הטבע<sup data-n=\"467\">15</sup>.\nוזהו החידוש בברכת כהנים לגבי הברכות דפ' בחוקותי, דעיקר הברכות דפ' בחוקותי הוא בענין ריבוי הטוב בכמות (\"דיש מרובה\"<sup data-n=\"468\">16</sup>) שיושפע לבנ\"י ע\"י קיום התומ\"צ, משא\"כ ברכה זו היא מיוחדת — שהנכסים שכבר נמצאים ב­רשותו של האדם, הם עצמם מתברכים ומתרבים<sup data-n=\"469\">17</sup> פי כמה, באופן שלמעלה מהטבע<sup data-n=\"470\">18</sup>.\nואע\"פ שכבר מצינו כעין ברכה זו גם בפ' בחוקותי, כפרש\"י עה\"פ<sup data-n=\"471\">19</sup> \"ואכלתם",[["462","11","ראה גם פענח רזא ומושב זקנים כאן (ותירוצם אינו ע\"ד הפשט כלל)."],["462","11","ראה גם פענח רזא ומושב זקנים כאן (ותירוצם אינו ע\"ד הפשט כלל)."],["464","12","ה, י ובפרש\"י."],["465","13","תולדות כו, יב."],["466","14","פרש\"י שם."],["467","15","וראה לקו\"ש ח\"ה (ע' 122 ואילך), שי\"ל, שלפירוש הב' ברש\"י שם, \"אומד זה למעשרות הי'\", נתרבתה התבואה \"מאה שערים\" לאחרי שכבר צמחה (שהרי האומד למעשרות הוא לאחרי צמיחת התבואה)."],["468","16","רש\"י בחוקותי כו, ה. וראה רש\"י שם, י ד\"ה וישן."],["469","17","משא\"כ בבחוקותי שהברכה בתבואה שכבר צמחה היא רק ש\"הפירות יהיו משתמרין\" (רש\"י שם, י ד\"ה ואכלתם), אבל לא ברכה וריבוי."],["470","18","אף שגם הברכות דפ' בחוקותי הן (בכלל) למעלה מן הטבע (ראה בארוכה לקו\"ש חי\"ט ע' 116 ואילך. חי\"ז ס\"ע 325 ואילך) — מ\"מ לא מצינו ברכה כזו, \"שיתברכו נכסיך\".\n[ואף שפרש\"י (שם, ד) שאילני סרק \"עתידין לעשות פירות\" — הרי מדגיש \"עתידין\", שברכה זו תתקיים רק לעת\"ל]."],["471","19","כו, ה."]]],[1301430110,"לחמכם לשובע\" — \"אוכל קימעא והוא מתברך במעיו\" — אין ברכה זו מגיעה להפלאת הברכה \"שיתברכו נכסיך\": זה שהמזון מתברך שלא ע\"פ טבע ב\"מעיו\" של אדם המקיים תומ\"צ, א) אינו גלוי לעין כלל, ב) פעולת הברכה היא בגופו של זה שעמל בתורה ושמר המצוות; אבל בברכת כהנים א) הברכה גלוי לכל ב) גם נכסי האדם, שהם חוץ להאדם המקיים תומ\"צ, יתברכו ויתרבו שלא ע\"פ טבע.\nוהטעם שרש\"י מדייק \"(שיתברכו) נכסיך\" — ולא \"ממונך\" — הוא לפי ש­\"נכסים\" כוללים כל סוגי הרכוש<sup data-n=\"472\">20</sup>, שב­כולם תשרה ברכה נוספת זו.\nד. פירוש רש\"י על סיום הכתוב \"וישמרך\": שלא<sup data-n=\"473\">21</sup> יבואו עליך שודדים ליטול ממונך שהנותן מתנה לעבדו אינו יכול לשמרו מכל אדם וכיון שבאים לסטים עליו ונוטלין אותה ממנו מה הנאה יש לו במתנה זו אבל הקב\"ה הוא הנותן הוא השומר. והרבה מדרשים דרשו בו בספרי<sup data-n=\"474\">22</sup>.\nוהנה הטעם שרש\"י מוציא פירושו של \"וישמרך\" מידי פשוטו — שמירת גוף ה­אדם עצמו<sup data-n=\"475\">23</sup> [ע\"ד ברכת הקב\"ה ליעקב \"ושמרתיך בכל אשר תלך\"<sup data-n=\"476\">24</sup> (וכפשטות הלשון \"וישמרך\"<sup data-n=\"477\">25</sup>, שקאי על האדם עצמו)] — ומפרשו בענין שמירת ממון ה­אדם — יש לומר:\nאת\"ל שזוהי ברכה על שמירת גוף האדם, הו\"ל להקדים ברכה זו ל\"יברכך\" (שהיא ברכה רק על נכסי האדם), כמובן בפשטות, שראשית כל צריך האדם להיות שלם ובריא, ורק אח\"כ יש מקום לברך אותו בנכסים וממון;\nולכן פרש\"י ש\"וישמרך\" כאן הוא המשך ל\"יברכך\", והיינו שהנחיצות ב­שמירה זו היא מחמת ברכת \"יברכך\": לאחרי שנכסי האדם נתברכו (\"יתברכו נכסיך\") ונתרבו שלא ע\"ד הרגיל, ה\"ז עלול לעורר תאותם של שודדים, בראו­תם אצלו עשירות כזו.\nוהנה נכסים בכלל נחלקים לשנים: קרקעות ומטלטלין, ובמטלטלין עצמם הכי קל ליטול ה\"ז ממון. וע\"ז באה ה­ברכה שגם מזה נשמר, שלא יבואו ויגזלו ממונו. ולכן באה ברכה מיוחדה נוספת — \"(יברכך ה') וישמרך\", שהקב\"ה ישמור מתנה זו<sup data-n=\"478\">26</sup> מן השודדים.",[["472","20","בשני כת\"י רש\"י שתח\"י \"שיתברכו כל נכסיך\"."],["473","21","תוכן פירוש זה נמצא בתנחומא ובמדב\"ר כאן, אבל בכמה שינויים, וז\"ל: עם הברכה שמירה, מלך ב\"ו יש לו אוהב בסוריא והוא יושב ברומי שלח המלך אחריו עלה ובא אצלו נתן לו מאה ליטרין של זהב טענו יצא לדרך נפלו עליו לסטין ונטלו כל מה שנתן לו המלך וכל מה שהי' אצלו שמא יכול לשמרו המלך מן הלסטין לפיכך כתיב יברכך ה' וישמרך.\n— טעם השינויים בפרש\"י [א) לא נקט \"מלך\", ב) כ' \"עבדו\" (כהגירסא בבמדב\"ר כאן), ולא \"אוהבו\", ג) לא הדגיש שינוי המקומות \"בסוריא. . ברומי\", ואשר חשש הלסטים הוא בהליכתו בדרך, ד) משמיט שנטלו \"כל מה שנתן לו המלך. . שהי' אצלו\", ו­עוד] — נת' בההתועדות."],["474","22","הטעם שנקט רש\"י \"ספרי\" דוקא (אף שישנם פירושים גם בתנחומא ובמדב\"ר כאן) — י\"ל, נוסף על העיקר שהספרי קדום להם, שזהו לשלול טעות שכוונתו להמשל שם (הובא בהערה הקודמת)."],["475","23","וראה כמה פירושים בספרי, תנחומא ובמדב\"ר כאן (כסיום ל' רש\"י עצמו \"והרבה מדרשים כו'\")."],["476","24","ויצא כח, טו. וכן בתפלת יעקב שם (פסוק כ). וראה פרש\"י שם, יא ד\"ה וישם."],["477","25","ראה באר בשדה על פרש\"י כאן."],["478","26","והטעם שכ' רש\"י \"ליטול ממונך\" (סתם) — ולא ע\"ד שכ' הראב\"ע כאן \"שישמור התוספת\" (כלשונו שם לפנ\"ז), וכלשון המשל בפרש\"י \"נוטלין אותה\" (המתנה) [וראה ל' המדרש, הובא לעיל הערה 21] — יש לומר, כי רש\"י לשיטתו, שהברכה (מתנה) היא \"שיתברכו נכסיך\", דהיינו (כנ\"ל) לא נתינת נכסים חדשים, אלא שהנכסים עצמם יתברכו ויתרבו, ומתנה זו א\"א ליטול מן האדם, ויכולים רק ליטול הממון שבו שורה ברכה זו."]]],[1301430111,"ובזה מתורץ עוד דיוק ברש\"י — ש­מפרש שברכת השמירה כאן היא רק בזה ש\"לא יבואו עליך שודדים ליטול ממונך\", דלכאורה אינו מובן, מדוע מגביל רש\"י ברכה זו רק לשמירה מן השודדים לבד, ולא כתב (בקיצור) \"וישמרך, את הנכסים שלך\" (ע\"ד לשון הספרי), או \"שנכסיך יהיו שמורים\" וכיו\"ב — לשון של שמירה כללית מכל מיני הפסד, כמו משריפה וכיו\"ב, ולא רק משודדים?\nאלא שהתוכן ד\"וישמרך\" הוא בהמשך ל\"יברכך\", היינו שמירתה מהנזק דשוד­דים שעלול לבוא דוקא מההשפעה ה­מרובה ד\"יברכך\", כנ\"ל, אבל אין ה­מדובר בסתם שמירה מהפסדים (כמו שריפה) המסתעפים מסיבות צדדיות<sup data-n=\"479\">27</sup>.\nה. אלא שעדיין צ\"ע אריכות המשך ל' רש\"י, שמחלק בין \"הנותן מתנה ל­עבדו\" למתנת הקב\"ה, ש\"הוא הנותן הוא השומר\" — דלכאורה הי' מספיק לומר \"וישמרך, שלא יבואו עליך שודדים ליטול ממונך\", שמזה מובן כבר תוכן ברכה זו.\nגם יש לדייק השינוי בלשון רש\"י, שגבי ברכת הקב\"ה אומר \"שלא יבואו עליך שודדים\", ואילו ב\"נותן מתנה ל­עבדו\" נקט \"מכל אדם. . לסטים\".\nוע\"פ משנת\"ל אתי לשון רש\"י ב­פשטות:\nכשם שברכת \"יברכך\" היא ברכה מיוחדת שלא מצינו כמותה בשאר ה­ברכות המפורשות בתורה — כמו\"כ צ\"ל בנוגע לברכת \"וישמרך\", שהיא שמירה מיוחדת, שהיא רק בכחו של הקב\"ה.\nומטעם זה א\"א לו לרש\"י לפרש ש­כוונת \"וישמרך\" היא שמירת נכסי האדם סתם — כי שמירה כזו אין בה חידוש מיוחד. ויתירה מזו — סתם שמירת ה­נכסים נכללת בעצם הברכה, ובלשון ה­מדרש<sup data-n=\"480\">28</sup> \"והלא אם מבורכים הם שמו­רים\" (\"כי ברכה בלא שמירה אינה כלום\"<sup data-n=\"481\">29</sup>).\nוזוהי כוונת רש\"י באריכות לשונו, ב­החילוק בין \"הנותן מתנה לעבדו\" למתנת הקב\"ה ש\"הוא הנותן הוא השומר\" — כי זהו החידוש בברכה זו, שהיא שמירה מיוחדת של הקב\"ה, שאינה ביכלתו של בשר ודם \"הנותן מתנה לעבדו (ש)אינו יכול לשמרו מכל אדם\". כלומר: אין כוונת רש\"י לומר שרק הקב\"ה \"הוא הנותן הוא השומר\", משא\"כ בשר ודם אינו שומר כלל (שהרי ביכלתו של בו\"ד לשמור נכסיו מכמה מיני היזקות), אלא הדיוק הוא — שהקב\"ה יכול לשמור \"מכל אדם\", יהי' מי שיהי', מה שאין זה ביכלתו של בשר ודם.\nועפ\"ז מובן גם דיוק לשון רש\"י ש­שמירת הקב\"ה היא \"שלא יבואו עליך שודדים ליטול ממונך\" (ולא \"לסטים\", כלשונו לאח\"ז):\nהלשון \"שודדים\" מורה על סוג מיוחד של לסטים, שבוזזים ושודדים את כל נכסי האדם (לא כסתם לסטים, שע\"ד הרגיל נוטלים רק חלק מנכסי האדם) — אי משום שחזקים הם ביותר, או שבאים",[["479","27","וי\"ל שזה נכלל בדרך ממילא ב\"יתברכו נכסיך\", כדלקמן סעיף ה."],["480","28","דעת ר' יצחק — במדב\"ר כאן."],["481","29","פי' מהרז\"וו לבמדב\"ר."]]],[1301430112,"בכנופיא כו'. וזהו שמדייק רש\"י ומדגיש החילוק שבין שמירת הקב\"ה לשמירת \"הנותן מתנה לעבדו\" — שבשר ודם אינו יכול לשמור מתנתו אפילו מלסטים (וכ\"ש וק\"ו משודדים), ואילו הקב\"ה יכול לשמור מתנתו מכל אדם, (לא רק מ­לסטים, אלא) אפילו מ\"שודדים\" — שאין ביכלתו של בו\"ד לשמור א\"ע מהם כלל<sup data-n=\"482\">30</sup>.\nו. ובדרך זו יתיישב גם פרש\"י ב­פסוק שלאח\"ז — \"יאר ה' פניו אליך\" — \"יראה לך פנים שוחקות פנים צהובות\".\nדלכאורה תמוה — אמאי שינה רש\"י מלשון הכתוב (\"יאר. . פניו\") וכתב \"פנים שוחקות פנים צהובות\"?\nובפרט שגם במדרש<sup data-n=\"483\">31</sup> הלשון \"שיביט בך בפנים מאירות ולא בפנים זעומות\", ומצינו לשון זו בפרש\"י לעיל — עה\"פ<sup data-n=\"484\">32</sup> \"וראיתם את כבוד ה'\", \"בפנים מאירות. . כבוד אור פניו\".\nגם צ\"ב כפל הלשון בפרש\"י \"פנים שוחקות פנים צהובות\", דמזה שרש\"י כופל גם תיבת \"פנים\" מוכח שהם שני ענינים (ולא ב' לשונות על ענין אחד) — ונוסף על השאלה מה הם שני הענינים, מנ\"ל בפשוטו של מקרא ש\"יאר גו'\" כולל שני ענינים?\nוע\"פ הנ\"ל מתורץ גם זה:\nברכת \"פנים מאירות\" סתם כבר נכל­לת בברכות דפ' בחוקותי, דכאשר בנ\"י עמלים בתורה ושומרים מצוותיו, הרי בודאי שזוכים לכל הברכות המנויות בפרשה מתוך \"פנים מאירות\".\nאלא החידוש כאן הוא שיהיו \"פנים מאירות\" באופן מיוחד — \"פנים שוחקות פנים צהובות\", כלומר, \"פנים מאירות\" הבא כתוצאה ממצב של \"פנים שוחקות\" — שמחה גדולה ושמחה גלוי', שמובן, שהארת הפנים במצב של שמחה ה\"ה באופן נעלה ביותר. וזהו שדייק רש\"י וכ' \"פנים צהובות\" (לא סתם \"פנים מאירות\"), והיינו כפרש\"י לעיל<sup data-n=\"485\">33</sup> ד\"לשון צהוב דומה לתבנית זהב, צהוב כמו זהוב\", וכן בעניננו, לא סתם \"מאירות\", אלא מראה (וצבע) של זהוב — צהוב.\nז. והנה מצות ברכת כהנים ה\"ה בכל מקום ובכל זמן<sup data-n=\"486\">34</sup> — דגם בזמן הגלות ובחוץ לארץ מ\"ע של תורה על הכהנים לברך את בני ישראל.\nשמזה מובן, שברכות אלו אינן תלו­יות במצבם של ישראל, אלא נמשכות לכאו\"א מישראל, יהי' מי שיהי', באיזה מצב שהוא.\nוזה מתאים עם משנת\"ל בנוגע לתוכן ברכות אלו — שהם ברכות מיוחדות שאינן בשאר הברכות שהובטחו לישראל בגלל שמירת התומ\"צ — כי הברכות דברכת כהנים באות ונמשכות ממקום עליון ביותר<sup data-n=\"487\">35</sup>, שלגבי' אין עבודת ה­",[["482","30","אלא כיון שסו\"ס דוחק לומר שכל תוכן ברכה זו הוא רק שמירת נכסים משודדים — מסיים רש\"י \"והרבה מדרשים דרשו בו בספרי\", שבספרי יש עוד כמה מדרשים בענין ברכת \"וישמרך\". ואכ\"מ."],["483","31","במדב\"ר כאן (פי\"א, ו). — וראה עוד פירושים שם, ובספרי ותנחומא, וכולם לשון אור."],["484","32","בשלח טז, ז."],["485","33","תזריע יג, לז. — ומתורצת סתימת ל' רש\"י \"פנים צהובות\" (אף שבסנהדרין קה, א הכוונה להבעת פנים זועפות. וראה תו\"ת פרשתנו כאן) — כי סמיך על ל' \"צהוב\" המפורש לעיל בקרא (וב­פרש\"י)."],["486","34","ל' החינוך מצוה שעח."],["487","35","ראה לקו\"ת ס\"פ קרח. ד\"ה כה תברכו באוה\"ת פרשתנו (ע' ער ואילך. שם כרך ד' ע' א'תלח ואילך) ובסה\"מ תרכ\"ט. ועוד."]]],[1301430113,"נבראים תופסת מקום, ואשר לכן (א) ה\"ה ברכות שלמעלה מן הטבע לגמרי, ורק ביכלתו של הקב\"ה לתת ברכות כאלו, (ב) הן נמשכות לכאו\"א מישראל, יהי' מי שיהי', בכל זמן ובכל מקום.\nוכן תהי' לנו — לראות ברכות הוי', למטה מעשרה טפחים, כפשוטו של מקרא ש\"יברכך ה' וישמרך\" (הברכה ה­ראשונה) היא בענינים גשמיים דוקא — ואז נהיו \"פנויים להתחכם בתורה ו­לעסוק בה\"<sup data-n=\"488\">36</sup>, מתוך מנוחת הנפש ומנוחת הגוף, עד למנוחה האמיתית — \"יום<sup data-n=\"489\">37</sup> שכולו שבת ומנוחה לחיי העולמים\".\n<span data-k=\"q\">(משיחות ש\"פ נשא תשל\"ז, ש\"פ נשא וש\"פ בהעלותך תשמ\"א)</span>",[["488","36","ל' הרמב\"ם הל' תשובה פ\"ט ה\"א."],["489","37","סוף תמיד."]]],[1301430114,"<h3>שיחה א</h3>\nא. בנוגע לדין פסח שני — שהתורה קבעה התשלומין דפסח ראשון לי\"ד ב­אייר דוקא<sup data-n=\"490\">1</sup>, חודש ימים לאחרי פסח ראשון — צריך ביאור<sup data-n=\"491\">2</sup>: מה נשתנה קרבן פסח (שזמן התשלומין שלו בא לאחר הפסק של חודש ימים) משאר קרבנות יו\"ט, שימי תשלומיהם באים בהמשך ל­יום ראשון של חג<sup data-n=\"492\">3</sup>?\nובפרט ע\"פ מחז\"ל<sup data-n=\"493\">4</sup> שה\"טמאים לנפש אדם\"<sup data-n=\"494\">5</sup> במדבר (שבאו בטענה \"למה נגרע לבלתי הקריב את קרבן ה' במועדו\"<sup data-n=\"495\">6</sup> וזכו שפרשה זו נאמרה על ידיהן<sup data-n=\"496\">7</sup>) חל יום השביעי לטומאתם בערב פסח, ש­לפ\"ז הרי הי' אפשר לקבוע את זמן ה­תשלומין במשך ימי החג גופא.\nויש לומר, ש(ע\"פ פנימיות התורה) זהו היסוד לביאור הצ\"צ<sup data-n=\"497\">8</sup>, שענינו של פסח שני בעבודת האדם שייך לתוכן העבודה של חודש אייר<sup data-n=\"498\">9</sup>, ה\"חודש השני\".\nתוכן ביאור הצ\"צ:\nענינו של פסח שני בעבודת האדם הוא — העלי' מהדרגא הראשונה דיציאת מצרים (פסח ראשון שבחודש ניסן, החודש הראשון) לדרגא השני' (שבחודש אייר, החודש השני)<sup data-n=\"499\">10</sup>, דהיינו העבודה ד\"ועשה טוב\" הבאה לאחרי הקדמת \"סור מרע\".\nכלומר: יציאת מצרים היא תחילת העבודה, \"סור מרע\" — היציאה ממצרים; וכמבואר בתניא<sup data-n=\"500\">11</sup> שביצי\"מ נאמר<sup data-n=\"501\">12</sup> \"כי ברח העם\", \"מפני שהרע שבנפשות ישר­אל עדיין הי' בתקפו כו'\", ועיקר עבו­דתם היתה באופן ד\"סור מרע\" (הבריחה מטומאת מצרים); ולאחר הקדמת עבודת \"סור מרע\" נתעלו למדריגה השני' — \"ועשה טוב\".\nובעבודה רוחנית בנפש האדם — יצי\"מ (פסח ראשון) היא העבודה ד\"את­כפיא\", כפיית הרע שבנפשו; ומעבודה זו מגיע ועולה לדרגא שני' — העבודה ד\"אתהפכא\", הפיכת הרע לטוב, \"בכל לבבך — בשני יצריך\"<sup data-n=\"502\">13</sup>. ומעלה זו דפסח שני מתאימה עם כללות החידוש שב­עבודת חודש אייר, חודש השני (לגבי חודש ניסן, חודש הראשון) — ספירת העומר (ד\"עיקר ספה\"ע הוא כל חדש אייר\"<sup data-n=\"497\">8</sup>) — דהעבודה דספירת העומר היא בירור המדות והפיכתן לקדושה.\nועפ\"ז מבאר<sup data-n=\"504\">14</sup> את החילוק בין פסח",[["490","1","פרשתנו ט, יא."],["491","2","ראה אוה\"ח פרשתנו (ט, ז) שי\"ל שזו היתה טענת האנשים \"למה נגרע וגו'\".\nוראה רע\"מ פרשתנו (קנב, ב). בעל הטורים פרשתנו (ט, י). ועוד."],["492","3","חגיגה ט, א. יז, א. ובכ\"מ."],["493","4","פסחים צ, ב. סוכה כה, ב."],["494","5","פרשתנו ט, ו."],["495","6","שם, ז."],["496","7","רש\"י שם."],["497","8","אוה\"ת פרשתנו ע' שסז­ח. וראה לקו\"ש ח\"ד ע' 1301 ואילך. סה\"מ מלוקט ח\"ג ע' קמג ואילך."],["498","9","ולהעיר מתיב\"ע פרשתנו (ט, יב) \"פסחא דניסן. . ובפסחא דאייר\"."],["499","10","ראה אוה\"ת שם — מלקו\"ת במדבר (ג, א) בפירוש \"באחד לחודש השני גו' לצאתם מארץ מצרים\" (ר\"פ במדבר)."],["500","11","פל\"א (מ, ב)."],["501","12","בשלח יד, ה."],["502","13","משנה ברכות נד, א."],["497","8","אוה\"ת פרשתנו ע' שסז­ח. וראה לקו\"ש ח\"ד ע' 1301 ואילך. סה\"מ מלוקט ח\"ג ע' קמג ואילך."],["504","14","אוה\"ת שם. וראה אוה\"ת ויקרא ח\"ג ע' תשלו."]]],[1301430115,"ראשון ופסח שני, ש\"הראשון אסור בבל יראה ובל ימצא, והשני חמץ ומצה עמו בבית\"<sup data-n=\"505\">15</sup>:\nמכיון שהעבודה דפסח ראשון היא \"סור מרע\", בריחה מהרע, לכן חל אז החיוב לבער את החמץ (הרומז על הרע, \"שאור שבעיסה\"<sup data-n=\"506\">16</sup>), שלא יהי' שום חמץ ברשותו; משא\"כ פסח שני, שענינו הפיכת הרע לטוב, אין צריכים בו בזמן לבער את החמץ מרשותו, אלא \"חמץ ומצה עמו בבית\", כי על ידי פסח שני ניתן (בהוספה —) הכח להפוך את החמץ לקדושה.\n[ויש לומר שזהו בדוגמת העילוי ד­שתי הלחם בחג השבועות (לגבי קרבן עומר דחג הפסח), שמעלתו היא דוקא בזה ש\"חמץ תאפינה\"<sup data-n=\"507\">17</sup> — כי לאחרי גמר העבודה דספירת העומר הרי החמץ נהפך לגמרי לקדושה<sup data-n=\"508\">18</sup> ויכולים ועושים אותו קרבן לה'<sup data-n=\"509\">19</sup>].\nב. אלא שצ\"ע בעצם ביאורו של ה­צ\"צ, שלכאורה ביאור זה — שפסח שני הוא דרגא שני' ונעלית בעבודה (עשה טוב, אתהפכא) הבאה לאחרי הקדמת ה­עבודה דפסח ראשון (סור מרע, אתכפיא) — הוא היפך המפורש בפשוטו של מקרא (והלכה), שכל ענינו של פסח שני אינו אלא באיש שלא הביא פסח ראשון (ומי שהקריב קרבנו בפסח ראשון, הרי לא זו בלבד שאין עליו חיוב להקריב פסח שני, אלא שאסור לו להקריב פסח שני)!\nולפי ביאור הצ\"צ ה\"ז להיפך<sup data-n=\"510\">20</sup> — כי נוסף ע\"ז שלאחרי העבודה דפסח ראשון שייכת וגם נדרשת העבודה דפסח שני, הרי עוד זאת, שאי אפשר להגיע להעבו­דה דפסח שני כ\"א דוקא ע\"י הקדמת העבודה דפסח ראשון?!\nג. ויש לומר הביאור בזה — וב­הקדם:\nהאמור לעיל, שכל הענין דפסח שני הוא דוקא כשלא קדם לו פסח ראשון, הרי זה רק בנוגע לקרבן פסח, שאם לא הקריב בראשון מקריב בשני, ואם",[["505","15","פסחים צה, רע\"א (במשנה). רש\"י פרשתנו ט, י."],["506","16","ל' חז\"ל — ברכות יז, א. ועוד. ויצה\"ר נקרא חמץ (זח\"ב קפג, ב. וראה ר\"ה ג, סע\"ב. רש\"י ברכות שם. ועוד)."],["507","17","אמור כג, יז."],["508","18","ראה לקו\"ש חל\"ב ע' 136. וש\"נ."],["509","19","משא\"כ בפסח שני שהוא עדיין באמצע הספירה, הרי: א) אין החמץ מצוה, ב) החמץ רק \"עמו בבית\", אבל יש \"איסור חמץ. . עמו באכילתו\"<sup data-n=\"e11\">*</sup> (רש\"י פרשתנו שם (מפסחים צה,\nא­ב<sup data-n=\"e12\">**</sup>). וראה אוה\"ת ויקרא הנ\"ל הערה 14)."],["510","20","ולהעיר מביאור כ\"ק מו\"ח אדמו\"ר (\"היום יום\" יד אייר. ועוד) ש\"פסח שני ענינו איז — אַז עס איז ניטאָ קיין פאַרפאַלן, מען קען אַלעמאָל פאַריכטען\" — עבודת התשובה (ופסח ראשון הוא עבודת הצדיקים — ראה בארוכה לקו\"ש חי\"ח ע' 118 ואילך (וראה שם ע' 121 הערה 49))."],["e11","*","באמבוהא דספרי לספרי זוטא פרשתנו (ט, יא) מפרש לשון רש\"י \"אלא עמו באכילתו\" — שגם באכילתו רשאי לאכול חמץ, ומציין לרש\"י סוכה מז, ב (ד\"ה ופנית) \"ואוכל חמץ מיד\".\nאבל פשטות לשון רש\"י \"ואין איסור חמץ אלא עמו באכילתו\" היא, שעמו באכילתו אסור (וכ\"ה בפנ\"י לקידושין לח, ב. מנ\"ח שבשוה\"ג הבאה. ועוד). וכן מוכח מלשון רש\"י סוכה שם \"מיד\" ולא \"עמו\". ועוד, לפ\"ז עדיפא הול\"ל במשנה (וכן ברש\"י עה\"ת) — \"(עמו) באכילתו\", לא \"(עמו) בבית\"."],["e12","**","נת' בשיחת ש\"פ שלח תשמ\"ז. — ודלא כמ\"ש במנ\"ח (מצוה שפא) ד\"לא ידעתי מהיכן יצא לרבינו זה. . ולא ראיתי בשום מקום\"."]]],[1301430116,"הקריב בראשון אסור לו להקריב בשני; אבל מובן שאין זה בנוגע לשאר הענינים והמצוות של חג הפסח, כמו איסורי חמץ ואכילת מצה — שגם מי שאינו מקריב קרבן פסח בי\"ד בניסן (ע\"פ תורה, להיו­תו \"טמא\" או \"בדרך רחוקה\"<sup data-n=\"511\">21</sup>) מחוייב באיסורי חמץ ולאכול מצה כו'.\n[ויש להוסיף, שבנדון הכתוב, הרי ה­\"אנשים אשר היו טמאים לנפש אדם\"<sup data-n=\"494\">5</sup> היו (כדברי חז\"ל<sup data-n=\"513\">22</sup>) \"מישאל ואלצפן. . שהיו עוסקין בנדב ואביהוא\", כלומר ש­טומאתם היתה ע\"פ ציווי משה<sup data-n=\"514\">23</sup> \"קרבו שאו את אחיכם גו'\".\n(וי\"ל שזהו<sup data-n=\"515\">24</sup> ביאור טענתם \"למה נגרע\" — דלכאורה אינו מובן: מה מקום לטענה \"למה נגרע לבלתי הקריב את קרבן ה' במועדו\" — הלא הם עצמם הקדימו תשובה לטענתם זו באמרם \"אנחנו טמאים לנפש אדם\", שלכן אינם יכולים להקריב קרבן ה' במועדו?\nאלא שטענתם היתה מיוסדת על זה שטומאתם היתה ע\"פ ציווי משה, ולכן טענו: היתכן שע\"י ציווי משה — \"נגרע\", ובפרט מ\"הקריב את קרבן ה' במועדו\").\nועפ\"ז ברור ופשוט שכל עניני הפסח ב\"אנשים\" אלה (לבד — הקרבת הק\"פ) היו בתכלית השלימות].\nועפ\"ז מובנים דברי הצ\"צ שפסח שני שייך לדרגא השני' בעבודה, הבאה ל­אחרי הדרגא הראשונה דפסח ראשון, היינו, שכדי לבוא לפסח שני בהכרח ש­יהי' תחלה פסח ראשון (אף שפסח שני הוא רק למי שלא הקריב פסח ראשון):\nהעבודה הרוחנית דחג הפסח — \"סור מרע\", כפיית הרע — קשורה בקיום (שאר) עניני ומצוות החג (איסורי חמץ, וחיוב אכילת מצה — \"לחם עוני\"<sup data-n=\"516\">25</sup>); וכיון שגם מי שלא הקריב פסח ראשון בזמנו ה\"ה עובד עבודתו ב(שאר) עניני הפסח, נמצא, שפסח שני הוא אצלו ה­דרגא השני', הבאה לאחרי העבודה ד­חה\"פ (הראשון)<sup data-n=\"517\">26</sup>, וכביאור הצ\"צ שבפסח שני מגיע ועולה למדריגה השני' בעבו­דה, עשה טוב, אתהפכא.\nד. אמנם עדיין לא נתבאר הענין כל צרכו:\nהן אמת שגם מי שלא הקריב קרבן פסח ראשון לא נגרע אצלו מעבודתו (גם הרוחנית) בדרגא הראשונה דחה\"פ רא­שון (מכיון שהיו אצלו כל עניני פסח ראשון מלבד קרבן פסח), וממנה עולה לדרגא השני', דפסח שני — אבל לאידך גיסא: א) למה מי שהקריב פסח ראשון אסור לו להקריב פסח שני (והרי לבי­אור הצ\"צ נדרשת ממנו העבודה דפ\"ש), ב) איך ובמה עולה הוא לדרגא השני' בעבודת השם כשבאה (רק) בהקרבת הפסח ראשון במועדו?\nויש לומר הביאור בזה:\nלאחרי הקרבת קרבן פסח ראשון, שוב אין צורך להביא קרבן בפסח שני כדי להגיע למדריגה השני' (עשה טוב, אתהפכא) — כי זה כבר נעשה בשלימות על ידי הקרבן בפסח ראשון. כלומר: זה שביכלתו של אדם להגיע (בחודש אייר,",[["511","21","פרשתנו ט, י."],["494","5","פרשתנו ט, ו."],["513","22","סוכה כה, ריש ע\"ב."],["514","23","שמיני י, ד."],["515","24","ראה גם ספורנו ואוה\"ח פרשתנו ט, ז."],["516","25","פ' ראה טז, ג. וראה תו\"א ס\"פ ויקהל (וכן בהוספות לתו\"א שם) שזהו מפני שמצה ענינה העבודה דאתכפיא."],["517","26","וראה גם אוה\"ת ויקרא שם: כיון שכבר אכלו (מצה) ז' הימים. . לכן שוב אין יניקה לחמץ כלל כו'."]]],[1301430117,"חודש השני) למדריגה השני' בעבודת ה' (עשה טוב, אתהפכא) בא ע\"י קרבן פסח שבפסח ראשון.\nהסברת הענין:\n\"קרבן\" — הוא מלשון קירוב<sup data-n=\"518\">27</sup>, שעל ידי קרבנות מתקרב האדם להשם. וכ­מבואר בכ\"מ<sup data-n=\"519\">28</sup> ענינו של קרבן בעבודת האדם, שהאדם צריך להקריב להשם את ה\"בהמה גו'\" שבו, עד שיהי' ראוי להיות נקרב על מזבח ה' ולהשרף באש של מעלה, שיכלל בקדושה וכו'.\nוהקרבת פסח ראשון היא היא הנותנת כח ופועלת שהמשך עבודת האדם (ספי­רת העומר, שזמנה מתחיל תיכף \"מ­מחרת\" הפסח) יהי' באופן כזה, שיגיע על ידה ל\"עשה טוב\", אתהפכא<sup data-n=\"520\">29</sup>.\nואין סתירה בין ביאור הצ\"צ (שפסח שני ענינו הדרגא השני' בעבודת השם) וענינו של פסח שני (שבא לתקן ול­השלים את החסרון דפסח ראשון) — כי עבודתו של פסח שני (דרגא השני', אתהפכא) תלוי' בהקרבת קרבן פסח. ולכן: מי שהקריב פסח ראשון, יגיע בודאי למדריגה השני' (בחודש השני, כולל יום פסח שני) ואין צורך (ובמילא — מקום) בקרבן נוסף<sup data-n=\"521\">30</sup>; משא\"כ מי שלא הקריב קרבן פסח בראשון, אא\"פ לו להגיע למדריגת אתהפכא מבלי שיתקן וישלים את החסרון דפסח ראשון ע\"י שיביא קרבן בפסח שני (ולא יגרע ל­הקריב — ע\"ד פסח ראשון).\nה. ע\"פ ביאור זה יומתק ג\"כ הטעם שגם בזמן הזה נקבע פסח שני ליום מיו­חד לכל ישראל, וכמ\"ש רבינו הזקן ב­סידורו<sup data-n=\"522\">31</sup> שבפסח שני אין אומרים תחנון, ועד שיש מנהג<sup data-n=\"523\">32</sup> לאכול בו מצה זכר לפסח שני<sup data-n=\"524\">33</sup>.\nדלכאורה: הענין של פסח שני הוא תיקון והשלמה למי שלא הקריב פסח ראשון",[["518","27","ס' הבהיר סי' מו (קט). ועייג\"כ זח\"ג ה, רע\"א. של\"ה מס' תענית ריא, ב."],["519","28","ראה לקו\"ת ויקרא ד\"ה אדם כי יקריב. ובכ\"מ."],["520","29","ולהעיר דפסח נאכל צלי ועל השובע דוקא, היפך \"לחם עוני\" (ראה לעיל הערה 25)."],["521","30","וי\"ל שאדרבה, ע\"י פסח ראשון מגיעים למעלה יותר מפסח שני (ולהעיר שפסח שני נקרא (ר\"ה פ\"א מ\"ג) \"פסח קטן\").\nועפ\"ז מובן המשך הדברים באוה\"ת פרשתנו שם, שלאחרי שמבאר מעלת פסח שני לגבי פסח ראשון, דפ\"ר מלכות ופ\"ש יסוד — כותב שמ\"מ פ\"ר גבוה יותר (כמ\"ש בזהר פרשתנו קנב, ב<sup data-n=\"e13\">*</sup>) כי \"מלכות שרשה גבוה יותר מיסוד. . אשת חיל עטרת בעלה ונעוץ תחלתן בסופן דוקא\".\nוי\"ל שענין זה שייך לקרבן פסח, כי הקרבן \"מקרב\" ומעלה כל ענין לשרשו ומקורו (עד \"רזא דא\"ס\" — ראה זח\"ב רלט, א. זח\"ג כו, ב), ועד\"ז בענין המלכות, שע\"י קרבן פסח עולה המלכות לשרשה ומקורה (למעלה מיסוד)."],["522","31","לפני למנצח יענך. וראה השלמה לשו\"ע אדה\"ז (להרר\"נ מדובראוונא) או\"ח סקל\"א סוס\"ח. וש\"נ. הערה 45 לקמן (הדיעות בזה — נלקטו בס' \"בין פסח לשבועות\" (ירושלים, תשד\"מ) פרק ז)."],["523","32","סידור יעב\"ץ חודש אייר. לקוטי מהרי\"ח. ועוד. וכ\"ה מנהג חב\"ד (ראה מכתב ז' תמוז תש\"ח<sup data-n=\"e14\">*</sup>). וראה בספר שבהערה הקודמת. וש\"נ."],["524","33","ולהעיר דבזה\"ז — אכילת מצה (דהאפיקומן) במקום פסח (ראשון) — טושו\"ע (ודאדה\"ז) או\"ח ר\"ס תעז."],["e13","*","הובא גם בלקו\"ת במדבר (שהובא לעיל הערה 10), ושם, ש\"יובן ממ\"ש. . בפ' ויקהל. . ב­ענין בחי' אתכפיא שיש בה בחי' שהוא למעלה מבחי' אתהפכא\"."],["e14","*","נדפס בס' אגרות קודש כ\"ק אדמו\"ר שליט\"א ח\"ב ע' שנב. לקו\"ש חכ\"ז ע' 384. המו\"ל."]]],[1301430118,"[וגם להמ\"ד<sup data-n=\"525\">34</sup> (וכ\"ה ההלכה<sup data-n=\"526\">35</sup>) דפסח שני הוא רגל בפני עצמו, שלכן גם מי שלא חל עליו החיוב להביא פסח ראשון ונעשה בר חיובא בין ראשון לשני (קטן שנתגדל, או גר שנתגייר בין ראשון ל­שני) חייב להביא פסח שני<sup data-n=\"527\">36</sup> — מ\"מ עכצ\"ל (ומפורש בקרא שבא ע\"י הטענה \"למה נגרע\") שענינו של פסח שני הוא תשלומין לגרעון דראשון, וכל מי שעשה את הראשון אי אפשר לו להתחייב בשני; אלא שחידשה תורה (והוסיפה בפ\"ש — רגל בפ\"ע) דעם היות שהקטן כו' לא הי' מחוייב בראשון, בכ\"ז ניתנה לו האפשרות להקריב הפסח בי\"ד באייר — ועד\"ז בגר<sup data-n=\"528\">37</sup>];\nולכן, בזמן הזה (ובפרט בחו\"ל) שאין לנו קרבן פסח<sup data-n=\"529\">38</sup> — שוב לא שייך לכאו­רה כל הענין דפסח שני — ומה מקום לחגיגת פסח שני (באיזה אופן שהוא)<sup data-n=\"530\">39</sup>?\nיתירה מזו: \"איש נדחה לפסח שני ואין צבור נדחה לפסח שני\"<sup data-n=\"531\">40</sup>, כלומר, ענין התשלומין דפסח שני ניתן רק ל­יחיד ולא לציבור<sup data-n=\"532\">41</sup>; וא\"כ כיצד מתאים לקבוע פסח שני כיום דמנהגים מיוחדים, שאין אומרים תחנון וכו' — עבור כל בנ\"י יחד<sup data-n=\"533\">42</sup>?\n[ודוחק גדול לתרץ שזהו רק ע\"פ דעת ר' יהודה (בירושלמי<sup data-n=\"534\">43</sup>) דכש\"ניתן לישראל לבנות בית הבחירה (בין פסח ראשון לפסח שני)\" — עושין הצבור פסח שני (ובפרט ע\"פ משנ\"ת במק\"א<sup data-n=\"535\">44</sup> שי\"ל שגם הבבלי ס\"ל בזה כהירושלמי, דב­אופן כזה הציבור עושה פסח שני) — וא\"כ אף שאין קרבן פסח בראשון מ\"מ אפשר שיהי' קרבן בפסח שני —\nכי מה שאנו חוגגים פסח שני אינו שייך לאפשרות דהקרבת פסח שני כ\"א זכר לפסח שני שהי' בזמן המקדש, ומה מקום לקבוע זכר לצבור על תשלומין דענין שלא ניתן אלא ליחיד?]\nועכצ\"ל שפסח שני יש בו ענין השייך לכל ישראל<sup data-n=\"536\">45</sup>. וע\"פ המבואר לעיל בתו­כן ענינו של פסח שני בעבודת האדם — מובן הענין בפשטות, שהרי ביום זה יש בכחו של כל אדם מישראל להגיע ל­מדריגה השני' שבעבודת השם, העבודה דאתהפכא. כלומר: גם אלו שהקריבו",[["525","34","פסחים צג, א."],["526","35","רמב\"ם הל' ק\"פ רפ\"ה."],["527","36","פסחים שם. רמב\"ם שם ה\"ז."],["528","37","ראה בארוכה לקו\"ש חי\"ח ע' 126 ואילך."],["529","38","ידועה השקו\"ט אם אפשר להקריב ק\"פ בזמה\"ז (וראה הנסמן בהערה 44), אבל למעשה כבר רבו האוסרין (ראה בס' שנסמנו בשד\"ח כללים סוף מערכת ק'. תו\"ש בא חי\"ב, ע' קנה). ואכ\"מ."],["530","39","אבל להעיר מהמנהג שלא לומר תחנון עד י\"ב סיון מפני שהם ימי תשלומין (דגרעון דראשון) — (הובא במג\"א סקל\"א סקי\"ח. וכ\"כ אדה\"ז בסידורו שם — משא\"כ בשו\"ע שלו או\"ח סו\"ס תצד). — וראה הערה 41."],["531","40","פסחים סז, א. וראה שם פ, ב."],["532","41","משא\"כ בנוגע לתשלומין דקרבנות יו\"ט. — וראה שו\"ע אדה\"ז שם בנוגע ל\"יום טבוח\" לאחרי חג השבועות. ואכ\"מ."],["533","42","ראה גם פרמ\"ג (משב\"ז) או\"ח סו\"ס קלא.\nואינו דומה לאי אמירת תחנון מא' ניסן עד י\"ב בו, ימי הקרבת קרבנות הנשיאים ש\"כל נשיא ביום שהקריב קרבנו הי' יו\"ט שלו\" (שו\"ע אדה\"ז או\"ח סתכ\"ט ס\"ט) — כי [גם להדיעות שהיו קרבן יחיד — רש\"י נשא (ז, יב. יד). וראה בארוכה לקו\"ש חכ\"ג ע' 42 ואילך — מ\"מ] מכיון שקרבנות אלו הובאו ע\"י נשיאים, מובן שיש להם שייכות להשבט שלו ונכללו כולם יחד \"ביום המשח\" ו\"לאחרי המשח\" — לכל ישראל."],["534","43","פסחים פ\"ט ה\"א (לגירסת ופירוש המנ\"ח מצוה שפ). תוספתא פסחים פ\"ח ה\"ב."],["535","44","לקו\"ש חי\"ב ע' 219 ואילך. ע\"ש."],["536","45","וראה חולין קכט, ב (ממגילת תענית פ\"ב) פסחא זעירא דלא למספד."]]],[1301430119,"פסח ראשון, שלימות פעולת הקרבה זו (שהיא העבודה דאתהפכא) באה בחודש השני, ובפרט בפסח שני [שבו מתחילה הספירה השייכת למדת ההוד<sup data-n=\"537\">46</sup>];\nולכן, גם בזמן הזה, שישנה העבודה הרוחנית שבקרבן פסח, חוגגים את הזמן המיוחד עבור העלי' למדריגה השני' ש­בעבודת השם, אתהפכא ועשה טוב.\n<span data-k=\"q\">(משיחות פסח שני תשמ\"ז, תשד\"מ)</span>",[["537","46","ראה סידור עם דא\"ח (דש, א) שעיקר הבירור דספה\"ע נשלם בל\"ג בעומר, \"הוד שבהוד\", שהוא \"סוף ותשלום הספירות בעיקר המדות שנק' גופא\". ע\"ש.\nואולי י\"ל שענין זה מתחיל בפ\"ש, ספירת חסד שבהוד שהיא ראשית והתחלת דספירת ההוד (ובפרט ע\"פ הידוע שחסד הוא \"יומא דאזיל עם כולהו יומין\" — ראה זח\"ג קג, א­ב. קצא, ב. לקו\"ש ח\"ה ע' 174 הערה 12. וש\"נ)."]]],[1301430120,"<h3>שיחה ב</h3>\nא. איתא בספרי פרשתנו (עה\"פ<sup data-n=\"538\">1</sup> וב­יום שמחתכם ובמועדיכם גו' ותקעתם בחצוצרות גו') \"וביום שמחתכם אלו שבתות\", ושמעינן מהא ששבת הוא יום שמחה, וכן משמע בירושלמי מגילה<sup data-n=\"539\">2</sup> דילפינן הדין דכשחל פורים בשבת אין עושין סעודת פורים ביום השבת (אלא אחר השבת)<sup data-n=\"540\">3</sup> ממ\"ש \"לעשות<sup data-n=\"541\">4</sup> אותם ימי משתה ושמחה את ששמחתו תלוי' בב\"ד יצא זה [שבת] ששמחתו תלוי' בידי שמים\"<sup data-n=\"542\">5</sup>.\nוהנה אדמו\"ר הזקן כתב בשולחנו (בהלכות יו\"ט<sup data-n=\"543\">6</sup>) \"נהגו להרבות במיני מאכלים בי\"ט יותר מבשבת שלא נאמר בה שמחה\", ומשמע לכאורה שאין שום חיוב שמחה בשבת (ודלא כבספרי<sup data-n=\"544\">7</sup> וירו­שלמי הנ\"ל), וכן הסכימו הפוסקים שאין חיוב של שמחה בשבת<sup data-n=\"545\">8</sup>, וכמפורש בתוס' מו\"ק<sup data-n=\"546\">9</sup> דב\"רגל. . כתיב בהן שמחה שבת. . לא<sup data-n=\"547\">10</sup> כתיב שמחה\"<sup data-n=\"548\">11</sup> (ומעין זה איתא בשאילתות<sup data-n=\"549\">12</sup> ועוד).\nאבל י\"ל שכוונת אדה\"ז במ\"ש \"בשבת (ש)לא נאמר בה שמחה\" היא (לא למעט שבת מכל ענין השמחה, אלא) רק לשלול שמחה כמו שמחת יו\"ט (שבזה איירי ב­שו\"ע שם), כי שמחת יו\"ט יש לה גדר מיוחד, וגדר זה של שמחה ליכא ב­שבת<sup data-n=\"550\">13</sup>; ובזה מודגש חידושו של אדה\"ז בסעיף זה בגדרה של שמחת יו\"ט, כד­לקמן.\nב. וז\"ל אדה\"ז בהלכות יו\"ט שם<sup data-n=\"551\">14</sup>: כל ז' ימי הפסח וח' ימי החג וכן בי\"ט של עצרת חייב אדם להיות שמח וטוב לב הוא ובניו ואשתו ובני ביתו וכל ה­נלוים אליו ושמחה זו היא מ\"ע מה\"ת שנאמר<sup data-n=\"552\">15</sup> ושמחת בחגיך אתה ובנך ובתך וגו' כיצד משמחין הקטנים נותן להם קליות ואגוזים והנשים קונה להם בגדים ותכשיטין כפי ממונו והאנשים בזמן ש­בהמ\"ק הי' קיים היו אוכלין בשר שלמים לשמחה ועכשיו שאין בהמ\"ק קיים אין יוצאים ידי חובת שמחה אלא ביין ש­",[["538","1","פרשתנו י, י."],["539","2","פ\"א ה\"ד בתחלתה."],["540","3","וכן נפסק בשו\"ע או\"ח סתרפ\"ח ס\"ו. ובנ\"כ הטושו\"ע שם, שהוא ע\"פ הירושלמי שם."],["541","4","אסתר ט, כב."],["542","5","וראה קרבן העדה בירושלמי שם. נ\"כ הטושו\"ע שבהערה 3."],["543","6","סתקכ\"ט ס\"ז בסופו."],["544","7","אבל לכמה גי' (זית רענן ליל\"ש עה\"פ, הגר\"א לספרי שם) הלימוד בספרי הוא (לא מתיבת \"שמחתכם\", אלא) מ\"וביום אלו שבתות\". וכ\"ה בספרי זוטא שם. וראה בארוכה מפרשי הספרי."],["545","8","ראה בארוכה שד\"ח פאת השדה כללים מערכת אל\"ף אות פב (כרך ז' א'תצט, ב ואילך) וש\"נ. וראה גם ביאור הרי\"פ פערלא לרס\"ג ח\"א עשה נט (רנה, א ואילך). ובכ\"מ."],["546","9","כג, ב ד\"ה מאן."],["547","10","ולכן ברגל אין אבילות כלל, ושבת אף שאין אבילות נוהגת, עולה לשבעה ולמנין ל'."],["548","11","ועד\"ז הוא בנמוק\"י מו\"ק שם במשנה: משום דלא כתיב בי' שמחה אלא עונג. וראה גם לשון ה­רמב\"ן במלחמות מו\"ק שם (כג, ב)."],["549","12","ח\"ש שאילתא טו."],["550","13","משא\"כ שמחה בכלל — ראה שו\"ע אדה\"ז שם סתצ\"ג ס\"ח. ולהעיר מסידור (עם דא\"ח) מה, ריש ע\"ד (ועד\"ז שם רצז, ד): ואין המצוה בשמחה בשבת כלל. ואכ\"מ."],["551","14","ס\"ו­ז."],["552","15","פ' ראה טז, יד."]]],[1301430121,"נאמר<sup data-n=\"553\">16</sup> ויין ישמח לבב אנוש אבל בשר אין חובה לאכול עכשיו כיון שאין לנו בשר שלמים ומ\"מ מצוה יש באכילת בשר ביו\"ט כיון שנאמר בו שמחה והו­איל וא\"א לנו לשמוח בו בעיקר השמחה שהוא אכילת בשר שלמים יש לנו ל­שמחו בשאר כל מיני שמחות לכך נהגו להרבות במיני מאכלים בי\"ט יותר מב­שבת שלא נאמר בה שמחה וכן בגדי י\"ט צריכים להיות יותר טובים מבגדי שבת.\nוהנה לפי פשוטו קאי אדה\"ז בשיטת הרמב\"ם, שכתב<sup data-n=\"554\">17</sup>: ימים טובים. . חייב אדם להיות בהן שמח וטוב לב הוא ובניו ואשתו ובני ביתו וכל הנלוים עליו ש­נאמר ושמחת בחגיך וגו'. אף על פי שה­שמחה האמורה כאן היא קרבן שלמים כמו שאנו מבארין בהלכות חגיגה יש בכלל אותה שמחה לשמוח הוא ובניו ובני ביתו כל אחד כראוי לו. כיצד ה­קטנים נותן להם קליות ואגוזים ומגדנות והנשים קונה להן בגדים ותכשיטין נאים כפי ממונו, והאנשים אוכלין בשר ושותין יין שאין שמחה אלא בבשר ואין שמחה אלא ביין.\nומבואר בדברי הרמב\"ם כמה פרטים בחיוב השמחה ביו\"ט, שגם אדה\"ז בשול­חנו נקט בהם כוותי':\nא) דגם בזמן הזה, אף שאין לנו מקדש וקרבן שלמי שמחה, מ\"מ יש מצות שמחה מן התורה<sup data-n=\"555\">18</sup> (ולא כהדיעות שבזמן הזה שמחת הרגל מדרבנן, כי \"ושמחת היינו בשלמי שמחה\"<sup data-n=\"556\">19</sup>).\nב) גם בזמן הזה יש מצוה באכילת בשר ביו\"ט.\nג) זה שמשמחין הקטנים בקליות ואגוזים והנשים בקניית בגדים ותכשיטין כפי ממונו הוי בכלל ושמחת בחגיך שמ­דאורייתא.\nג. אמנם יש חילוק יסודי בין דברי אדה\"ז לדברי הרמב\"ם:\nהרמב\"ם כתב סתם \"והאנשים אוכלין בשר ושותין יין שאין שמחה אלא בבשר ואין שמחה אלא ביין\", והיינו דשניהם, בשר ויין, שווים (תמיד) בקיום מצות שמחת יו\"ט, אבל אדה\"ז כתב ומפרט \"ועכשיו שאין בהמ\"ק קיים אין יוצאים ידי חובת שמחה אלא ביין. . אבל בשר אין חובה לאכול עכשיו. . ומ\"מ מצוה יש באכילת בשר ביו\"ט כו'\", דאף שיש מצוה באכילת בשר ביו\"ט, מ\"מ בזמה\"ז שאני אכילת בשר ביו\"ט משתיית יין, ד­ביין יוצאים חובת שמחה, משא\"כ בבשר (ש\"אין חובה לאכול עכשיו\").\nוהנה בפשטות י\"ל, שאין אדה\"ז חולק על הרמב\"ם, אלא בא (בהוספה זו) לבאר דבריו (ולתרץ קושיית הבית יוסף<sup data-n=\"557\">20</sup> על הרמב\"ם, ד\"בפ' ערבי פסחים<sup data-n=\"558\">21</sup>: ת\"ר חייב אדם לשמח בניו ובני ביתו ברגל במה משמח ביין ר' יהודה אומר אנשים בראוי להם ונשים בראוי להם. . תניא ריב\"ב אומר בזמן שבה\"מ קיים אין שמ­חה אלא בבשר שנאמר<sup data-n=\"559\">22</sup> וזבחת שלמים ואכלת שם ושמחת ועכשיו שאין בהמ\"ק קיים אין שמחה אלא ביין שנאמר<sup data-n=\"553\">16</sup> ויין ישמח לבב אנוש. . (ותמה הב\"י על דברי הרמב\"ם) למה הצריך שיאכלו בשר וישתו יין דהא בברייתא קתני דב­זמן הזה אין שמחה אלא ביין ומשמע דביין סגי בלא בשר\"):",[["553","16","תהלים קד, טו."],["554","17","הל' יו\"ט פ\"ו הי\"ז­יח."],["555","18","ראה בארוכה שאגת ארי' סי' סה. מנחת חינוך מצוה תפח."],["556","19","תוד\"ה עשה דיחיד (מו\"ק יד, ב)."],["557","20","או\"ח סי' תקכט ד\"ה כתב הרמב\"ם."],["558","21","קט, א."],["559","22","תבוא כז, ז."],["553","16","תהלים קד, טו."]]],[1301430122,"אדה\"ז מפרש דברי הרמב\"ם, דעכשיו שאין ביהמ\"ק קיים יש חילוק בין יין ובשר, דעיקר חובת השמחה הוא ביין (כדאיתא בגמ'), משא\"כ בשר, דאין חובה לאכול בשר אלא מצוה בלבד.\nולכאורה פירוש זה בדברי הרמב\"ם דאיכא נמי שמחה בבשר, יסודו (כמ\"ש הב\"ח<sup data-n=\"557\">20</sup>) מחולין<sup data-n=\"562\">23</sup> ומשבת<sup data-n=\"563\">24</sup> \"והך דערבי פסחים הכי פירושו בזמן שבהמ\"ק קיים עיקר שמחה בבשר שלמים כדכתיב קרא וזבחת שלמים וגו' דאיכא תרתי שמחה חדא שמחת הבאת שלמים לה' אידך שמחת אכילת בשר מה שאין כן ביין דליכא אלא חדא שמחה אבל עכשיו שאין בהמ\"ק קיים אין עיקר שמחה אלא ביין כדכתיב קרא כו' אבל בשר אינו עיקר שמחה דלא אשכחן קרא דכתיב בו שמחה בבשר שאינו של שלמים וזאת היא דעת התוספות שכתבו<sup data-n=\"564\">25</sup>. . במה משמח ביין היינו בזמן הזה אבל בזמן בית המקדש אין שמחה אלא בבשר עכ\"ל פי' בזמן הזה עיקר שמחה ביין ובזמן בית המקדש אין עיקר שמחה אלא בבשר\"<sup data-n=\"565\">26</sup>.\nאבל קשה לפרש כן ברמב\"ם (ולומר שדברי אדה\"ז הם (רק) פירוש בדברי ה­רמב\"ם<sup data-n=\"566\">27</sup>), שהרי מפשטות לשון הרמב\"ם משמע שאין יתרון בשמחה דשתיית יין על אכילת בשר סתם, תמיד גם בזמן הזה.\nועוד זאת: מפשטות לשון הרמב\"ם משמע<sup data-n=\"567\">28</sup> שגם בזמן הבית מצות ושמחת בחגיך מחייבת אכילת בשר ושתיית יין בשווה, שהרי לא הזכיר שום חילוק בין זמן הבית וזמן הזה, ומחלק רק בין ה­שמחה דקרבן שלמים לפרטי השמחה ש\"יש בכלל אותה שמחה לשמוח הוא ובניו כו'\" שהולך ומפרט אח\"כ, שבנוגע לאנשים ה\"ז אכילת בשר ושתיית יין (והיינו אפילו ע\"י אכילת בשר חולין<sup data-n=\"568\">29</sup>) — אבל מדברי אדה\"ז \"והאנשים בזמן שביהמ\"ק הי' קיים היו אוכלין בשר שלמים\" מובן, דקיום מצות שמחה בזמן ביהמ\"ק הי' רק בבשר שלמים (ואין חיוב לאכול בשר ולשתות יין)<sup data-n=\"569\">30</sup>.\nד. ויש לבאר החילוק בין אדה\"ז וה­רמב\"ם בהקדם עוד שינוי בין לשון אדה\"ז ולשון הרמב\"ם:\nא) ברמב\"ם בתחלת הענין כ' \"וחייב",[["557","20","או\"ח סי' תקכט ד\"ה כתב הרמב\"ם."],["562","23","פג, א."],["563","24","קיח, ב ואילך."],["564","25","פסחים שם ד\"ה במה משמחו."],["565","26","ראה גם בישוב דברי הרמב\"ם דרישה לטאו\"ח שם. יש\"ש ביצה פ\"ב ס\"ה. כפות תמרים סוכה מב, ב. ערוך לנר סוכה שם. ועוד."],["566","27","וראה שו\"ע אדה\"ז ר\"ס רמב קו\"א סק\"ב."],["567","28","אף שיל\"ב ע\"פ כללי הרמב\"ם (יד מלאכי כללי הרמב\"ם אות ה) שאינו כותב דינים חדשים."],["568","29","ראה ר\"ן סוכה רפ\"ד וריטב\"א שם דגם בזמן המקדש שמחה בבשר (שלמים) היא רק למצוה מן המובחר, ולא לעכב. וראה גם חמד משה או\"ח סרמ\"ט סק\"ד דבזמן המקדש היתה שמחה אף בבשר חולין וכפשטות לישנא דריב\"ב<sup data-n=\"e15\">*</sup>."],["569","30","מאריכות לשון אדה\"ז (\"אבל בשר אין חובה לאכול עכשיו כיון שאין לנו בשר שלמים ומ\"מ מצוה יש באכילת בשר ביו\"ט כיון שנאמר בו שמחה והואיל וא\"א לנו לשמוח בו בעיקר השמחה שהוא אכילת בשר שלמים יש לנו לשמחו בשאר כל מיני שמחות לכן נהגו להרבות במיני מאכלים בי\"ט יותר מבשבת\"), משמע שיש (באנשים) ג' גדרים בשמחת יו\"ט בזה\"ז: א) חובת שמחה, שהיא ביין, ב) מצות שמחה, שהיא באכילת בשר, ג) מנהג — \"להרבות במיני מאכלים בי\"ט יותר מבשבת\". וראה לקמן הערה 47."],["e15","*","אבל בערוך לנר סוכה שם (ועוד) דדברי ריב\"ב אין שמחה אלא בבשר, מדובר רק בבשר שלמים. וכן משמע לפירוש אדה\"ז בשו\"ע כדלקמן בפנים."]]],[1301430123,"אדם להיות בהן שמח וטוב לב הוא ובניו ואשתו ובני ביתו וכל הנלוים עליו ש­נאמר ושמחת בחגיך\" וממשיך \"אף על פי שהשמחה האמורה כאן היא קרבן שלמים. . יש בכלל אותה שמחה לשמוח הוא ובניו כו'\", ומפרט בהלכה שלאח\"ז \"כיצד, הקטנים וכו'\"; ואילו אדה\"ז מ­סיים תיכף בסעיף הראשון \"חייב אדם להיות שמח וטוב לב כו' ושמחה זו היא מ\"ע מה\"ת שנאמר ושמחת בחגיך גו'\", ובסעיף שלאח\"ז \"כיצד משמחין כו'\", ול­אח\"ז \"והאנשים בזמן שביהמ\"ק הי' קיים היו אוכלין בשר שלמים לשמחה ועכשיו שאין בהמ\"ק קיים אין יוצאין ידי חובת שמחה אלא ביין\", שלא הזכיר בתחילת הענין שהשמחה שנאמרה בכתוב היא קרבן שלמים, כ\"א לאחרי שפרט השמחה של כל סוג בפ\"ע<sup data-n=\"570\">31</sup>.\nב) הרמב\"ם כתב \"שהשמחה האמורה כאן היא קרבן שלמים\", ואדה\"ז כ' \"היו אוכלין בשר שלמים לשמחה\".\nה. ונראה בכ\"ז דחלוקה שיטת אדה\"ז משיטת הרמב\"ם ביסוד המ\"ע של ושמחת בחגיך, דלדעת הרמב\"ם השמחה דקרבן שלמים והשמחה לשמוח הוא ובניו ובני ביתו כל אחד כראוי לו (שבכלל זה הוא מה שהאנשים אוכלין בשר ושותין יין), הרי הם שני דינים וב' סוגי שמחה, אבל אדה\"ז ס\"ל שהם (דין ו)סוג אחד.\nוזהו דיוק ל' הרמב\"ם \"אף על פי שה­שמחה האמורה כאן היא קרבן שלמים. . יש בכלל אותה שמחה לשמוח הוא ובניו כו' כל אחד כראוי לו\", והיינו דאף שזה נכלל בהמ\"ע מה\"ת \"ושמחת בחגיך\", מ\"מ ה\"ז רק שהיא \"בכלל אותה שמחה\", היינו שהיא עוד שמחה הנכללת באותה השמחה, אבל השמחה האמורה בכתוב היא קרבן שלמים.\nאבל לדעת אדה\"ז \"שמחה זו (מה ש­\"חייב אדם להיות שמח וטוב לב הוא ובניו. . וכל הנלוים אליו\") היא (היא ה)מ\"ע מה\"ת שנאמר ושמחת בחגיך אתה ובנך ובתך וגו'\"<sup data-n=\"571\">32</sup>.\nוהיינו דהשמחה דכל אחד כראוי לו, הקטנים בקליות ואגוזים והנשים בבגדים ותכשיטין והאנשים כו' היא היא השמחה האמורה בכתוב \"ושמחת בחגיך אתה גו'\", אלא שאצל האנשים נשתנה אופן קיום השמחה הראוי' להם, דבזמן ש­ביהמ\"ק קיים היו אוכלין בשר שלמים לשמחה ועכשיו שאין ביהמ\"ק כו' חובת השמחה היא ביין<sup data-n=\"572\">33</sup>.\nו. ההסברה בזה:\nלדעת הרמב\"ם \"השמחה האמורה כאן היא קרבן שלמים\", והיינו שחיוב השמחה",[["570","31","ואף שבזה חלוק שו\"ע אדה\"ז מהרמב\"ם, שאדה\"ז בא לומר בעיקר ההלכות הנוגעים \"עכשיו\" בזה\"ז, ולא כברמב\"ם — הרי סו\"ס הביא כאן אופן קיום המצוה בזמן המקדש. ובפרט שמצינו כ\"פ בשו\"ע אדה\"ז שנחית לבאר ולהודיע פרטי ההלכות גם דזמן הבית (ראה לדוגמא הל' פסח ר\"ס תכט), ולא כבשו\"ע המחבר, שכ' רק הדינים שבזה\"ז."],["571","32","ושינוי זה בין הרמב\"ם ואדה\"ז מודגש גם לקמן: ברמב\"ם שם הי\"ט \"אע\"פ שאכילה ושתי' במועדות בכלל מ\"ע כו'\", ובשו\"ע אדה\"ז שם סיו\"ד \"אע\"פ שהאכילה ושתי' במועדות היא מ\"ע\" (ו­השמיט תיבת \"בכלל\" שברמב\"ם)."],["572","33","ולפ\"ז, לכאורה, ג' דיעות בדבר: א) דעת הרמב\"ם דנאמר כאן ב' דינים וסוגים בשמחה: הנאמר בקרא — קרבן שלמים; והנכלל בקרא — שמחה דכ\"א כראוי לו, היינו שאר מיני שמחות כולל אנשים אוכלין בשר ושותין יין, ב) דעת הר\"ן והריטב\"א (הנ\"ל הערה 29), דמצוה מן המובחר הוא באכילת שלמים, וקיום המצוה הזו (אף שאינו מן המובחר) בבשר חולין ובשאר שמחות בזמן הבית, ג) דעת אדה\"ז, קיום \"עיקר השמחה\" בבשר שלמים בזמן המקדש, קיום מצוה זו בזה\"ז — ביין."]]],[1301430124,"אינו אכילת בשר המעוררת שמחה, אלא שמחה מיוחדת בזה שמביא קרבן לה', שזה גופא הוא מעשה השמחה ד\"ושמחת בחגיך\", וכמ\"ש הרמב\"ם בהלכות חגי­גה<sup data-n=\"573\">34</sup> \"והשמחה האמורה ברגלים היא ש­יקריב שלמים יתר על שלמי חגיגה ואלו הם הנקראים שלמי שמחת חגיגה שנאמר וזבחת שלמים ואכלת שם ושמחת לפני ה' אלקיך\". ומפשטות הלשון משמע, ש­מעשה השמחה הוא לא רק אכילת בשר השלמים<sup data-n=\"574\">35</sup>, אלא כללות \"קרבן שלמים\" (הכולל גם הבאתו לפני ה') הוא מעשה השמחה<sup data-n=\"575\">36</sup> ד\"ושמחת בחגיך\"<sup data-n=\"576\">37</sup>.\nומלבד זה \"יש בכלל אותה שמחה לשמוח הוא ובניו ובני ביתו כל אחד כ­ראוי לו\", ושמחה זו אינה מצוה דמעשה של שמחה, אלא עשיית דברים המעור­רים ומביאים שמחה לכ\"א כראוי לו, ומצוה זו מקיימים האנשים באכילת בשר ושתיית יין, גם בזמן הבית (גם בבשר חולין) כי אכילת בשר זה הוא סוג אחר של שמחה, שאוכל בשר ושותה יין ה­מביאים ומעוררים לידי שמחה<sup data-n=\"577\">38</sup>.\nונמצא שבזמן הבית יש באנשים תרי קיומי מצות שמחה: א) חיוב דקרבן שלמים — הבאת קרבן ואכילתו, ב) אכי­לת בשר (חולין<sup data-n=\"578\">39</sup>) ושתיית יין.\nאמנם לדעת אדה\"ז ישנו קיום אחד ד­מצות עשה \"ושמחת בחגיך\", והוא מה ש\"חייב אדם להיות שמח וטוב לב הוא ובניו ואשתו ובני ביתו וכל הנלוים אליו\".\nאלא שאצל אנשים \"עיקר השמחה\" \"הוא אכילת בשר שלמים\", ולכן \"בזמן שביהמ\"ק הי' קיים היו אוכלין בשר שלמים לשמחה, ועכשיו שאין ביהמ\"ק קיים אין יוצאין ידי חובת שמחה אלא ביין\", אבל קיום שמחת אכילת בשר שלמים בזמן ביהמ\"ק אינו שונה בגדרו מקיום מצות שמחה בזמן הזה לאנשים. דיסוד החיוב הוא אכילת בשר (שלמים) ושתיית יין המביאים ומעוררים את ה­אדם לידי שמחה, ורק שאכילת בשר שלמים הוא \"עיקר השמחה\", וכנ\"ל<sup data-n=\"579\">40</sup>.",[["573","34","פ\"א סה\"א."],["574","35","להעיר שהרמב\"ם שם פ\"ב ה\"י פסק (כה­משנה חגיגה ז, ב): יוצאין ישראל יד\"ח שלמי שמחה בנדרים ונדבות כו' והכהנים כו' בחזה ושוק שמצוה זו היא לשמוח באכילת בשר לפני ה' והרי אכלו. אבל ראה מנ\"ח שם דגם להרמב\"ם יכול להיות דצריך להיות לשם שמחה (עדמ\"ש בתוד\"ה עולות — חגיגה ז, ב בסופו לגבי נדרים ונדבות. וראה מנ\"ח שם: א\"כ בבכור ומעשר ג\"כ וכן בחזה ושוק דה­בעלים מביאים לשם שמחת כהנים). וראה גם צל\"ח חגיגה (ו, ב) דלהרמב\"ם מחוייב עכ\"פ פעם אחת בכל ימי החג שיקריבו שלמים לשם שלמי שמחה. ע\"ש. וראה גם שפת אמת יומא ג, א בתוס' ד\"ה פז\"ר. ואכ\"מ."],["575","36","וי\"ל שהוא ע\"ד ומעין הקרבת תודה לה'."],["576","37","ועפ\"ז יומתק מה שפסק הרמב\"ם שם (פ\"א סה\"א) \"ונשים חייבות במצוה זו\", כיון שלדעת הרמב\"ם זהו חיוב השמחה הנאמר בכתוב כאן. וראה לח\"מ שם. לח\"מ פי\"ד מהל' מעה\"ק הי\"ד. ועוד. ואכ\"מ."],["577","38","ראה בכל הנ\"ל צפע\"נ לרמב\"ם הל' יו\"ט פ\"ו הי\"ח. צפע\"נ הל' כלאים פ\"י הכ\"ז (יז, א)."],["578","39","אלא באם נאמר בזה \"בכלל מאתיים מנה\" (ולא שבטלה המנה) לדעת הרמב\"ם יוצאים מצות אכילת בשר סתם (בזמן הבית) גם באכילת בשר שלמים. וצ\"ע שהרי בשלמים משולחן גבוה קאכיל (ב\"ק יב, ב: אבל לאחר שחיטה כו'. פרש\"י שם. קידושין נב, ב ובפרש\"י ד\"ה כי קא זכו. — אבל בתוס' ב\"ק שם דחלק בעלים אפילו אחר שחיטה הוי ממון בעלים. וכבר שקו\"ט בדעת הרמב\"ם (הל' אישות פ\"ה ה\"ה), דמשמע לכאורה שס\"ל כתוס'. ואכ\"מ)."],["579","40","ונמצא דלהרמב\"ם בזמן הזה חסר עיקר קיום מצות שמחה הנאמר בקרא שהיא בקרבן שלמים, ואילו לאדה\"ז יצא ידי חובת שמחה ה­מפורשת בקרא, ולאידך מה שנכלל ב\"ושמחת בחגיך\" להרמב\"ם שוין בזה זמן הבית וזמן הזה, ולאדה\"ז אינו יכול לשמוח עכשיו ב\"עיקר השמחה\"."]]],[1301430125,"ויש לומר, שמחולקים בפירוש הכתוב \"ושמחת בחגיך\" — שלהרמב\"ם \"חגיך\" פירושו \"קרבנך\"<sup data-n=\"580\">41</sup>, והיינו שחייבים לש­מוח ב(הבאת<sup data-n=\"581\">42</sup>) קרבן<sup data-n=\"582\">43</sup>, משא\"כ לאדה\"ז הפירוש ד\"(ושמחת) בחגיך\" קאי על זמן החג, שיש חיוב לשמוח במועדים, אלא שהתורה הוסיפה וקבעה שעיקר קיום ה­שמחה בא ע\"י אכילת בשר שלמים.\nז. ועפ\"ז מובן בפשטות מה שמסיים כאן אדה\"ז \"לכך נהגו להרבות במיני מאכלים בי\"ט יותר מבשבת שלא נאמר בה שמחה\":\nלפי הנ\"ל הרי לשיטת אדה\"ז גדר מצות שמחה ביו\"ט אינו מעשה השמחה השייכת לשמיא (כדעת הרמב\"ם שה­שמחה האמורה כאן הוא קרבן שלמים), אלא שמחה (טבעית) הבאה ע\"י אכילת בשר ושתיית יין באנשים (ובנשים וקט­נים בראוי להם כנ\"ל), ורק שעיקר שמ­חה זו היא אכילת בשר שלמים בזמן ה­בית, משא\"כ השמחה שנאמרה בשבת היא \"וביום שמחתכם\", והיינו<sup data-n=\"583\">44</sup> שמהותה של שמחה זו היא שמחה דשמיא ולא שמחה טבעית הבאה ע\"י אכילת בשר ושאר דברים המשמחים<sup data-n=\"584\">45</sup>.\nוכן מובן גם מדעת ר\"נ בספרי שם דפליג את\"ק וס\"ל ד\"וביום שמחתכם אלו תמידים\", והרי תמידים הם עולות שאין בהם אכילת אדם, ואין שמחתם אלא שמחת הקרבת קרבן<sup data-n=\"585\">46</sup>, די\"ל שמזה מובן גם לדעת ת\"ק, דמ\"ש \"וביום שמחתכם אלו שבתות\", היינו שמחה שכל כולה היא שמחה דשמיא.\nח. אמנם, אף שלפי בי' הנ\"ל באדה\"ז גדרה ויסודה דשמחת שלמים אינו שמ­חה דשמיא אלא בכלל שמחה הטבעית ע\"י דברים המביאים ומעוררים לידי שמחה, כל אחד כפי הראוי לו — מ\"מ, לאידך גיסא, הרי דוקא לפי אדה\"ז יוצא, שהשמחה דאכילת בשר דיו\"ט קשורה עם אכילת קדשים.\nדלהרמב\"ם הרי שמחת האנשים \"כ­ראוי\" להם אין לה שייכות עם שמחת השלמים, אלא הוא חיוב בפ\"ע המתקיים גם ע\"י אכילת בשר חולין ושתיית יין (כנ\"ל), ואינה אלא שמחה גשמית; משא\"כ אדה\"ז שכתב בפירוש (כנ\"ל) שעיקר השמחה היא אכילת בשר שלמים, הרי אין זו שמחה גשמית בלבד, אלא שמחה",[["580","41","וראה ל' הרמב\"ם הל' חגיגה פ\"א סה\"א (נעתק לעיל בפנים) \"שלמי שמחת חגיגה\"."],["581","42","ראה רמב\"ם הל' בכורים פ\"ג הי\"ב (בסופו)."],["582","43","לא מיבעי להמפרשים דמקורו של הרמב\"ם הוא ברייתא דריב\"ב פסחים שם, שמפורש בקרא וזבחת שלמים ואכלת גו', ולמדין \"ושמחת בחגיך\" משם (ראה כס\"מ לרמב\"ם הל' חגיגה פ\"א סה\"א) — אלא גם את\"ל דהרמב\"ם פסק כבחגיגה (ח, סע\"א ואילך) \"לרבות כל מיני שמחות\" (ראה ערוך לנר סוכה שם), אעפ\"כ מפורש שם רק שמחת קרבנות."],["583","44","נוסף על הפשוט, שבשבת לא נאמר בה שמחה היינו שלא נאמר בה ציווי וחיוב על שמחת האדם כביו\"ט (שנאמר בה ושמחת בחגיך) כ\"א רק \"וביום שמחתכם\", וי\"ל שזהו דיוק לשון הירושלמי (הובא לעיל בס\"א) \"ששמחתו תלוי' בידי שמים\"."],["584","45","להעיר מתו\"ח חולין ספ\"א — הובא בשד\"ח שבהערה 8 (א'תק, ג­ד) — שמפרש שהשמחה בשבת היא \"שמחה רוחנית\". אלא דשם מפרש הכוונה ד­\"ישמחו בהקב\"ה\", \"ישמחו ישראל במלכותו יתברך\" (ע\"ש), משא\"כ להמבואר בפנים, השמחה היא במעשה (בכל מעשי שבת), ורק דתוכנו הוא שמחה דשמיא (ע\"ד השמחה דהקרבת קרבן), כבפנים."],["585","46","ראה בארוכה במפרשים שם (תולדות אדם. ספרי דבי רב. ועוד), דמכח התמידים נקרא כל יום יום שמחה כדאיתא בירושלמי והובא בתוס' רפ\"ד דפסחים דביום הקרבת קרבן הי' מן הדין להיות יו\"ט. ע\"ש בספרי דבי רב בארוכה."]]],[1301430126,"של מצוה, ושיש בה קדושה (אכילת קדשים).\nויש לומר, שגם השמחה בזמן הזה צ\"ל (לדעת אדה\"ז) באופן שמודגש שאינה סתם שמחה גשמית, אלא היא שמחה של מצוה ותורה. ויומתק עפ\"ז לשון אדה\"ז בהדין שעכשיו אין יוצאים ידי חובת שמחה אלא ביין, שמביא ע\"ז לשון הכתוב \"שנאמר ויין ישמח לבב אנוש\" (אף שהרמב\"ם לא הביא הכתוב) — וי\"ל שכוונתו בזה להדגיש שקיום חובת שמחה צ\"ל מיוסד אך ורק על תורה, ולכן הוא רק על ידי שתיית יין (ולא ע\"י \"שאר מיני שמחות\", כמו אכילת בשר) — כי רק בנוגע ליין \"אשכחן קרא\" (בלשון הב\"ח) שטבעו לשמח \"לבב אנוש\" (משא\"כ \"בשר (שאינו של שלמים). . לא אשכחן קרא דכתיב בו שמחה\").\nואתי שפיר גם המשך לשון אדה\"ז בנוגע לאכילת בשר בזה\"ז, \"מצוה יש ב­אכילת בשר ביו\"ט כיון שנאמר בו שמחה והואיל וא\"א לנו לשמוח בו בעי­קר השמחה שהוא אכילת בשר שלמים יש לנו לשמחו בשאר כל מיני שמחות\", דמאריכות לשונו משמע, שאכילת בשר בזה\"ז היא (לא סתם שמחה, אלא) כעין המשך לאכילת בשר שלמים בזמן בהמ\"ק. וע\"פ הנ\"ל י\"ל, כי גם השמחה מאכילת בשר בזה\"ז<sup data-n=\"586\">47</sup> צ\"ל דרך קדושה כו' (ולא רק שמחה גשמית), כעין ה­שמחה באכילת בשר קודש<sup data-n=\"587\">48</sup>.\nובזה יש לבאר גם את החילוק בסדר ההלכות בין הרמב\"ם ושו\"ע אדה\"ז:\nהרמב\"ם, לאחרי שמפרט את אופני השמחה ומסיים \"והאנשים אוכלין בשר ושותין יין שאין שמחה אלא בבשר ואין שמחה אלא ביין\", ממשיך באותה הלכה<sup data-n=\"588\">49</sup> \"וכשהוא אוכל ושותה חייב ל­האכיל לגר ליתום ולאלמנה כו' אבל מי שנועל דלתות חצרו ואוכל ושותה הוא ובניו ואשתו ואינו מאכיל ומשקה לעניים ולמרי נפש אין זו שמחת מצוה אלא שמחת כריסו ועל אלו נאמר כו'\".\nמשא\"כ בשו\"ע אדה\"ז, אף שגם הוא מביא דינים אלה, לא כתבם באותו סעיף, אלא לאחרי כמה סעיפים<sup data-n=\"589\">50</sup> (מהם<sup data-n=\"590\">51</sup> שמקורם ג\"כ ברמב\"ם אלא שב­רמב\"ם באו לאחרי הלכה זו<sup data-n=\"591\">52</sup>).\nוע\"פ הנ\"ל מבואר, כי לדעת הרמב\"ם יש כאן ב' שמחות: א) שמחת קרבן שלמים שאינה שמחה טבעית אלא מעשה של שמחה דשמיא. ב) שמחה דכל אחד ואחד, שהיא שמחה טבעית, והיא מבו­ארת בהלכה יח, ולכן צריך הרמב\"ם ל­הוסיף תומ\"י באותה הלכה דבנוגע ל­שמחה טבעית זו \"וכשהוא אוכל ושותה חייב להאכיל כו' אבל מי שנועל כו' אין זו שמחת מצוה אלא שמחת כריסו כו'\".\nמשא\"כ לשיטת אדה\"ז, שגם השמחה דכ\"א כראוי לו אינה שמחה טבעית פשו­טה, אלא היא חלק (והסתעפות) מ\"עיקר השמחה שהוא אכילת בשר שלמים\", ו­היינו שגם באכילת בשר ושתיית יין נרגש שעיקר השמחה היא המשך למה שהיו מקיימים בזמן \"שביהמ\"ק הי' קיים (ש)היו אוכלין בשר שלמים לשמחה\" — לכן, אף שצריך לומר ולהשמיענו הדין",[["586","47","וכן \"שאר כל מיני שמחות\" ומה ש\"נהגו להרבות במיני מאכלים בי\"ט\", מדגיש בשו\"ע אדה\"ז שם שבא בהמשך לעיקר השמחה שהוא אכילת בשר שלמים."],["587","48","ראה לקו\"ת שמיני יח, ג."],["588","49","הי\"ח."],["589","50","בסי\"א."],["590","51","ס\"י."],["591","52","הי\"ט."]]],[1301430127,"ד\"כשהוא אוכל ושותה חייב להאכיל לגר וליתום ולאלמנה. . אבל מי שנועל דלתי חצרו כו' ואינו מאכיל ומשקה כו' אין זו שמחת מצוה כו'\", מ\"מ אין להו­סיפו בחדא מחתא עם גוף חיוב ומצות שמחת יו\"ט.\nט. ביאור פלוגתת הרמב\"ם ואדה\"ז בפנימיות הענינים:\nבדרושי אדמו\"ר הזקן מבואר<sup data-n=\"592\">53</sup> הטעם ששמחת יו\"ט היא ע\"י הקרבת שלמי שמחה: עיקר השמחה היא לשמוח בו ית', כמאמר<sup data-n=\"593\">54</sup> \"וישמחו בך כל ישראל\", דהגם ששמחה כזו צ\"ל כל השנה, עכ\"ז היו\"ט נקרא \"מועדים לשמחה\", שאז השמחה של מצוה היא ביתר שאת ויתר עז מחמת תוספת גילוי אור, אלא שבכדי שגילוי השמחה בה' יהי' גם בנפש ה­בהמית, המסתרת ומעלמת על ניצוץ אלקי שבנפש האדם ומונעת השמחה בהשם, הקריבו שלמי שמחה שזהו כדי לשמח גם את נפש הבהמית.\nאבל בזה גופא, הפעולה בנפש ה­בהמית, יש לבאר בשני אופנים: א) עיקר שמחת יו\"ט, שהיא השמחה בו ית', היא רק בנפש האלקית, ופעולת הקרבת ה­שלמים היא רק להסיר ההעלם והסתר שמצד נפש הבהמית, שמונעת גילוי ה­שמחה של נפש האלקית. ב) הפעולה ב­נפש הבהמית היא לא רק להסיר המניעה שבה, אלא שגם היא עצמה תרגיש השמחה בה'.\nויש לומר, שזהו החילוק (בפנימיות) בין שיטת הרמב\"ם ושיטת אדה\"ז:\nלדעת הרמב\"ם, השמחה האמורה ב­כתוב \"ושמחת בחגיך\" \"היא קרבן של­מים\", שאין זו שמחה טבעית וגשמית אלא רק שמחה בה', והיא שמחת נפש האלקית בו ית'; אלא ש\"יש בכלל אותה שמחה לשמוח. . כל אחד כראוי לו. . אוכלין בשר ושותין יין כו'\", כי<sup data-n=\"594\">55</sup> כדי שלא תהי' מניעה מצד נפש הבהמית על שמחת נפש האלקית, צריכים גם לפעו­לה מיוחדת לבטל התנגדותה לשמחת יו\"ט, וזהו ע\"י שמשמחין אותה בשמחה טבעית וגשמית, \"כל אחד כראוי לו\".\nאבל דעת אדה\"ז היא, ששמחת יו\"ט צ\"ל באופן שגם נפש הבהמית תרגיש השמחה העיקרית שבשמחת יו\"ט, שהיא השמחה בו ית', ולכן ס\"ל ש\"ושמחת ב­חגיך\" היינו ע\"י אכילת בשר שלמים, שבזה יש שני הקצוות: השמחה היא מ­אכילת בשר, הפועלת שמחה טבעית אצל הגוף ונפש הבהמית, אבל ביחד עם זה ה\"ה אכילת קדשים, שנרגש באכילה זו ענין של קדושה — והיינו, שגם בנפש הבהמית נרגש ענין השמחה בו ית'.\nויש לומר, שהרמב\"ם ואדה\"ז אזלי בזה לשיטתייהו:\nדעת הרמב\"ם<sup data-n=\"595\">56</sup> היא<sup data-n=\"596\">57</sup>, דעוה\"ב אין בו לא אכילה כו', שתכלית שלימות השכר היא לנשמות בלא גופים<sup data-n=\"597\">58</sup>, ולכן ס\"ל ד­השמחה האמורה כאן היא קרבן שלמים, שאינה שמחה הקשורה לגוף ונפש ה­בהמית כ\"א שמחה אלקית של הנשמה",[["592","53","בכל הבא לקמן ראה לקו\"ת צו (טו, ב), סה\"מ תקס\"ח ד\"ה ויהי הענן (ע' קעא, קעח). מאמרי אדמו\"ר האמצעי ויקרא ח\"א ע' קלב ואילך. ועוד."],["593","54","נוסח תפלת העמידה דיו\"ט."],["594","55","להעיר ממשל הבעש\"ט (כתר שם טוב סי' קז. שצב) לענין עונג שבת בחומר."],["595","56","הובאה במקומות שבהערה 53. סהמ\"צ שבהערה 58. ועוד."],["596","57","הל' תשובה פ\"ח ה\"ב ואילך. פיה\"מ סנהדרין פ' חלק."],["597","58","ראה בארוכה סהמ\"צ להצ\"צ מצות ציצית."]]],[1301430128,"(ושמחת הגוף ונפש הבהמית באכילת בשר ושתיית יין היא רק כדי שלא יבל­בלו את שמחת הנפש האלקית, כנ\"ל).\nאבל ההכרעה בתורת החסידות<sup data-n=\"598\">59</sup> היא כדעת<sup data-n=\"595\">56</sup> הרמב\"ן<sup data-n=\"600\">60</sup> שתכלית שלימות ה­שכר היא לנשמות בגופים דוקא, הכוונה היא לעשות לו ית' דירה בתחתונים<sup data-n=\"601\">61</sup>, ואשר תכלית ושלימות הגילוי יהי' דוקא בזמן תחיית המתים לנשמה בגוף, והיינו לפי שהעבודה במשך שית אלפי שנין דהוי עלמא ובפרט בזמן הגלות אינה רק לפעול גילוי הנשמה, אלא גם בירור וזיכוך הגוף ונפש הבהמית; ועד\"ז הוא גם לגבי שמחת יו\"ט, דעיקר השמחה לשמוח בה' היא לא רק להנשמה אלא הכוונה לפעול שמחה זו גם בנפש ה­בהמית.\nולכן לדעת אדה\"ז בשו\"ע גדר ה­שמחה היא שמחה השייכת להגוף, שתיית יין ואכילת בשר, וגם יסוד ה­שמחה ועיקר השמחה אינו שמחת קרבן שלמים כ\"א אכילת בשר שלמים, כי שמחת ה' צריך שיורגש ויחדור בהגוף הגשמי כפשוטו.\n<span data-k=\"q\">(משיחת יום שמח\"ת תש\"מ)</span>",[["598","59","ראה במקומות שבהערה 53. תשובות וביאורים (קה\"ת, תשל\"ד) סי\"א<sup data-n=\"e16\">*</sup> (לקו\"ש ב\"עניני גאולה ומשיח\" ע' סג) — בארוכה."],["595","56","הובאה במקומות שבהערה 53. סהמ\"צ שבהערה 58. ועוד."],["600","60","שער הגמול בסופו."],["601","61","תנחומא נשא טז. תניא פל\"ו."],["e16","*","נדפס גם באג\"ק כ\"ק אדמו\"ר שליט\"א ח\"ב ע' סה. המו\"ל."]]],[1301430129,"<h3>שיחה ג</h3>\nא. \"זכרנו את הדגה אשר נאכל ב­מצרים חנם את הקשואים ואת האבטחים ואת החציר ואת הבצלים ואת השומים\"<sup data-n=\"602\">1</sup>, ובפרש\"י — על התיבות \"את הקשואים\"<sup data-n=\"603\">2</sup> — מביא (מספרי<sup data-n=\"604\">3</sup>) \"אמר רבי שמעון מפני מה המן משתנה לכל דבר חוץ מאלו מפני שהן קשים למניקות, אומרים לאשה אל תאכלי שום ובצל מפני התינוק, משל למלך כו' כדאיתא בספרי\".\nוהנה ברמב\"ן פירש טענת בנ\"י \"זכרנו גו' אשר נאכל במצרים גו'\", שזהו \"כזו­כר הנשכחות, כי לא אכלו דגים מיום צאתם ממצרים ועד הנה, וטעם. . חנם כפי פשוטו כי היו הדייגים המצריים מעבידין אותן למשוך הדגים כו' והיו נותנין להם מן הדגים<sup data-n=\"605\">4</sup> כו' והקשואים והאבטחים והחציר והבצלים והשומים במצרים הרבה מאד כי היא כגן הירק<sup data-n=\"606\">5</sup> וכאשר היו חופרין להם בגנות היו אוכ­לין מן הירקות\". ולפי פירושו היתה כאן טענה אחת בלבד, שבמדבר חסרו אותם המאכלים שאכלו במצרים \"חנם\" (ועד\"ז פירשו רוב פשטני המקרא<sup data-n=\"607\">6</sup>);\nאבל רש\"י חילק את הכתוב לשנים, דעל התיבות \"אשר נאכל במצרים חנם\" פירש (ע\"פ הספרי<sup data-n=\"608\">7</sup>) \"חנם מן המצות\"<sup data-n=\"609\">8</sup>, ועל \"את הקשואים\" מפרש (כנ\"ל) שהמן לא הי' משתנה בטעמו לחמשת<sup data-n=\"610\">9</sup> המינים הללו (קשואים, אבטחים, חציר, בצלים, שומים) — והיינו שהיו כאן שתי טענות נגד ה\"מן\": א) שהמן תלוי בעשיית מצות<sup data-n=\"611\">10</sup>, משא\"כ הדגה שאכלו במצרים היתה \"חנם מן המצות\"<sup data-n=\"612\">11</sup>, ב) במצרים היו להם גם חמשת המינים דקשואים כו', ואילו במדבר חסרים מינים אלה, לפי ש\"המן משתנה לכל דבר חוץ מאלו\".\nויש לומר, שהכרחו של רש\"י לחלק את הכתוב לשנים, מרמז בהתיבות ש­העתיק מהכתוב — \"את הקשואים\", דל­פירוש הרמב\"ן שכל הכתוב הוא המשך",[["602","1","פרשתנו יא, ה."],["603","2","ראה לקמן הערה 13."],["604","3","עה\"פ. — וראה יומא (עה, א) ב' דיעות: אם לא נשתנה כלל למינים אלו, או שנשתנה רק טעמן ולא ממשן. וראה מפרשי הספרי, שזוהי גם פלוגתת ר\"ש וחכמים בספרי שם. ואכ\"מ."],["605","4","ובפי' הב' — שקיבלו כ\"ז ב\"מנת המלך\". ומציין לפירושו לעיל בפ' שמות (א, יא). ע\"ש."],["606","5","עקב יא, י."],["607","6","ראה ראב\"ע, חזקוני, בחיי, אברבנאל ועוד."],["608","7","וכ\"ה בתיב\"ע עה\"פ: בלא תפקידתא."],["609","8","ולא כפשוטו. ולהעיר מב' הדיעות בגמרא (יומא שם)."],["610","9","כ\"ה ל' הספרי כאן \"חוץ מחמשת המינים הללו\", ובפרש\"י \"חוץ מאלו\". אבל נראה פשוט, שזהו רק בשביל קיצור לשון [ולא שכוונת רש\"י לכלול בזה עוד מין ששי וכו' — \"דגה\" הנזכר בקרא לפנ\"ז — כפי' התו\"ת כאן (ע\"פ כתובות ס, ב שדגים קטנים קשים למניקות). וראה גם משמרת הקודש על פרש\"י כאן — דא\"כ הו\"ל לרש\"י לפרש זה על תיבת \"הדגה וגו'\"]."],["611","10","דיש לומר, שכוונת תלונתם היא לא רק שעתה חייבים במצוות בכלל (כפי' הרא\"ם ועוד), אלא שהמן גופא יש בו כמה מצות (ראה רש\"י בשלח טז, ד)."],["612","11","ומה שנקט הכתוב \"דגה\" דוקא (אף שכל אכילתם במצרים היתה \"חנם מן המצות\") — י\"ל בפשטות, דגם רש\"י ס\"ל כדברי הרמב\"ן שהמינים שנמנו בקרא כאן היו עיקר מאכלם של ישראל במצרים, אלא שטענתם (לגבי המן) נתחלקה לב', כבפנים."]]],[1301430130,"אחד הול\"ל<sup data-n=\"613\">12</sup> \"ואת הקשואים\"; ומזה ש­אומר \"את\", מוכח שמכאן מתחיל ענין (טענה) חדש<sup data-n=\"614\">13</sup>.\nב. אבל צ\"ע בעצם פירושו:\nדהנה ז\"ל מאמר ר\"ש בספרי: \"ר' שמעון אומר מפני מה המן משתנה להם לכל דבר שהיו רוצים חוץ מחמשת ה­מינים הללו, משל למלך בשר ודם ש­מסר בנו לפדגוג והי' יושב ומפקדו ו­אומר לו הנראה שלא יאכל מאכל רע כו' ובכל כך הי' הבן ההוא מתרעם על אביו לומר שלא מפני שאוהבני אלא שאי אפשר לו [שאין רצונו] שאוכל\".\nהרי יש כאן שינוי גדול בין לשון הספרי ולשון רש\"י — שבספרי לא הובא אלא המשל, ואילו רש\"י מוסיף ביאור ופירוש<sup data-n=\"615\">14</sup> (בדברי ר\"ש) \"מפני שהן קשים למניקות, אומרים לאשה אל תאכלי שום ובצל מפני התינוק\".\nוצ\"ע מנ\"ל לרש\"י לפרש שכוונת ר\"ש היא, שמאכלים אלו קשים רק למניקות, ולא כפשטות משמעות המשל שהם מאכלים רעים סתם — לכל<sup data-n=\"616\">15</sup>?\nוביותר תמוה: בגמ'<sup data-n=\"617\">16</sup> מפורש \"למה נקרא שמן קשואין מפני שהן קשין לכל גופו של אדם כחרבות\", הרי מפורש שקשואים הם מאכל רע לכל אדם (ולכל גופו), ועד שזה נרמז בשמם<sup data-n=\"618\">17</sup>; וא\"כ ודאי שדברי ר\"ש יכולים להתפרש כפשוטם, שמינים הללו הם \"מאכלים רעים\" בכלל [והרמב\"ם בהל' דעות<sup data-n=\"619\">18</sup> מנה \"החציר והבצלים והשומים\" (ג' מינים האחרונים כאן) בין \"מאכלים רעים. . (ש)אין ראוי לאדם לאכול מאלו אלא מעט עד מאד ובימות הגשמים\"] — ומנ\"ל לרש\"י להג­ביל דברים הסתמיים של ר\"ש, ולומר שכוונתו שהם קשים רק למניקות?!\n[מקורו של ענין זה \"אומרים לאשה אל תאכלי שום ובצל מפני התינוק\" — הוא בספרי (כמובא גם בפרש\"י לש\"ס<sup data-n=\"620\">19</sup>), אלא שהוא בספרי להלן — על הפסוק<sup data-n=\"621\">20</sup> \"והי' טעמו כטעם לשד השמן\", שא' ה­פירושים בספרי הוא<sup data-n=\"622\">21</sup> \"מה הדד הזה [\"לשד\" לשון שדים] שהוא מין אחד ומש­תנה למינים הרבה, כך הי' המן משתנה להם לישראל לכל דבר שהם רוצים, משל אומר לאשה אל תאכלי שום ובצל מפני התינוק\" (וכמבואר במפרשים<sup data-n=\"623\">22</sup>, ש­",[["613","12","כקושיית האלשיך כאן. ולהעיר מרבותינו בעה\"ת (דעת זקנים) כאן."],["614","13","ועפ\"ז מתורץ למה העתיק רש\"י בהד\"ה רק התיבות \"את הקשואים\", אף שפירושו קאי על כל המינים שנמנו אח\"כ בקרא, ועכ\"פ הו\"ל להוסיף \"וגו'\" — כי עיקר ההדגשה בפרש\"י היא על תיבת \"את\", שמזה מוכח שמכאן מתחיל ענין חדש, וע\"ז מביא מאמר ר\"ש \"מפני מה כו'\"."],["615","14","ראה לקמן בסוף הסעיף והערה 23."],["616","15","וראה גם ספרי דבי רב לספרי כאן. עיון יעקב לע\"י יומא שם."],["617","16","ע\"ז כט, א. — ושם (יא, א) ובברכות (נז, ב) — בלי תיבת \"לכל\", ומחלק בין רברבי וזוטרי<sup data-n=\"e17\">*</sup>. והועתק גם ביל\"ש פרשתנו כאן."],["618","17","וראה ראב\"ע כאן."],["619","18","פ\"ד ה\"ט (הובא גם בעיון יעקב לע\"י שם)."],["620","19","יומא שם ד\"ה הללו — וג\"כ לראי' שהמן לא נשתנה לה' מינים הללו כי הם \"קשין לעוברות ומניקות\"."],["621","20","יא, ח."],["622","21","וראה יומא שם, סע\"א."],["623","22","ראה ספרי דבי רב, שי\"ג כן בספרי \"לכל דבר שהם רוצים, חוץ מן הכרתי כו' משל אומר כו'\". ועד\"ז היא גירסת הגר\"א. ועוד.\nאבל להעיר מפי' העמק הנצי\"ב שם, שכוונת המשל (\"אומר לאשה אל תאכלי כו'\") היא להוכיח שהחלב משתנה לפי המאכל שאוכלת האם (וראה רש\"י יומא שם). וכן משמע מלשון הספרי זוטא שם \"מה הדד הזה כו' ובו מינים הרבה לכך אומרין לאשה אל תאכלי. . בשביל התינוק\"."],["e17","*","שלא יוקשה מהא \"שלא פסקו מעל שולחנם (דרבי ואנטונינוס) לא חזרת ולא קישות כו'\". ול­העיר, שבפרש\"י תולדות (כה, כג) השמיט \"קישות\". ואכ\"מ."]]],[1301430131,"כוונת הספרי שהי' משתנה לכל טעם חוץ מאלו שקשים למניקות \"מפני התי­נוק\")\nאבל ענין זה לא הובא במאמר ר\"ש<sup data-n=\"624\">23</sup>. זאת ועוד: שם הובאו רק שני מינים \"שום ובצל\" — ואין מזה ראי' שגם שאר ג' המינים הם קשים למניקות].\nג. גם יש להבין כמה דיוקים בלשון רש\"י, ומהם:\nא) רש\"י לא העתיק עיקר מאמרו של ר\"ש, שהוא המשל ממלך בשר ודם כו', ומביא רק התחלתו, \"משל למלך וכו' כדאיתא בספרי\". ואע\"פ שרש\"י מוסיף הביאור למה לא נשתנה טעם המן למי­נים אלו (כנ\"ל), מ\"מ, אין בדברי רש\"י שום הסברה לתוכן התלונה של בנ\"י, שזה מוסבר רק במשל ר\"ש, שהבן חושב שהטעם שאביו צוה שלא ליתן לו מאכלים אלו הוא לפי שאינו רוצה ש­יהנה מטיב מאכלים אלה (\"אי אפשר לו שאוכל\").\nב) למה מעתיק רש\"י גם שם בעל המאמר — ר' שמעון?\nוכמשנ\"ת כמ\"פ, שכוונת רש\"י בהבאת שם בעל המאמר במקומות ספורים בפי­רושו (אף שברוב המקומות אינו מביא דבר בשם אומרו) היא לרמז על תוס' הסברה בתוכן פירושו, ע\"י הידיעה ש­מאמר זה אמרו תנא (או אמורא) פלוני.\n[ושני דיוקים אלו בולטים יותר, כש­משווים פרש\"י זה לפירושו כמה פסוקים לפנ\"ז, עה\"פ<sup data-n=\"625\">24</sup> \"ויצעק העם אל משה\", שכ' שם \"משל למלך בו\"ד שכעס על בנו והלך הבן אצל אוהבו של אביו וא\"ל צא ובקש עלי מאבא\", שגם משל זה מקורו בספרי על אתר ובעל המאמר הוא ר' שמעון — ושם (א) העתיק רש\"י כל ה­משל (ולא ציין שמקורו בספרי), (ב) השמיט שם בעל המאמר!].\nג) כאן כתב רש\"י \"מפני שהן קשים למניקות\", אבל בפירושו לש\"ס<sup data-n=\"626\">25</sup> כתב שהמן לא נשתנה לחמשה מינים הללו לפי שהם \"קשין לעוברות ומניקות\". וצ\"ע הטעם שרש\"י השמיט בפירושו על התורה \"לעוברות\"<sup data-n=\"627\">26</sup> [שהרי הטעם \"מפני התינוק\" שייך לכאורה לעוברות כמו למניקות. ועוד זאת: מסתבר — ובפרט בלימוד ע\"ד הפשט — להגדיל ככל האפשר מספר בנ\"י שבגללם לא נשתנה המן למינים הללו, וא\"כ ודאי שהו\"ל לרש\"י בפירושו עה\"ת להוסיף שגם ל­עוברות הם קשים].\nד) למה מקדים רש\"י \"שום\" ל\"בצל\" (\"אל תאכלי שום ובצל\") — היפך סדרם בקרא<sup data-n=\"628\">27</sup> — \"ואת הבצלים ואת השומים\".\nד. ויש לומר הביאור בכל זה — ב­פשטות:\nבפסוק זה מבוארת טענת בנ\"י על",[["624","23","ואף שרש\"י מביאו כאן בשם ר\"ש — י\"ל (א) אין כוונתו שזהו לשון ר\"ש אלא הוספת ביאור רש\"י בדבריו [וכמשנ\"ת כמ\"פ שזוהי דרכו של רש\"י בפירושו עה\"ת, לשנות מלשון חז\"ל בהתאם ל­פשש\"מ, גם כשמביא דבר בשם אומרו], (ב) דברי הספרי דלקמן הם סתמא דספרי, וסתם ספרי ר\"ש (סנהדרין פו, א). וראה ספרי כאן פסוק ו."],["625","24","יא, ב."],["626","25","הנ\"ל הערה 19."],["627","26","ולאידך, בפרש\"י לש\"ס שם השמיט \"שום\" — נת' בההתועדות (בה נאמרה שיחה זו)."],["628","27","אף שכ\"ה גם בספרי, הו\"ל לרש\"י לשנות בהתאם לפשש\"מ, כנ\"ל הערה 23."]]],[1301430132,"משה רבינו שיש חסרון במצבם במדבר לגבי מצבם במצרים. ולפי זה, את\"ל שמאכלים אלו הם מאכלים רעים וקשים לגופו של אדם — אין מקום לטענה \"זכרנו גו' אשר נאכל במצרים\"<sup data-n=\"629\">28</sup>, ואד­רבה, הי' להם להודות שעתה אין מקום למאכלים רעים!\nואע\"פ שע\"ז הביא ר\"ש משל מבן המלך שהי' \"מתרעם על אביו לומר שלא מפני שאוהבני [ורוצה למנוע ממנו מאכלים רעים] אלא שאי אפשר לו ש­אוכל\", וכן בנמשל, שבנ\"י התרעמו על הקב\"ה \"לומר שלא מפני שאוהבני אלא שאי אפשר לו שאוכל\" — לכאורה אין זה ביאור מספיק, דבשלמא במשל שהמ­דובר בבן קטן, מובן שמתרעם על אביו (אף שה\"פדגוג\" שלו אומר לו שזה מאכל רע) להיותו מתאווה אל מאכלים רעים; אבל בנמשל קשה לומר שבנ\"י יטענו טענה שאין לה יסוד (כיון שלפי המצי­אות המפורסמת, במציאות הי' כ\"ז לטוב­תם, למנוע מהם מאכלים רעים הקשים לגופו של אדם). ועכ\"פ הו\"ל למשה להשיבם שטענתם בטעות יסודה, ואד­רבה, מניעת מאכלים אלו היא לטובתם.\nואין לתרץ ע\"פ פרש\"י עה\"פ (ש­לפנ\"ז<sup data-n=\"630\">29</sup>) \"מי יאכילנו בשר\" — \"וכי לא הי' להם בשר והלא כבר נאמר. . וצאן ובקר. . אלא שמבקשים עלילה\" — כי אינו דומה לעניננו, דזה שהי' להם צאן ובקר הי' במספר מוגבל, עד שגם משה רבינו אמר להקב\"ה \"שש מאות אלף רגלי העם גו' הצאן ובקר ישחט להם ומצא להם גו'\"<sup data-n=\"631\">30</sup>, וא\"כ הי' קצת מקום לעלילה זו; משא\"כ כאן, הרי כל התלו­נה אין לה יסוד, דאדרבה, זהו מטובו וחסדו של הקב\"ה שמנע מהם מאכלים רעים!\nולכן פרש\"י, שמינים אלו קשים רק למניקות בלבד, אבל אינם מאכלים רעים לכל אדם. וזו היתה תלונתם של בני ישראל: מפני מה נמנע מהם טעמם של מאכלים אלו אך ורק בגלל שאינם מאכלים טובים למניקות — וכי לא הי' אפשר להקב\"ה לעשות שרק אצל המני­קות לא ישתנה המן למינים אלו, ואילו אצל כל ישראל לא יחסר טיב המאכלים ההם<sup data-n=\"632\">31</sup>.\nומטעם זה לא העתיק רש\"י את כל משלו של ר\"ש — כי אין המשל מכוון לנמשל, שכוונת האב (במשל) היא למנוע מבנו מאכלים רעים, ואילו בנמשל נמנעו מכל בנ\"י מאכלים אלו (לא לפי שאינם טובים להם, אלא) רק בגלל המיעוט מ­בנ\"י, המניקות, שעבורם הם קשים (\"מפני התינוק\").\nולכן מביא רש\"י רק תחלת המשל (ומציין לספרי), לרמז, שתוכנה של תלו­נת בנ\"י הוא בדומה לתלונת הבן<sup data-n=\"633\">32</sup>, שחו­",[["629","28","ע\"ד קושיית הבאר מים חיים (לאחי ה­מהר\"ל) על פי' הב' ברמב\"ן כאן, שהיו נותנין להם דגים קטנים ממנת המלך — דאיזה שבח יש בזה. וראה מעשה ה' עה\"ת כאן."],["630","29","פסוק ד. וראה גם רש\"י לפנ\"ז — שם, א ד\"ה כמתאוננים."],["631","30","לקמן שם, כא­כב (וראה רש\"י שם)."],["632","31","ראה גם הרי\"ף לע\"י יומא שם. ספרי דבי רב לספרי כאן."],["633","32","וי\"ל, שכוונת רש\"י בהעתיקו תיבת \"(משל) למלך\" — אינה רק לציין התחלת המשל, אלא מפני שתיבה זו היא נקודת התלונה, דאם הי' המדובר ב\"אב\" סתם, לא הי' מקום לתלונה — כי אפשר שאין ביכולתו לתת לבנו כל מאכל שרוצה, משא\"כ המלך שכלום חסר בבית המלך. וכ\"ש בנמשל, בנוגע ל­ממה\"מ הקב\"ה, דהיפלא מה' דבר — שרק להמני­קות לא יהיו מינים אלו ולא יחסרו אצל שאר כל בנ\"י. ולכן התלוננו שאין הקב\"ה רוצה שיהנו ממאכלים אלו."]]],[1301430133,"שב שכוונת האב במנוע ממנו מאכלים אלו הוא רק כדי לייסרו ולהענישו (ולא לטובתו), וכן בעניננו, שבנ\"י התלוננו שהקב\"ה אינו רוצה שיהנו ממאכלים אלו (אלא שבמשל טעמו של האב הוא לטובת הבן, כל בניו, ובנמשל — הוא מפני טוב­תם של המיעוט, המניקות, כדלקמן).\nה. ועפ\"ז מיושבים גם הדיוקים הנ\"ל ברש\"י:\nא) מקדים \"שום\" ל\"בצל\" (\"אל תאכלי שום ובצל\") — כי ב\"שום\" מודגש ומוכ­רח שהוא מאכל קשה רק למניקות בלבד ולא לכל ישראל — שהרי חכמים<sup data-n=\"634\">33</sup> מנו כמה מעלות טובות באכילת שום, ועד שעזרא תיקן ש\"אוכלין שום בערב שבת\"<sup data-n=\"635\">34</sup> (ובגלל זה נקראים כל ישראל \"אוכלי שום\"<sup data-n=\"636\">35</sup>), ועכצ\"ל ששום הוא מאכל קשה רק למניקות, ומזה למדים על השאר, שהם מאכלים קשים רק ל­מניקות ולא לכל ישראל.\nב) רש\"י משמיט \"עוברות\" — כי לפי פשוטו של מקרא מסתבר למעט ככל האפשר מספר בנ\"י שמאכלים אלו רעים עבורם, כי דוקא אז מובנת תלונתם של ישראל. וי\"ל שס\"ל לרש\"י, שע\"ד הפשט לא שייך לומר (בבירור) בנוגע למן ש­מינים אלו (כפי שהיו במן) הם קשים למעוברות, לפי שההיזק ממאכלים ל­מעוברות י\"ל שהוא (בעיקר) מריח ה­מאכלים, כדאיתא בגמ'<sup data-n=\"637\">36</sup> שבמעוברת נוגע ותופס מקום מה שמריחים, \"עוברה שהריחה\". ולכן לא שייך זה בנוגע להמן שרק טעמו הי' משתנה ולא ריחו<sup data-n=\"638\">37</sup>.\nובדרך זו יש ליישב עוד דיוק בהמ­שך לשון רש\"י בכתוב זה, שמפרש ג' מינים הראשונים \"הקשואים — הם קו­קומברו\"ש בלע\"ז. אבטחים — בורק\"ש. החציר — כרישין פוריל\"ש, ותרגומו ית בוציניא וכו'\".\nואינו מובן:\nא) מהו דיוק לשון רש\"י גבי \"קשו­אים\" — \"הם קוקומברו\"ש\", שלא כתב כן גבי אבטחים וחציר?\nב) מהי כוונת רש\"י בהביאו \"ותרגומו ית בוציניא וכו'\", שמביא רק התרגום על \"קישואים\" (\"ית בוציניא\"), והשאר רק מרמז ב\"וכו'\"? דממ\"נ, או שהו\"ל להעתיק התרגום גם על אבטחים וחציר [ובפרט ש\"חציר\" יכולים לפרש מלשון עשב<sup data-n=\"639\">38</sup>, כמ\"ש<sup data-n=\"640\">39</sup> מצמיח הרים חציר, וא\"כ ודאי שהו\"ל לרש\"י להוכיח שכאן פירושו \"כרישין\" מהתרגום שכתב \"כרתי\"<sup data-n=\"641\">40</sup>] — או אם סמך שהתלמיד יעיין בעצמו ב­תרגום (וכפי שמצינו בכמה מקומות ש­רש\"י רק מציין לתרגום), למה העתיק (התחלת) לשון התרגום \"ית בוציניא\"<sup data-n=\"642\">41</sup>?",[["634","33","ב\"ק פב, א."],["635","34","ב\"ק שם. וראה מג\"א או\"ח ר\"ס רפ. שו\"ע אדה\"ז שם."],["636","35","משנה נדרים לא, רע\"א (וברש\"י ותוס' שם). וראה שבת (קיח, ב) במה מענגו. . ראשי שומין."],["637","36","יומא פב, א."],["638","37","וזה שרש\"י בפי' על הש\"ס הוסיף גם \"עוברות\" — י\"ל (א) שתינוק שכבר לומד ש\"ס יודע יותר מהנעשה בנוגע לעוברות ואכילתן, (ב) (בדוחק עכ\"פ) שרש\"י מביאו דרך אגב, להסביר לתינוק שרואה בש\"ק שכל הב\"ב אוכלים בצל משא\"כ העוברות נזהרות מבצל (אף שאצל המן שלא נשתנה ריחו לא הי' שייך)."],["639","38","ראה ראב\"ע כאן."],["640","39","תהלים קמז, ח. ועד\"ז שם קד, יד. ועוד."],["641","40","וכ\"ה בתרגום ירושלמי. ובתיב\"ע \"קפלו­טיא\" (ראה משנה נדרים נג, א ובפיה\"מ להרמב\"ם ועוד שם)."],["642","41","לכאורה י\"ל שרש\"י מעתיק לשון הת\"א כיון שבתיב\"ע ות\"י תרגמו באו\"א (ראה ס' \"כללי רש\"י\" (קה\"ת, תש\"מ) ע' 74 (בהוצאת תנש\"א ע' 131). וש\"נ). אבל להעיר, שגם באבטחים וחציר תרגמו באו\"א. ומסתבר שעיקר הדגשת רש\"י היא בתרגום ד\"קישואים\", כבפנים."]]],[1301430134,"וע\"פ הנ\"ל יש לומר, כי עיקר חידושו של רש\"י הוא אכן בנוגע לקישואים. ד­הנה בפרש\"י לש\"ס<sup data-n=\"643\">42</sup> פי' \"בוצין\" — \"דל­עת\", ולא מצינו ש\"דלעת\" קשה למניקות. ולכן מפרש רש\"י, בדרך חידוש, ש\"קי­שואים\" כאן \"הם קוקומברו\"ש בלע\"ז\" (שהם קשים למניקות, כמפורש ברש\"י), וע\"ז מסיים ש\"תרגומו ית בוציניא\", שה­תרגום חולק ע\"ז<sup data-n=\"644\">43</sup>, שהרי מתרגם קישו­אים \"ית בוציניא\"<sup data-n=\"645\">44</sup>, שהם אינם קשים למניקות<sup data-n=\"646\">45</sup>, וא\"כ לפירוש התרגום, הצד השווה בחמשת מינים הללו אינו בזה שהם קשים למניקות (ועכצ\"ל שהתרגום מפרש תלונתם של ישראל באופן אחר).\nוזוהי גם כוונת רש\"י שהעתיק בפי­רוש רק \"ית בוציניא\" והשאר מרמז ב\"וכו'\" — כי בנוגע לפירוש המינים, מחולק רש\"י עם התרגום רק בנוגע ל­קישואים, אבל מזה גופא משתלשל נפק\"מ בפירוש כללות הכתוב (ה\"וכו'\"), מה הי' תוכן תלונת ישראל בנוגע ל­חמשת מינים הללו.\nו. אלא שלאחרי כל זה יש מקום לשאלה (עכ\"פ לתלמיד \"ממולח\") — למה באמת עשה ה' ככה, למנוע מכל ישראל טעמם של מינים אלו בגלל המניקות ש­הם מיעוטא דמיעוטא של כל ישראל<sup data-n=\"632\">31</sup>?\nולכן העתיק רש\"י שם בעל המאמר — ר' שמעון — דאזיל לשיטתו, שפעמים יתכן שהמיעוט מכריע את הרוב<sup data-n=\"648\">46</sup>.\nוכפי שמצינו בהדגשה אצל ר\"ש, ש­אמר<sup data-n=\"649\">47</sup> \"יכול אני לפטור את כל העולם כולו מן הדין מיום שנבראתי עד עתה, ואילמלי אלעזר בני עמי, מיום שנברא העולם ועד עכשיו, ואילמלי יותם בן עוזיהו עמנו מיום שנברא העולם ועד סופו\". דאע\"פ שהם יחידים ממש, מ\"מ ביכולתם להכריע את כל העולם כולו. והיינו משום שרשב\"י \"רואה\" את כל ישראל, ושל כל הדורות כולם, שהם מציאות אחת ממש, ולכן מעשה כל יחיד ופרט שבישראל נוגע להכלל כולו.\nועד\"ז ס\"ל לר\"ש להיפך, דכאשר יש­נו דבר שיכול להזיק את המיעוט, כדאי למנוע ענין זה גם מהרוב, כדי שלא יהי' שום חשש או חשש דחשש שיגיע רעה זו להמיעוט.\nובפשטות<sup data-n=\"650\">48</sup>: כדי שהמניקות לא ישימו לב שכל ישראל נהנים ממאכלים טובים אלו ויתאוו להם וכו', כדאי למנוע מאכלים אלו מרוב בני ישראל.\nומזה הוראה עד כמה צ\"ל ההשתדלות בטובת איש פרטי, ועוד זאת — אפילו כאשר מדובר בתינוק בישראל, וכ­בנדו\"ד, שהקב\"ה מנע מאכלים טובים",[["643","42","ברכות מח, רע\"א. סוכה נו, ב. — ותוס' (סוכה שם) פליגי על רש\"י (ע\"פ התרגום כאן)."],["644","43","ב\"כללים בדברי רש\"י\" הנדפס בכמה חומשים, שכשכותב רש\"י \"ותרגומו\", \"אז מביא רש\"י ראי' לפירושו שכן הוא\". אבל כבר נת' כמ\"פ שלכאורה אין כללים אלו מדוייקים, וצ\"ע מי חיברם. וראה לדוגמא בעניננו (\"ותרגומו\") — פרש\"י שלח יג, כח. ועוד."],["645","44","ולהעיר, שתרגום יונתן וירושלמי כאן \"ית קטיא\" הוא לכאורה כפרש\"י (ראה ערוך מע' קט (השני))."],["646","45","לשיטת רש\"י ש\"בוצינא\" היינו \"דלעת\"."],["632","31","ראה גם הרי\"ף לע\"י יומא שם. ספרי דבי רב לספרי כאן."],["648","46","ולהעיר, שלחד תירוץ ביבמות (סז, ריש ע\"ב) ס\"ל לר\"ש דחיישינן למיעוטא."],["649","47","סוכה מה, ב."],["650","48","ראה גם הרי\"ף לע\"י יומא שם."]]],[1301430135,"אלה מכל בנ\"י כדי שלא יהי' חשש של היזק ליונקי שדים — ועאכו\"כ שצ\"ל השתדלות עד כדי מסירת נפש בטובתם הרוחנית של קטנים וקטנות מישראל, לדאוג להם ובפרט שכאו\"א מהם יקבל חינוך על טהרת הקודש, באופן\"גם כי יזקין לא יסור ממנה\"<sup data-n=\"651\">49</sup>.\n<span data-k=\"q\">(משיחות ש\"פ בהעלותך וש\"פ שלח תשכ\"ח) </span>",[["651","49","משלי כב, ו."]]],[1301430136,"<h3>שיחה א</h3>\nא. בפירוש רש\"י בפרשתנו בנוגע ל­מרגלים, מצינו סתירות בנוגע למצבם בעת שילוחם: בתחלת הפרשה, עה\"פ<sup data-n=\"652\">1</sup> \"כולם אנשים\", מפרש רש\"י \"ואותה שעה כשרים היו\". אבל בהמשכה, עה\"פ<sup data-n=\"653\">2</sup> \"ו­יקרא משה להושע בן נון יהושע\" פירש \"התפלל עליו י\"ה יושיעך מעצת מרג­לים\", דמזה משמע, שכבר אז הרגיש משה רשעתם של המרגלים<sup data-n=\"654\">3</sup>, וכן מפורש בפרש\"י אח\"כ עה\"פ<sup data-n=\"655\">4</sup> \"וילכו ויבואו אל משה\" — \"מה ביאתן בעצה רעה אף הלי­כתן בעצה רעה\".\nוהנה ביישוב הסתירה מפרש\"י עה\"פ \"וילכו ויבואו\", כבר ביארו המפרשים<sup data-n=\"656\">5</sup>, שזהו דיוקו של רש\"י לפני זה \"ואותה שעה כשרים היו\", דרק בשעה שנבחרו ונתמנו \"כשרים היו\" — \"לאפוקי לאחר אותה שעה\"<sup data-n=\"657\">6</sup>, משהחזיקו בדרך<sup data-n=\"658\">7</sup> (\"ויל­כו\"), נהפכו ונעשו רשעים.\nאבל אין זה מיישב מ\"ש רש\"י שמשה התפלל על תלמידו יהושע \"י\"ה יושיעך מעצת מרגלים\", שהרי זה הי' ב\"אותה שעה\" שנבחרו, לפני התחלת הליכתם ב­דרך<sup data-n=\"659\">8</sup>?\nיש מפרשים<sup data-n=\"660\">9</sup> ש\"מיד אחר שהובררו\" כבר לא היו כשרים, וביארו<sup data-n=\"661\">10</sup> ד\"בתחלה כשהובררו כשרים היו וצוה להם משה שליחות על פי ה' לראות את הארץ כיצד היתה נוחה ליכבש ונצנץ בהם יצר הרע וחזרו למשה למסור להם סימנים בארץ אם<sup data-n=\"662\">11</sup> טובה ואם רעה ואת העם החזק הוא הרפה והכרכים אם מבצרים והרגיש משה שכוונתם לרעה דמה להם לחקור יותר ממה שנצטוו. . ולכך כתב. . ויקרא משה יהושע, כשהרגיש בהם יצרם הרע התפלל על יהושע\".\nאבל פירוש זה צ\"ע:\nא) קשה ביותר לומר שכוונת רש\"י",[["652","1","יג, ג."],["653","2","יג, טז."],["654","3","אבל ל' רש\"י בתחילת הפרשה (יג, ב) \"ורשעים הללו\" קאי בפשטות על סופם, כשחזרו ומרדו בה'."],["655","4","יג, כו."],["656","5","חזקוני, רא\"ם, גו\"א (יג, ב). רע\"ב (עה\"ת) לקמן פסוק כו. מפרשים שנסמנו בהערה 7. ועוד.\nבפענח רזא פי' ד\"משה טעה בהם והי' סבור כי כשרים היו\". אבל מפשטות ל' רש\"י משמע ש\"היו כשרים\" בפועל."],["657","6","ל' הרא\"ם."],["658","7","דבק טוב (בהגהה) ומשכיל לדוד ריש פרש­תנו. רע\"ב, חי' ופי' מהרי\"ק על פרש\"י, באר מים חיים (לאחי המהר\"ל) — לקמן פסוק כו. חדא\"ג מהרש\"א סוטה (לה, א)."],["659","8","בשפ\"ח כאן \"שכבר א\"ל השם ית' שלח לך לדעתך ושיתן להם מקום לטעות וא\"כ ודאי ידע רוע תבונתם ועצתם הרעה\" (וראה לקמן סעיף ב). וצע\"ג, דא\"כ איך יתפרשו דברי רש\"י \"אותה שעה כשרים היו\"."],["660","9","נמוקי מהרא\"י (לבעל תרומת הדשן) על פרש\"י כאן. הואיל משה (לבעל מטה משה) באר היטב על פרש\"י כאן. ולהעיר מלשון הגו\"א כאן \"משנשלחו. . ואחר המינוי מיד\". ועד\"ז בנחלת יעקב (לקמן פסוק כו) \"הליכתן מיד לאחר שנתבררו\". ובמושב זקנים עה\"ת שם \"משנצטוו ללכת\"."],["661","10","נמוקי מהרא\"י שם. ע\"ש ב\"תרי גווני\" שליחות. וראה גם הואיל משה (באר התורה) פרשתנו."],["662","11","פרשתנו יג, יח ואילך. שם, טז. — וצ\"ע, שהרי כ\"ז הוא מדברי משה, ואם כוונתם לרעה למה מסר להם משה כל הסימנים הללו."]]],[1301430137,"במ\"ש \"אותה שעה כשרים היו\" היא רק לזמן קצר ביותר<sup data-n=\"663\">12</sup>, משעת המינוי עד ש­\"חזרו למשה למסור להם סימנים ב­ארץ\"<sup data-n=\"664\">13</sup> [שבפשטות לא היתה שהיית זמן<sup data-n=\"665\">14</sup> בין התמנותם לדברי משה אליהם \"עלו<sup data-n=\"666\">15</sup> זה בנגב גו' וראיתם את הארץ וגו'\"].\nב) לפירושם הול\"ל (לרש\"י) \"בעת התמנותם כשרים היו\" וכיו\"ב.\nג) ועיקר: אם \"הרגיש משה שכוונתם לרעה\" — מדוע עמד בבחירתו לשלוח מרגלים האלה ולא שלח אחרים תחתיהם שלא תהי' כוונתם רעה (שבודאי הי' זה בידו של משה)<sup data-n=\"667\">16</sup>?\n[ומה שביארו במפרשים<sup data-n=\"668\">17</sup> (הטעם ש­משה התפלל על יהושע שינצל \"מעצת המרגלים\" אבל לא מנעו מלכת עמהם) כי סבר משה אולי יהושע וכלב יוכלו להחזירם ממחשבתם הרעה — אינו מ­יישב שאלה זו, דאיך יכנס בספק רעת כל בנ\"י — מפני שאולי יצליחו יהושע וכלב להחזירם לטוב! — ובפרט שיכול לא לשלחם כל עיקר].\nב. לכאורה יש לשאול כעין שאלה זו על כללות ענין שילוח המרגלים, של­פרש\"י, כבר בהתחלת הדבר ידע משה שאינו ענין רצוי ומ\"מ לא נמנע מל­שלחם.\nדהנה על הפסוק<sup data-n=\"669\">18</sup> \"שלח לך אנשים\" פרש\"י \"שלח לך — לדעתך, אני איני מצוה לך אם תרצה שלח, לפי שבאו ישראל ואמרו<sup data-n=\"670\">19</sup> נשלחה אנשים לפנינו. . אמר (הקב\"ה) אני אמרתי להם שהיא (ארץ ישראל) טובה. . חייהם שאני נותן להם מקום לטעות בדברי המרגלים למען לא יירשוה\". שמזה יוצא, דאף ש­משה שמע מפי הקב\"ה שאין צורך ב­שילוח המרגלים — מ\"מ, דעתו של משה (\"לדעתך\") הסכימה לכך.\nומפורש הדבר עוד יותר בפרש\"י לקמן בפ' דברים (עה\"פ<sup data-n=\"671\">20</sup> \"וייטב בעיני הדבר\"), שהטעם שהסכים משה לשילוח המרגלים הוא רק משום שחשב \"שמא תחזרו בכם כשתראו שאיני מעכב\" (כה­משל שמביא שם מ\"אדם האומר לחבירו מכור לי חמורך זה א\"ל הן נותנו אתה לי לנסיון א\"ל הן. . כיון שראה שאין מעכבו כלום אמר הלוקח בלבו בטוח הוא זה שלא אמצא בו מום מיד א\"ל טול מעותיך ואיני מנסהו\"), הרי להדיא, דאף",[["663","12","בפנים יפות כאן פי' \"אותה שעה, היינו משקיעת החמה (אור לכ\"ט סיון) עד צאת הכוכבים שהוא לערך שעה\". ע\"ש. אבל אינו לפי פשוטו כלל."],["664","13","ולכאורה י\"ל שכוונת רש\"י ב\"הליכתן בעצה רעה\" היא להליכתם בא\"י גופא (שרק אז, בראותם חוזק הערים כו', נהפכו לרעה) — וא\"צ לדחוק שנעשו רשעים מיד בתחילת הליכתם, קודם ראותם חוזק העם והערים."],["665","14","שהרי בפשטות בחירת ושילוח המרגלים נעשו במשך יום אחד — כ\"ט סיון (רש\"י דברים א, ב) — כי הנסיעה מחצרות למדבר פארן היתה בכ\"ח סיון (ראה בארוכה לקו\"ש חי\"ט ע' 1 הערה 6. וש\"נ)."],["666","15","יג, יז ואילך."],["667","16","ולומר שלא היו בכל בנ\"י \"כשרים\" מהם — ה\"ז א) דוחק הכי גדול ב) הי' עליו לבטל כל ענין השליחות, שהרי הי' רק מדעתו.\nבפענח רזא שם (ועד\"ז במושב זקנים בתי' הב') כ' \"שהעם החזיקו עליו לשלוח כדכתיב במשנה תורה (דברים א, כב) ותקרבון אלי כולכם וגו'\" (וראה לקמן ס\"ב). אבל דוחק גדול לומר שמשה יסכים וישלח אנשים שכוונתם לרעה מפני שחזקו עליו!"],["668","17","דבק טוב (בהגהה) והואיל משה (באר היטב) שם."],["669","18","יג, ב."],["670","19","דברים א, כב."],["671","20","א, כג."]]],[1301430138,"שמשה הרגיש שלא היתה כוונת בנ\"י ל­טובה (וכפי שניתן להבין גם מעצם אופן בקשת בנ\"י, כפרש\"י שם<sup data-n=\"670\">19</sup> שקרבו כולם \"בערבוביא, ילדים דוחפין את הזקנים כו'\") — מ\"מ הסכים לבקשתם של ישראל (היפך רצונו — דמשה).\nומכיון שעכ\"פ אנו רואים שעוד לפנ\"ז לא נמנע מלשלחם (מאיזה טעם שיהי') אף שלא היתה כוונתם לטובה — א\"כ שוב אין לשאול גם בנדו\"ד למה לא עיכב שילוח המרגלים לאחרי ש\"הרגיש משה שכוונתם לרעה\".\nאבל אאפ\"ל כן — כי חילוק גדול ב­דבר:\nבפירוש רש\"י הנ\"ל המדובר בבקשת בנ\"י \"נשלחה אנשים לפנינו\", כי הם לא האמינו בטוב הארץ, ולכן לא הוטב ב­עיני השם כי \"אני אמרתי להם שהיא טובה\"; ובזה מובן הטעם שמשה הסכים לדבריהם, כי חשב שבראותם שאינו מ­פחד מלשלוח אנשים לראות את הארץ ה\"ז גופא יוכיח לבנ\"י שטובה הארץ, וב­מילא יחזרו בהם מרצונם זה.\nוגם זה שהסכים משה לשלוח את ה­מרגלים אף לאחרי שראה שלא חזרו בהם בנ\"י — אפשר להסביר, כי לכן בחר באנשים כשרים, \"ראשי בני ישר­אל\"<sup data-n=\"673\">21</sup> (וכלשון רש\"י בפ' דברים<sup data-n=\"674\">22</sup> \"מן הברורים שבכם, מן המסולתים שבכם\"), שסמך עליהם שיראו את טוב הארץ וגם יביאו אתם מפרי הארץ<sup data-n=\"675\">23</sup>, ועי\"ז יתברר לבנ\"י בראי' מוחשית<sup data-n=\"676\">24</sup> שאכן טובה ה­ארץ מאד מאד, ואדרבא יתחזק אצלם הרצון לעלות לארץ.\nאבל את\"ל שמשה הרגיש באנשים ש­בחר בהם עצמם ש\"כוונתם לרעה\", הרי אין כל מקום לשלחם — ומדוע לא השתדל לעכבם<sup data-n=\"677\">25</sup>.\nולכן נ\"ל ששני הדברים, \"אותה שעה כשרים היו\", ותפלת משה \"י\"ה יושיעך מעצת מרגלים\" — מעיקרא אינם סותרים זל\"ז, כדלקמן.\nג. ויובן זה בהקדים דיוק לשון רש\"י<sup data-n=\"678\">26</sup> \"י\"ה יושיעך מעצת מרגלים\", ועד\"ז לקמן<sup data-n=\"679\">27</sup> גבי כלב מדייק רש\"י ש­\"נשתטח על קברי אבות שלא יהא ניסת לחבריו להיות בעצתם\". דלכאורה הי' מתאים יותר להשתמש בלשון המתארת את חטאם — כמו \"דבה\", כמש\"נ<sup data-n=\"680\">28</sup> \"ויוצי­או דבת הארץ גו'\" [וכלשון רש\"י עצמו בתחלת הפרשה, \"למה נסמכה פרשת מרגלים לפרשת מרים לפי שלקתה על עסקי דבה כו'\", וכן בהמשך הענין<sup data-n=\"681\">29</sup> \"ל­הוציא דבה נתכוונו\"], או \"חטא המרג­לים\"; ומדוע נקט רש\"י לשון \"עצה\" דוקא<sup data-n=\"682\">30</sup>?\nויש לומר, שבדוקא נקט רש\"י לשון זו, להדגיש, שאין כוונתו לומר שה' יושיעו מחטא המרגלים, כי עדיין ב­\"אותה שעה כשרים היו\" (ולא היו שיי­כים לחטא של \"דבה\"<sup data-n=\"683\">31</sup> וכו'), אלא רק",[["670","19","דברים א, כב."],["673","21","פרשתנו יג, ג ובפרש\"י."],["674","22","א, כג ד\"ה ואקח."],["675","23","פרשתנו יג, כ."],["676","24","דאינה דומה שמיעה לראי' (ראה רש\"י יתרו כ, יט). וראה רמב\"ן ריש פרשתנו."],["677","25","ראה הערה 16."],["678","26","והוא מסוטה לד, ב."],["679","27","יג, כב (מסוטה שם). ולהעיר מרש\"י יד, כד \"אני עמכם בעצה\"."],["680","28","יג, לב. וכן לקמן יד, לו­לז."],["681","29","יג, כג."],["682","30","כן דייק גם בס' ערבי נחל (לבעהמ\"ס לבושי שרד) ריש פרשתנו."],["683","31","להעיר שגם \"דבה\" היא רק \"לשון חינוך דברים. . וישנה לטובה\" (רש\"י פרשתנו יד, לו). וראה בארוכה לקו\"ש חי\"ח (ע' 145 ואילך), שעיקר חטא המרגלים הי' שעסקו ב\"דבת הארץ\" (גם כשלא היתה דבה רעה). ע\"ש."]]],[1301430139,"מ\"עצת מרגלים\", \"עצה\" סתם — לאו דוקא עצה רעה (שזה נתחדש רק אח\"כ בעת הליכתם, \"הליכתן בעצה רעה\", כנ\"ל ס\"א מהמפרשים), ואדרבה, כיון ש­ב\"אותה שעה כשרים היו\", ודאי שזו היתה אצלם \"עצה טובה\" — ומ\"מ התפלל משה על יהושע \"י\"ה יושיעך מעצת מרגלים\", כי אף שכוונתם לטובה, מ\"מ, עלולה \"עצתם\" להביא לידי טעות וכו' (כפי שאכן קרה בפועל), ולכן התפלל שינצל מזה.\nד. ביאור הענין:\nבכל הפרשה כולה מתוארת שליחות המרגלים בלשון \"תור\" — \"ויתורו את ארץ כנען\"<sup data-n=\"684\">32</sup>, \"תור הארץ\"<sup data-n=\"685\">33</sup>, \"תרים\"<sup data-n=\"686\">34</sup> ו­כיו\"ב, ולא נזכרה אף פעם אחת בפרש­תנו לשון \"מרגלים\" בקשר לשליחות זו<sup data-n=\"687\">35</sup> [ואין זה משום שיש חסרון ותוכן בלתי רצוי בשילוח מרגלים — שהרי מצינו (לקמן בפ' חוקת<sup data-n=\"688\">36</sup>) שגם אח\"ז — משה עצמו שלח \"לרגל את יעזר\", וכן יהושע שלח מרגלים<sup data-n=\"689\">37</sup>].\nובטעם הדבר יש לומר:\nהחילוק בין שתי הלשונות — \"לתור\" או \"לרגל\"<sup data-n=\"690\">38</sup> — הוא<sup data-n=\"691\">39</sup>: \"לתור\" מתאר (בעיקר) רק פעולת החיפוש והראי'<sup data-n=\"692\">40</sup> בלבד, ובעניננו — ראיית הארץ ויושבי'; משא\"כ לשון \"ריגול\" מורה על חקירה וחיפוש לשם כוונה נסתרה, כמו בריגול המסייע לכיבוש ארץ האויב [ע\"ד ש­מצינו לעיל (בפ' מקץ<sup data-n=\"693\">41</sup>) בנוגע ליוסף ואחיו — \"ויאמר אליהם (יוסף לאחיו) מרגלים אתם לראות את ערות הארץ באתם\", ופרש\"י \"גלוי הארץ, מהיכן היא נוחה ליכבש\"]; ובדרך כלל ענין הריגול קשור עם חכמת המרגל, שעל יסוד חקי­רותיו וחיפושיו אפשר לטכס עצה איך למלא משימה מסויימת (כיבוש ארץ האויב, וכיו\"ב).\nוזהו הטעם שבפרשתנו נאמרה רק לשון \"לתור את ארץ כנען\", וכיו\"ב — כי כל ענין השליחות (בכוונת משה) הי' רק על המעשה, שיראו את הארץ ויושבי' ויספרו לבנ\"י מה שראו (וכן להביא מפרי הארץ כדי להראות את ישראל מ­טוב הארץ), ותו לא מידי — אבל לא \"לרגל את הארץ\", להכניס עצמם בחי­פוש \"עצות\" ותחבולות בשביל כיבוש הארץ וכיו\"ב<sup data-n=\"694\">42</sup>.\nובזה יובן תוכנה של תפלת משה \"י\"ה יושיעך מעצת מרגלים\":\nאף שמשה הדגיש לאנשים שבחר",[["684","32","יג, ב. וכן שם, טז­יז. כא. לב. יד, ז. שם, לד. לו. לח."],["685","33","יג, כה."],["686","34","יד, ו."],["687","35","ורק בפ' דברים (א, כד) נאמר \"וירגלו אותה\". וראה הערה 45."],["688","36","כא, לב."],["689","37","כמסופר בתחילת ספרו (הפטרת פרשתנו)."],["690","38","אף שלפעמים משמשים שניהם לכוונה אחת (ראה רש\"י סוף פרשתנו (טו, לט). חוקת כא, א (בפי' הא'). רש\"י לנ\"ך — שופטים א, כג) — מ\"מ בפרטיות יש חילוק ביניהם, כבפנים."],["691","39","בהבא לקמן ראה גם מלבי\"ם כאן (באו\"א קצת). ולהעיר מכלי יקר כאן (יג, ב), של\"ה שבהערה 47 ועוד — ביאור ג' הלשונות \"ויתורו\", \"ויחפרו\", \"וירגלו\" — ע\"ד הדרוש."],["692","40","ראה ראב\"ע ריש פרשתנו (יג, ב). ס' השרשים להרד\"ק ערך תור. וראה פרש\"י חוקת שם (בפי' הב') \"התייר הגדול\" (ולהעיר מפרש\"י בהעלותך י, לג \"לתקן להם מקום חניי'\", ובת\"א שם)."],["693","41","מב, ט."],["694","42","ורק בנ\"י רצו בכך, ולכן בקשו \"ויחפרו לנו את הארץ גו' את הדרך אשר נעלה בה ואת הערים אשר נבא אליהן (תחילה לכבוש)\" — דברים א, כב (ובפרש\"י). וראה בארוכה מלבי\"ם כאן."]]],[1301430140,"שמטרת השליחות היא רק \"לתור את ארץ כנען\"<sup data-n=\"695\">43</sup>, הרי תיכף ומיד בהתאספם אצלו הרגיש שהנם רואים את עצמם (לא כ\"תרים\" בלבד, אלא) כ\"מרגלים\", והיינו, שמלבד המעשה בפועל (לילך ולראות את הארץ), עליהם לטכס עצות ולהסיק מסקנות (על יסוד הריגול) הנוגעות לכי­בוש הארץ וכו'.\nוע\"ז התפלל משה \"י\"ה יושיעך מעצת מרגלים\": אף שעדיין לא הי' בעצתם שום חטא, כי ב\"אותה שעה כשרים היו\", וכל כוונתם היתה רק לטכס עצות טובות איך לסייע בריגולם לכיבוש הארץ ו­כו'<sup data-n=\"696\">44</sup> — מ\"מ, התפלל משה שלא יהי' ל­יהושע חלק ב\"עצת מרגלים\", אלא ישאר נאמן למטרת השליחות שהיתה אך ורק \"לתור את ארץ כנען\"<sup data-n=\"697\">45</sup>, מבלי לערב בזה ענין של \"נתינת עצות\" וכו'<sup data-n=\"698\">46</sup>, כי הנהגה של \"עצת (מרגלים)\" עלולה להביא לידי נפילה (כדלקמן סעיף ה).\n[ועפ\"ז יש לומר, שזו היתה גם כוונת כלב בתפלתו \"שלא יהא ניסת לחבריו להיות בעצתם\" — ולא כ' \"בעצתם ה­רעה\" (וכיו\"ב) — די\"ל שבעת ההיא עדיין לא נודע לכלב ש\"הליכתן בעצה רעה\", אבל התפלל שלא יהא ניסת לחבריו גם ב\"עצה טובה\" שלהם, כי הי' נאמן ל­שליחותו של משה, מבלי לנטות משהו מהמטרה, רק \"לתור את הארץ\", ולא להיות חבר ל\"עצת (מרגלים)\"].\nאבל לאידך מובן, שלא הי' בזה טעם מספיק לבטל שליחותם, כי זה שראו עצמם ב\"אותה שעה\" (כשעדיין \"כשרים היו\") כ\"מרגלים\" אינו מכריח להביא לתוצאות בלתי רצויות, ואינו אלא חשש כו'.\nה. עפ\"ז יבואר עוד ענין תמוה ב­פרשת מרגלים, שלכאורה לא מצינו ש­רש\"י יפרשו:\nכיצד יתכן, שאנשים מובחרים אלה, שמשה רבינו בעצמו בחר בם לשליחות זו (שמזה גופא מובן שהם היו המתאימים ביותר מכל בנ\"י למלא שליחות זו) ייהפ­כו, מן הקצה אל הקצה<sup data-n=\"699\">47</sup>, להיות חוטאים ומחטיאים, עד שמרדו בה' ואמרו \"לא נוכל לעלות. . כי חזק הוא ממנו\"<sup data-n=\"700\">48</sup> (וכפרש\"י \"כביכול כלפי מעלה אמרו\")?\nוע\"פ הנ\"ל י\"ל שבדיוק לשון רש\"י \"עצת מרגלים\" מרומז השורש והסיבה שהביאום לירידה אחר ירידה, ועד ל­מרידה בה':\nהלשון \"עצה\" מורה על הצורך בחי­פוש ומציאת תחבולה, דבר מסויים מתוך כוונה נסתרה ונעלמה (שלא תוודע להמנגד בזה וכיו\"ב). והוא הדבר בהענין ד\"עצת מרגלים\": ענין הריגול דורש \"עצה\" ותחבולה, מרגלים צריכים לטכס עצות ותחבולות איך להערים ולהסתיר",[["695","43","יג, יז."],["696","44","שזהו ענין טוב. וכנ\"ל שגם משה שלח \"לרגל את יעזר\". וכן יהושע שלח מרגלים. וראה בארוכה רמב\"ן ריש פרשתנו."],["697","45","עפ\"ז מובנת הדגשת (יתור) לשון הכתוב לקמן (יד, ו) \"ויהושע. . וכלב. . מן התרים את ה­ארץ קרעו בגדיהם\", שהם רק תרו את הארץ (משא\"כ השאר, שהם גם ריגלו אותה, כמ\"ש בדברים שם (א, כד))."],["698","46","להעיר מעקידה פרשתנו (הובא בשל\"ה פרשתנו — שנד, ב) ש\"הגדילו רשע. . שהוציאו עצמם מכלל מרגלים ונכנסו בכלל יועצים\". ע\"ש באורך. ועד\"ז במנחה בלולה פרשתנו (יג, כח)."],["699","47","וראה ביאור השתלשלות ירידת המרגלים ע\"ד הדרוש — של\"ה פרשתנו. ועוד. וע\"ד החסידות — ראה לקו\"ת פרשתנו ד\"ה שלח וד\"ה ויאמרו. ועוד."],["700","48","יג, לא."]]],[1301430141,"את מטרת בואם, שבאופן זה יצליחו ל­בצע את מטרתם מבלי שיוודע לזה ש­יכול למנעה [ע\"ד שמצינו לעיל בנוגע ליוסף ואחיו — \"ויאמר<sup data-n=\"701\">49</sup> אליהם (יוסף לאחיו) מרגלים אתם לראות את ערות הארץ באתם ויאמרו אליו לא אדוני ו­עבדיך באו לשבר אוכל\", היינו, שלדב­רי יוסף העלימו את המטרה האמיתית שבגללה באו למצרים (\"לראות את ערות הארץ\") באמרם שבאו \"לשבר אוכל\"].\nונמצא, שענין הריגול כשלעצמו דו­רש הנהגה של ערמה והסתרת האמת, ו­רק עי\"ז יכולים להצליח בביצוע ה­ריגול.\nוזהו הטעם לזה שמשה רצה ששליחו­תם תהי' מוגבלת רק לחלק המעשה, \"לתור את ארץ כנען\", מבלי שייעשו \"מרגלים\", יכנסו בעצות ותחבולות של ערמה והסתרת האמת, ועד שעלולה ל­הרחיקם ממדת האמת וכו'. ואפילו כש­כוונתו לכתחילה היא לשם מטרה טובה, לחשוב מחשבות ותחבולות של \"עצה טובה\" [ולפעמים מוכרחים לשלוח מרג­לים, כי בלאה\"כ אא\"פ (ע\"פ טבע) לנצח האויב, שלכן, כנ\"ל, שלח משה לרגל את יעזר] — מ\"מ, סו\"ס הרי מדת הערמומיות (והסתרת האמת) יכולה להוריד את ה­אדם מדחי אל דחי, ודרושה זהירות יתי­רה שלא יכשל כו'<sup data-n=\"702\">50</sup>.\nולכן, לאחרי שהרגיש משה שהאנשים ההם מחזיקים את עצמם ל\"מרגלים\" — התפלל (תיכף) על יהושע (תלמידו<sup data-n=\"703\">51</sup>), \"י\"ה יושיעך מעצת מרגלים\" — שלא יהי' לו חלק בעצתם (גם אם היא \"עצה טובה\"), כדי שלא תהי' לו שום שייכות ל\"עצת מרגלים\"<sup data-n=\"704\">52</sup>.\nו. ויש להמתיק הענין ע\"פ המבואר בחז\"ל, שמדתו של משה היא מדת האמת — \"ואמת זה משה\"<sup data-n=\"705\">53</sup> (שלכן ניתנה תורה על ידו, כי זהו ענינה של תורה — \"תורת אמת\"<sup data-n=\"706\">54</sup>). ולכן, כדי להיות שלוחו של משה — שלוחו של אדם כמותו, \"כמותו דהמשלח ממש\"<sup data-n=\"707\">55</sup> — א\"א שתהי' אצל ה­שליח שום נטי' ממדת האמת.\nוזהו ששליחותו של משה היתה רק \"לתור את הארץ\" ולא \"לרגל אותה\" — כי בענין עיקרי זה, שליחות בשייכות לכניסה לארץ, הי' צ\"ל כח המשלח (כחו של משה) באופן גלוי<sup data-n=\"708\">56</sup>,\nועי\"ז שהשלוחים נטו מקו שליחותם והחזיקו את עצמם למרגלים, נתבטל בהם כח המשלח — כי נוסף על ביטול השליחות מצד השינוי, דעי\"ז ששליח משנה את שליחותו (בענין עיקרי) בטלה",[["701","49","מקץ מב, ט­י."],["702","50","ע\"ד מ\"ש בשו\"ע אדה\"ז (או\"ח מהד\"ק ס\"א ס\"ג, מב\"י לטאו\"ח שם) לענין מדת העזות — ד\"הוי עז כנמר\" — שצ\"ל זהירות \"שלא יקנה קנין בנפשו להיות עז פנים אפילו שלא במקום עבודתו ית'\". וראה הגש\"פ עם לקוטי טעמים ומנהגים (קה\"ת) ע' יא."],["703","51","ראה מושב זקנים, גו\"א ועוד על פרש\"י כאן."],["704","52","כי בנדו\"ד לא הי' צורך ב\"מרגלים\", וגם הענין ד\"לתור את הארץ\" הי' רק מפני שבנ\"י לא האמינו שאכן טובה הארץ (כנ\"ל סעיף ב)."],["705","53","תהלים פה, יא. שמו\"ר פ\"ה, י. וראה סנהדרין קיא, סע\"א."],["706","54","כמחז\"ל \"משה (אמת) ותורתו אמת\" (ב\"ב עד, א. סנה' קי, סע\"א ואילך. תנחומא קרח יא). וראה לקו\"ש חכ\"ו ע' 4 ואילך."],["707","55","ל' אדה\"ז בלקו\"ת ויקרא (א, ג). וראה בארוכה לקמן ע' 114 ואילך."],["708","56","משא\"כ בהשליחות \"לרגל את יעזר\", שלא היו צריכים לכחו של משה (באופן גלוי) כו'. וראה הערה 59."]]],[1301430142,"השליחות<sup data-n=\"709\">57</sup> — הרי כאן, נפסלו בעצם מלהיות שלוחי משה, כי א\"א שהם יהיו \"כמותו\" דמשה<sup data-n=\"710\">58</sup>, שמדתו מדת האמת<sup data-n=\"711\">59</sup>.\nורק יהושע וכלב שלא נתפתו ל\"עצת מרגלים\" נשארו שלוחי משה<sup data-n=\"712\">*59</sup>, וזה גופא שמרם שלא נטו מהכוונה ומטרת שליחותם, ואמרו \"טובה הארץ מאד מאד. . אל תיראו את עם הארץ כי לחמנו הם. . אל תיראום\"<sup data-n=\"713\">60</sup>, ומשום כך זכו ליכנס לארץ, ועד ש\"חיו מן האנשים ההם\" — ש\"נטלו חלקם של מרגלים בארץ וקמו תחתיהם לחיים\"<sup data-n=\"714\">61</sup>.\n<span data-k=\"q\">(משיחת ש\"פ שלח תשמ\"ה)</span>",[["709","57","רמב\"ם הל' שלוחין ושותפין פ\"א ה\"ב ואילך. שו\"ע חו\"מ סקפ\"ב ס\"ב ואילך."],["710","58","ולהעיר מגו\"א כאן (יג, ג) דזה שנעשו רשעים הי' להיותם \"שלוחיהם של רשעים. . ונעשו כמו המשלחים\". ועד\"ז באוה\"ח ריש פרשתנו."],["711","59","וי\"ל שזהו הפירוש (הפנימי) בפרש\"י חוקת (כא, לב) \"וישלח משה לרגל את יעזר — המרגלים לכדוה, אמרו לא נעשה כראשונים בטוחים אנו בכח תפלתו של משה להלחם\", דכיון שהיו בטוחים \"בכח תפלתו של משה\", שכחו של משה הי' אצלם בגלוי, לא הסתירו א\"ע כמרגלים אלא לחמו בגלוי.\nוי\"ל ע\"ד הרמז, שלכן לא העתיק רש\"י בהד\"ה תיבת \"וילכדו\" (שלכאורה זוהי הראי' שהם לכדוה) — כי עצם הענין שהיו שלוחי משה הביא לכך שלא הסתירו עצמם אלא לחמו ולכדוה."],["712","*59","להעיר מרש\"י יד, כד \"ובלבו הי' לומר האמת\"."],["713","60","פרשתנו יד, ז­ט."],["714","61","שם, לח ובפרש\"י."]]],[1301430143,"<h3>שיחה ב</h3>\nא. מזה שהמרגלים נקראו (בפרשת­נו<sup data-n=\"715\">1</sup>) בשם \"עדה\" והיו עשרה (כי יהושע וכלב לא היו בכללם), למדו חז\"ל<sup data-n=\"716\">2</sup> שכל עשרה מישראל בהצטרפם נחשבים \"עדה\"<sup data-n=\"717\">3</sup> שלמה.\nוצ\"ע<sup data-n=\"718\">4</sup> שמקור להלכה זו, במעלתה ה­מיוחדת של \"עדה\" בעניני קדושה (ש\"כל דבר שבקדושה לא יהא פחות מעשרה\"<sup data-n=\"719\">5</sup>) נלמד דוקא מהמרגלים (דכתיב בהו<sup data-n=\"715\">1</sup> \"עד מתי לעדה הרעה הזאת\")<sup data-n=\"721\">6</sup>?\nואף דדין של עדה<sup data-n=\"722\">7</sup> קדושה (ש\"אין דבר שבקדושה פחות מעשרה\") הוא שגם רשע \"מצטרף למנין עשרה לכל דבר ש­בקדושה. . (כי) ישראל אע\"פ שחטא ישראל הוא<sup data-n=\"723\">8</sup> ובקדושתו הוא עומד ולא יצא מכלל ישראל\"<sup data-n=\"724\">9</sup>, אבל לכאורה אין זה טעם מספיק, כי [נוסף ע\"ז שאת\"ל (כפי שמשמע מפשש\"מ) שהמרגלים היו בגדר מורדים בה' (כדברי כלב<sup data-n=\"725\">10</sup> \"בה' אל תמרודו\"), הרי אין זה פשוט ל­הלכה<sup data-n=\"726\">11</sup> אם אפשר לצרף \"מורדים\" ל­מנין עשרה לדבר שבקדושה, ומה גם כשכל העשרה הם \"מורדים\" — הנה] הלימוד ממרגלים ד\"עדה\" הוי עשרה — נוגע גם לדין \"עדה\" דסנהדרין<sup data-n=\"727\">12</sup> (\"ו­שפטו. . והצילו העדה גו'\"<sup data-n=\"728\">13</sup>) שהיא עשרה, שבזה פשיטא דאין רשע בכלל<sup data-n=\"729\">14</sup>.\nוי\"ל שזהו אחד מהרמזים בנגלה ד­תורה להמבואר בפנימיות התורה, שה­מרגלים היו בדרגא נעלית<sup data-n=\"730\">15</sup>. כלומר, לא",[["715","1","יד, כז."],["716","2","מגילה כג, ב (הובא בפרש\"י עה\"פ). וכן הוא לכמה גירסאות בברכות כא, ב וסנהדרין עד, ב (ראה על הגליון בש\"ס שם. וראה פרש\"י סנהדרין שם. מהרש\"א שם)."],["717","3","ראה רמב\"ם הל' תפלה פ\"ח ה\"ה. שו\"ע אדה\"ז או\"ח סנ\"ה ס\"ב."],["718","4","ראה ספר השיחות תש\"ד ע' 29."],["719","5","ברכות ומגילה שם — דאתיא תוך (אמור כב, לב) תוך (קרח טז, כא).\nבס' השיחות שם הובא \"הבדלו מתוך העדה הרעה הזאת\" — כנראה ט\"ס, ותיבת הרעה מיותרת. או שהכוונה שם להעתיק ב' הפסוקים (גם הפסוק דפרשתנו, וכבגמ' שם), וכסיום הלשון בס' השיחות שם שעדה פי' עשרה."],["715","1","יד, כז."],["721","6","ולהעיר דבירושלמי סנהדרין פ\"א ה\"ד (ועד\"ז בירושלמי ברכות פ\"ז ה\"ג) ישנה דיעה דה­לימוד הוא מהכתוב (מקץ מב, ה) ויבואו בני ישראל לשבר בתוך הבאים."],["722","7","להעיר משו\"ע אדה\"ז שם: ועדה זו צריך להיות כולה מזכרים בני חורין גדולים. . וכמו שהיתה עדה האמורה להלן אבל נשים ועבדים וקטנים אינן מצטרפין."],["723","8","סנהדרין מד, רע\"א."],["724","9","שו\"ע אדה\"ז שם סי\"ד (מב\"י שם (ד\"ה כתב בס') בשם ס' המנהיג סי' עט). וראה תניא ספ\"א. אגה\"ק סכ\"ג (קלו, ב). סה\"מ תקס\"ה ח\"ב ע' תתקסד. ועוד."],["725","10","יד, ט. וזה אמר לכל עדת בני ישראל (שם, ז), ופשיטא למרגלים שע\"פ פשש\"מ (וראה רש\"י שם יד, כז) היו לא רק חוטאים בעצמם אלא גם מחטיאי הרבים."],["726","11","ראה ב\"י שם מהרשב\"א. פמ\"ג (א\"א) שם סק\"י. ועוד."],["727","12","משנה סנהדרין פ\"א (ב, סע\"א)."],["728","13","מסעי לה, כד­כה."],["729","14","אף שיש לחלק דבזה שאני שאינו בכלל — לא מפני שאינו ב\"עדה\" אלא מפני שאינו ב­\"סנהדרין\"."],["730","15","להעיר ממחז\"ל שטן ופנינה לש\"ש נתכוונו (ב\"ב טז, א)."]]],[1301430144,"זו בלבד שלא היתה כוונתם ח\"ו מרידה כפשוטה, אלא אדרבה, \"היו במדריגה גבוה מאד\"<sup data-n=\"731\">16</sup>, וכדלקמן בארוכה.\n[וכמשנ\"ת בכ\"מ שנגלה דתורה ופני­מיות התורה הם תורה אחת, ולכן, אף שכל חלק יש לו גדרים וכללים משלו וע\"ד שאין למדים הלכה מאגדה<sup data-n=\"732\">17</sup> — מ\"מ, מכיון שבעצם ה\"ה תורה אחת, מובן שיש ביניהם שייכות, קשר ועד — לאי­חוד (ועד, שהם גוף ונשמה זל\"ז כדאיתא בזהר<sup data-n=\"733\">18</sup>), וגם הענינים שבפנימיות התורה שלפום ריהטא אינם מתאימים עם הפשט וההלכה יש להם יסוד ומקור בנגלה דתורה<sup data-n=\"734\">19</sup>, אם ברמז או בפירוש.\nוכן בעניננו, דעם היות שע\"פ פשש\"מ (ונגלה דתורה בכלל) חטאו המרגלים ב­חטא חמור ובגללו נענשו הם עצמם ועל ידם כל דור המדבר כו' — מ\"מ צריך לומר שגם בנגלה דתורה יש רמז עכ\"פ על מעלת המרגלים המבוארת בפנימיות התורה].\nב. בתורת החסידות (פנימיות התורה) מבואר<sup data-n=\"735\">20</sup>, דזה שלא רצו המרגלים ליכנס לא\"י הי' מצד גודל מעלתם<sup data-n=\"736\">21</sup> בעבודת ה': לא רצו להכנס לא\"י משום שמאנו ל­השפיל את עצמם בסדר החיים של \"שש שנים תזרע שדך גו'\"<sup data-n=\"737\">22</sup>, להתעסק ב­ענינים גשמיים וחומריים, וע\"ד מאמר רשב\"י<sup data-n=\"738\">23</sup> \"אפשר אדם חורש כו' וזורע כו' תורה מה תהא עלי'\". כל רצונם ו­חפצם הי' (כהמשך למ\"ת) להשאר בהת­בודדות במדבר, מנותקים מחיי ישוב, בלא טרדות הפרנסה וכו' (כי השם סיפק צרכיהם במדבר ע\"י המן, לחם מן ה­שמים<sup data-n=\"739\">24</sup>, והמים מבארה של מרים<sup data-n=\"740\">25</sup>, וע\"י ענני הכבוד שליוו אותם והרגו את ה­נחשים והעקרבים וגיהצו בגדיהם<sup data-n=\"741\">26</sup> ו­כו'), והרי זוהי הדרך האמיתית ללמוד תורה ולהיות דבוק בה', וכמאמר רז\"ל<sup data-n=\"742\">27</sup> לא ניתנה תורה (לדרוש) אלא לאוכלי המן.\n[אלא שטעו בזה, כי יש מעלה גדולה יותר בעבודה שבסדר החיים בא\"י, קיום המצות התלויות בארץ, ומצות מעשיות בכלל, אפילו לגבי מעלת הדביקות וכו' שבמדבר].\nועפ\"ז י\"ל, שבענין הנ\"ל — שדוקא מ­ה\"עדה\" דמרגלים ילפינן שעשרה מישר­אל נחשבים \"עדה\" קדושה — מרומז ש­חטאם של המרגלים לא הי' במובנו ה­פשוט, אלא שטעו בחשבם שהדרך (הנ\"ל) שבחרו בה היא הדרך העיקרית בעבודת ה'<sup data-n=\"743\">28</sup>,",[["731","16","לקו\"ת פרשתנו לו, סע\"ד."],["732","17","ירושלמי פאה פ\"ב ה\"ד (וראה אנציקלו­פדיא תלמודית ערך אגדה. וש\"נ). ויתרה מזה בהלכה עצמה — ממונא מאיסורא לא ילפינן (ברכות יט, ב וש\"נ) וכיו\"ב."],["733","18","ח\"ג קנב, א."],["734","19","וראה דרמ\"צ ה, א (ועד\"ז כב, א): וגם הגליא הוא כפי הסתים כגוף לנפש."],["735","20","לקו\"ת פרשתנו (לז, ב. לח, ב) מספרי קבלה. אוה\"ת שם (ס\"ע תמג ואילך. ס\"ע תנה ואילך). ובכ\"מ."],["736","21","ראה לקו\"ת ריש פרשתנו."],["737","22","בהר כה, ג."],["738","23","ברכות לה, ב."],["739","24","בשלח טז, ד ואילך."],["740","25","פרש\"י חוקת כ, ב."],["741","26","פרש\"י בהעלותך יוד, לד. עקב ח, ד."],["742","27","מכילתא בשלח טז, ד."],["743","28","ולהעיר דאף שבמשנה (סנהדרין קח, א) אי' שמרגלים אין להם חלק לעוה\"ב, משמע בזהר ח\"ג (רע\"מ) רעו, א שיש להם חלק לעוה\"ב. וידוע הפי' בס' עשרה מאמרות (מאמר חקו\"ד ח\"ב פ\"ח) ובכ\"מ — בדעת רע\"ק (סנהדרין שם) \"דור המדבר אין להם חלק לעוה\"ב\", כי אין להם צורך בעוה\"ב, ואדרבא הם למעלה מזה (וראה לקוטי לוי\"צ אגרות ע' שנח ואילך). וראה לקו\"ש חכ\"ג ע' 102. וש\"נ.\nולהעיר מתפלת (ופירוש) אדה\"ז עה\"פ: מי לי בשמים — זע איך וויל נישט כו' (שורש מצות התפלה — בסהמ\"צ להצ\"צ פ\"מ)."]]],[1301430145,"אלא שמצד גודל מעלתם ודרגתם ב­עבודת ה'\nועוד (וי\"ל שזהו עיקר) השתדלותם להשפיע על בנ\"י בזה\n— ה\"ז חטא גדול וחמור.\nג. ויתר על כן יש לומר, דזה ששו­רש הנהגת המרגלים הוא דבר שבקדו­שה, נרמז ונלמד גם מזה שאנשי דור המדבר נשארו במדבר ארבעים<sup data-n=\"744\">29</sup> שנה, ולא חיו חיי צער וטרדות, אלא אדרבה, חיי מנוחה, שכל מ' שנה הי' להם המן למזון, ומים מבארה של מרים וכו', וענני הכבוד הגינו בעדם וכו' (כנ\"ל).\nדלכאורה: הרי זה היתה טענתם ו­רצונם של (המרגלים ו)דור המדבר ל­השאר במדבר ולא להכנס לא\"י — ואיך מתאים שנתמלא מבוקשם ונשארו במד­בר במנוחה וענן ה' עליהם יומם ולילה כו'?\n[ועוד זאת: ע\"פ הידוע<sup data-n=\"745\">30</sup> שעונשי ה­תורה ענינם לתקן פגמו של החטא, ועד שיהי' המצב — הפך מענין החטא — יפלא ביותר, שבנדו\"ד לא שללו רצונם ולא תיקנו ושללו חטאם (כניסה לארץ) אלא היתה ההנהגה אתם כפי שרצו, שנשאר כל הדור ההוא — כל שנותיו במדבר! וגם את\"ל שמצד חטאם לא היו ראויים להכנס לא\"י (דמכיון שמאסו בא\"י לכן לא זכו להכנס אלי') — מ\"מ מהי ההסברה שהעונש יהי' להשאר ב­מדבר בחיי מנוחה כו' בתוך ענני הכבוד, ומשה ואהרן בראשם וכו'?]\nוע\"פ הביאור הנ\"ל (בפנימיות התורה) י\"ל הטעם בדבר, כי המעלה הרוחנית שבמדבר (שהיא כוונתם, ולש\"ש<sup data-n=\"746\">31</sup>) אינה טעות (אלא שבא עי\"ז ונסתעף מזה ל­מעשה דבר טעות),\nכלומר, הישיבה במדבר בתוך ענני הכבוד וכו' כשלעצמה יש בה קדושה, אלא שהם חשבו שזוהי התכלית הסופית, אף שמעלה זו היא (צ\"ל) הכנה לכניסה לא\"י, כי כדי להגיע לשלב הנעלה של כניסה לא\"י, מוכרחת ההכנה וההכשרה שעל ידי שהייתם במדבר מ' שנה.\nד. וילה\"ק בירור בדברי הרמב\"ם ב­הל' תשובה, שעל פיו אפשר להסביר ביאור זה (שבפנימיות התורה) — בסגנון ההלכה:\nבפ\"י מהל' תשובה כ' הרמב\"ם<sup data-n=\"747\">*31</sup>: אל יאמר אדם הריני עושה מצות התורה ו­עוסק בחכמתה כדי שאקבל כל הברכות הכתובות בה או כדי שאזכה לחיי ה­עוה\"ב ואפרוש מן העבירות שהזהירה תורה מהן כדי שאנצל מן הקללות הכתובות בתורה או כדי שלא אכרת מחיי העוה\"ב אין ראוי לעבוד את ה' על הדרך הזה שהעובד על דרך זה הוא עובד מיראה ואינה מעלת הנביאים ולא מעלת החכמים ואין עובדים ה' על דרך זה אלא עמי הארץ והנשים והקטנים שמחנכין אותן לעבוד מיראה עד שתרבה דעתן ויעבדו מאהבה.\nובפרק שלפנ\"ז<sup data-n=\"748\">32</sup> כתב \"ומפני זה נת­",[["744","29","כהלשון בזה בכ\"מ (בתושב\"כ ובתושבע\"פ) אף שבפועל הי' פחות מל\"ט שנה. וראה פרש\"י (פרשתנו יד, לג)."],["745","30","ראה לקו\"ש שם ע' 98 ואילך. וש\"נ."],["746","31","ראה לעיל הערה 15."],["747","*31","ה\"א."],["748","32","פ\"ט ה\"ב."]]],[1301430146,"אוו כל ישראל נביאיהם וחכמיהם ל­ימות המשיח כדי שינוחו ממלכיות שאינן מניחות להן לעסוק בתורה ובמצות כהוגן וימצאו להם מרגוע וירבו בחכמה כדי שיזכו לחיי העולם הבא\".\nולכאורה צריך ביאור: איך אפ\"ל ב­פ\"י ש\"אין ראוי לעבוד את ה' על הדרך הזה. . ואינה מעלת הנביאים ולא מעלת החכמים\", והרי לפנ\"ז כותב בפירוש<sup data-n=\"749\">33</sup> שזו<sup data-n=\"750\">34</sup> דרך הנביאים והחכמים (שלכן \"נתאוו כל ישראל נביאיהם וחכמיהם ל­ימות המשיח\"), הרי שזוהי כן מעלת הנביאים והחכמים<sup data-n=\"751\">35</sup>?\nבפשטות י\"ל שב' ענינים הם: בפ\"ט לא קאי באופן קיום התומ\"צ, כ\"א ב­ביאור תוכן ומהות שכר המצות שבחיי עוה\"ב<sup data-n=\"752\">36</sup>, שהם \"סוף כל השכר כולו וה­טובה האחרונה שאין לה הפסק וג­רעון\"<sup data-n=\"753\">37</sup>. ולכן \"התאוו לה כל הנביאים\"<sup data-n=\"754\">38</sup>, ו\"כמה כפּמה דוד והתאוה לחיי העולם הבא\"<sup data-n=\"755\">39</sup>, ומטעם זה ג\"כ נתאוו כל ישראל נביאיהם וחכמיהם (למצב זה בעולם<sup data-n=\"756\">40</sup>) לימות המשיח כי דוקא עי\"ז (יוכלו לעסוק בתורה ובמצות כהוגן ו)יזכו לחיי עולם הבא.\nמשא\"כ בפ\"י מבאר הרמב\"ם האופן הרצוי בקיום התומ\"צ, שכוונת עסק ה­תומ\"צ לא תהי' בשביל לזכות לחיי עוה\"ב אלא מאהבה. ונמצא, דאף שצ\"ל התאוה לחיי עוה\"ב אין זה מטרת קיום התומ\"צ<sup data-n=\"757\">41</sup>, אלא ענין בפ\"ע<sup data-n=\"758\">42</sup>.\nאבל חילוק זה לכאורה דחוק הוא, כי מהלשון \"(וימצאו להם מרגוע) וירבו בחכמה כדי שיזכו לחיי העולם הבא\" משמע, דסו\"ס מחשבתם וכוונתם (אף שלא בשעת קיום המצות) היא שעסק התומ\"צ הוא כדי לזכות לחיי העולם הבא.\nה. להלן בפ\"י ממשיך הרמב\"ם (ב­הלכה בפ\"ע): העובד מאהבה עוסק ב­תורה ובמצות והולך בנתיבות החכמה לא מפני דבר בעולם ולא מפני יראת הרעה ולא כדי לירש הטובה אלא עושה האמת<sup data-n=\"759\">43</sup> מפני שהוא אמת וסוף הטובה לבא בגללה ומעלה זו היא מעלה גדולה מאד ואין כל חכם זוכה לה והיא מעלת אברהם אבינו שקראו הקב\"ה אוהבו לפי שלא עבד אלא מאהבה.",[["749","33","וכ\"כ בהל' מלכים פי\"ב ה\"ד."],["750","34","משא\"כ מש\"כ \"כדי שנזכה לחיי העולם הבא\" בהל' תשובה פ\"ט ה\"א שם, שקאי ע\"ז שהקב\"ה משפיע לנו הטובות כו' \"כדי שלא נעסוק כל ימינו כו' אלא נשב פנויים ללמוד בחכמה ולעשות המצוה כדי שנזכה לחיי העולם הבא\", היינו שזוהי כוונת פעולת הקב\"ה, לא \"תאוות\" וכוונת האדם. ועד\"ז מש\"כ \"כדי שתזכו לחיי העוה\"ב\" דלקמן הל' תשובה שם."],["751","35","כן הקשה גם בהגהות עמק מלך על הרמב\"ם הל' מלכים שם."],["752","36","והוא ההמשך והסיום למה שהתחיל בפרק ח ע\"ד \"הטובה הצפונה לצדיקים\" היא חיי העוה\"ב."],["753","37","ל' הרמב\"ם שם פ\"ט ה\"ב."],["754","38","שם פ\"ח ה\"ג בסופה."],["755","39","שם ריש הלכה ז."],["756","40","כתוכן כו\"כ תפלות בנ\"י: תפלת (נדר) יעקב (ר\"פ ויצא) ועוד."],["757","41","וכן צריך לפרש במ\"ש הרמב\"ם שם רפ\"ז: ישתדל אדם לעשות תשובה כו' כדי. . (ש)יזכה לחיי העולם הבא."],["758","42","כמ\"ש הרמב\"ם בפיהמ\"ש סנהדרין הקדמה לפ' חלק (סד\"ה ועתה אחל): והתכלית הוא העוה\"ב ולעומתו הוא ההשתדלות כו' ועם היותו הוא התכלית המבוקש אינו ראוי למי שהוא רוצה שיהי' עובד מאהבה שיהי' עובד להשיג העוה\"ב כו'."],["759","43","וצ\"ע ענין האמת כאן.\nולהעיר מתחלת ס' הרמב\"ם פ\"א ה\"ד: הוא לבדו האמת\nאף שבפשטות הכוונה לאמתית מציאותו."]]],[1301430147,"וצריך ביאור, דלכאורה גם כאן סו­תר דברי עצמו: בה\"א כתב שהעבודה מיראה היא דרך עמי הארץ והנשים וה­קטנים \"ואינה מעלת הנביאים. . (ו)ה­חכמים\", היינו שעבודתם ומעלתם של החכמים והנביאים היא עבודה מאהבה; ובה\"ב כתב על העבודה מאהבה ד\"מעלה זו היא מעלה גדולה מאד ואין כל חכם זוכה לה\", הרי שאין זו מעלת (כל) ה­נביאים וכל החכמים.\nויתירה מזו: בה\"א מסיים דגם עמי הארץ וכו' שעובדים מיראה \"מחנכין אותן לעבוד מיראה עד שתרבה דעתן ויעבדו מאהבה\", הרי דעבודה מאהבה שייכת לכאו\"א, ובה\"ב מפורש ד\"מעלה זו היא מעלה גדולה מאד ואין כל חכם<sup data-n=\"760\">44</sup> (אפילו) זוכה לה\".\nו. לכן נראה לומר, שעסק התומ\"צ \"כדי שיזכו לחיי עוה\"ב\" שבפ\"ט, אין פירושו כדי לקבל השכר דעוה\"ב, אלא כדי להגיע להמשך עסק התומ\"צ באופן שהוא בעוה\"ב<sup data-n=\"761\">45</sup>.\nביאור הדבר: באהבת ה' ממשיך ה­רמב\"ם<sup data-n=\"762\">46</sup> \"וכיצד היא האהבה הראוי' הוא שיאהב את ה' אהבה גדולה יתירה עזה מאוד עד שתהא נפשו קשורה באהבת ה' ונמצא שוגה בה תמיד. . (ובסוף ה­פרק<sup data-n=\"763\">47</sup>:) דבר ידוע וברור שאין אהבת הקב\"ה נקשרת בלבו של אדם עד ש­ישגה בה תמיד<sup data-n=\"764\">48</sup> כו' אינו אוהב הקב\"ה אלא בדעת שידעהו כו' לפיכך צריך האדם ליחד עצמו להבין ולהשכיל ב­חכמות ותבונות המודיעים לו את קונו כו'\".\nהיינו, דגדר האהבה לה' הוא מה ש­נפשו (ודעתו) קשורה בה' — ד(שלימות) ענין זה הוא בעוה\"ב, וכמו שכ' הרמב\"ם בפ\"ח<sup data-n=\"765\">49</sup> ע\"ד עוה\"ב ד\"צדיקים יושבים ועטרותיהם בראשיהן ונהנין מזיו השכי­נה. . (ופי') עטרותיהן בראשיהן כלומר דעת שידעו שבגללה זכו לחיי העוה\"ב מצוי' עמהן והיא העטרה. . (ו)נהנין מזיו שכינה שיודעים ומשיגין מאמתת הקב\"ה מה שאינם יודעים והם בגוף האפל השפל\". ולכן כ' הרמב\"ם<sup data-n=\"766\">50</sup> ש\"זהו השכר שאין שכר למעלה ממנו והטובה שאין אחרי' טובה\".\nוביחד עם זה אין להם מנוחה (היפך ד\"יושבים\" ו\"נהנין\")<sup data-n=\"767\">*50</sup>\nהיינו שחיי עוה\"ב אינם (רק) \"שכר\" על עסק התומ\"צ אלא המשך ועלי' והתקרבות תמידית לשלימות הדביקות בה' שע\"י התומ\"צ.\nועפ\"ז יובן החילוק בין מ\"ש הרמב\"ם ברפ\"י \"אל יאמר אדם הריני עושה מצות התורה ועוסק בחכמתה כדי שאקבל כל",[["760","44","להגירסא בכמה כת\"י \"אדם\" (במקום \"חכם\") — ראה ספר המדע (ירושלים, תשכ\"ד) — מתורץ (וראה פיהמ\"ש שם ד\"ה וכת החמישית קרוב לסופה: שזה הענין קשה מאוד ואין כל אדם משיג אותו). אבל ברוב כת\"י ודפוסים איתא \"חכם\" (כבפנים)."],["761","45","ומהנפק\"מ למעשה — שההמשך בענין מעורר ומזרז לעלי' עוד יותר וכמרז\"ל מי שיש לו מנה רוצה מאתים מאתים רוצה ד' מאות (קה\"ר פ\"א, יג), ואין לו מנוחה, משא\"כ בקבלת שכר — עלול להיות שמח בחלקו וזאת מנוחתו."],["762","46","פ\"י ה\"ג."],["763","47","פ\"י ה\"ו."],["764","48","וי\"ל דבה\"ג מדובר כאשר כבר הגיע אהבה בלבו \"אהבת ה' בלב אוהביו שוגים בה תמיד\". ובה\"ו מדובר \"שישגה בה תמיד\" בדעתו בכדי להגיע לאהבת ה' בלבו."],["765","49","ה\"ב."],["766","50","שם סה\"ג. ועד\"ז בכ\"מ בפ\"ח וסוף פ\"ט."],["767","*50","ראה הערה 45."]]],[1301430148,"הברכות הכתובות בה או כדי שאזכה לחיי העוה\"ב\", למ\"ש בפ\"ט דזה ש\"נתאוו כל ישראל נביאיהם וחכמיהם לימות ה­משיח (הוא) כדי שינוחו ממלכיות שאינן מניחות להן לעסוק בתורה ובמצות כ­הוגן וימצאו להן מרגוע וירבו בחכמה כדי שיזכו לחיי העוה\"ב\":\nמש\"כ \"נתאוו כל ישראל נביאיהם ו­חכמיהם לימות המשיח כדי שינוחו מ­מלכיות כו' וירבו בחכמה כדי שיזכו לחיי העולם הבא\", אין רצונו לומר שהמטרה \"כדי לזכות לחיי עוה\"ב\" היא (ע\"מ לקבל) פרס, קבלת שכר על עבודתם, אלא כדי לזכות לתכליתה ושלימותה של האהבה והדביקות בה' (שמדבר לפנ\"ז)<sup data-n=\"768\">51</sup>, לשגות בה תמיד שזהו ע\"י שירבו ויוסיפו תמיד בחכמה בימות המשיח.\nמשא\"כ בפ\"י, שבו שולל הרמב\"ם עשיית מצות התורה כו' בכוונה לזכות לחיי העוה\"ב כקבלת שכר<sup data-n=\"769\">52</sup> על עבודתו, שלכן כללו הרמב\"ם בין שאר עניני תו­עלת ושכר דעבודתו — \"כדי שאקבל כל הברכות הכתובות בה. . כדי שאנצל כו'\". ומכיון שכוונתו אינה להעלי' ל­שלימות העבודה אלא לקבלת שכר<sup data-n=\"769\">52</sup>, לכן ההלכה \"אל יאמר אדם כו'\".\n[אלא שבזה גופא ישנם שני אופנים:\nבמ\"ש בריש פ\"י \"אל יאמר אדם כו' כדי שאקבל כל הברכות כו' או כדי שאזכה לחיי העולם הבא ואפרוש מן העבירות כו' כדי שאנצל מן הקללות כו' או כדי שלא אכרת מחיי העולם הבא\" כוונת הרמב\"ם לשלול העבודה מיראה, כלומר, שכוונת האדם העובד היא מפני שירא לחיי נפשו<sup data-n=\"771\">53</sup>, ולכן עובד ה' כדי שיהיו לו חיי מנוחה בעוה\"ז (וינצל מן הקללות כו'), או (במי שנוגעים לו חיי נפשו) כדי שתזכה נפשו לחיים נצחיים דעוה\"ב (ולא יכרת מחיי עולם הבא);\nולהלן בהלכה ד כותב הרמב\"ם \"אמ­רו חכמים הראשונים שמא תאמר הריני למד תורה בשביל שאהי' עשיר כו' בשביל שאקבל שכר בעולם<sup data-n=\"772\">54</sup> הבא ת\"ל לאהבה כו'\" — היינו שהכוונה שלו \"לקבל שכר\" היא (לא משום שירא לחיי נפשו, אלא) מפני שרוצה לקבל גמול ותשלום עבור עבודתו (תשלום גשמי — \"שאהי' עשיר\", או תשלום רוחני — \"ש­אקבל שכר בעולם הבא\"), שזוהי דרגא פחותה יותר בעובד ה' שלא לשמה<sup data-n=\"773\">55</sup>].\nז. אמנם אע\"פ שזה שהחכמים וה­נביאים נתאוו לזכות לחיי עולם הבא הוא המשך ועלי' יותר בעבודתם מאהבה — ישנה מדריגה נעלית יותר בעבודה מאהבה ש\"אין כל חכם זוכה לה\". וזהו מה שמחדש הרמב\"ם בהלכה ב<sup data-n=\"774\">56</sup> ע\"ד",[["768","51","ראה עבודת הקודש ח\"ב פ\"ה בשם החכם רבי יוסף. אבל שם לא כתב כן בדעת הרמב\"ם (וראה שם פירושו בדעת הרמב\"ם). וראה גם של\"ה (מז, א ואילך ושם מט, ב בהגהה בדעת הרמב\"ם)."],["769","52","וי\"ל דבכללות גם זה נקרא \"קבלת שכר\", אף שבפרטיות כפי המבואר ברמב\"ם שם ה\"ז נקרא \"עובד מיראה\" ולא \"קבלת שכר\", כדלקמן בפנים."],["769","52","וי\"ל דבכללות גם זה נקרא \"קבלת שכר\", אף שבפרטיות כפי המבואר ברמב\"ם שם ה\"ז נקרא \"עובד מיראה\" ולא \"קבלת שכר\", כדלקמן בפנים."],["771","53","או בלשונו בה\"ה \"שלא תגיע עליו פורענות\"."],["772","54","והיינו שאין כוונתו לזכות לחיי עוה\"ב (שהם המטרה של קיום התומ\"צ, \"סוף מתן שכרן של מצות\") — וכלשון הרמב\"ם בה\"א \"כדי שאזכה לחיי העולם הבא\" — אלא שרוצה לקבל שכר צדדי (לפי השגתו), ע\"ד \"בשביל שאהי' עשיר. . שאקרא רבי\", אלא שמקום קבלת שכר זה הוא \"בעוה\"ב\"."],["773","55","ולהעיר משינוי לשון הרמב\"ם — שבה\"א כ' \"כדי שאקבל הברכות כו' כדי שאזכה כו'\", ובה\"ד משנה וכ' \"בשביל שאהי' עשיר כו' בשביל שאקבל שכר בעוה\"ב\" (שמשמעו בשביל ענין אחר)."],["774","56","פשטות ל' הרמב\"ם בה\"ב \"העובד מאהבה עוסק בתומ\"צ כו'\" קאי בכללות במדריגת אהבה סתם. אלא י\"ל שבדיוק לשונו כולל מדריגה נעלית יותר באהבה."]]],[1301430149,"\"מעלת אברהם אבינו\" ש\"עושה האמת מפני שהוא אמת\".\nוי\"ל שמהיתרון בזה הוא:\nכאשר העבודה היא מאהבה סתם (ש­ישנה אצל כל ישראל (ועאכו\"כ) נביאי­הם וחכמיהם), הרי עסק התומ\"צ הוא בכדי להגיע להתקשרות ודביקות ב­הקב\"ה, ונמצא שהעסק בתומ\"צ הוא ב­אופן שאין העסק בשביל ולשם עצמו אלא בשביל מבוקש, שהוא כעין דבר נוסף; אבל כאשר העבודה מאהבה היא באופן ש\"עושה האמת מפני שהוא אמת\", הרי זה שולל לא רק העבודה בשביל קבלת שכר, אלא שאין מבוקש אחר בעבודתו, גם לא המבוקש שיתדבק בהקב\"ה שהוא התוכן דידיעת ה' ואהבת ה', כ\"א \"עושה האמת מפני שהוא אמת\", להיותו ציווי ורצון ה', שקיום ציווי ה' הוא אמת מצד עצמו.\nועל מעלה זו כתב הרמב\"ם \"ומעלה זו היא מעלה גדולה מאוד\", (ולא כמ\"ש בהלכה שלפנ\"ז סתם \"מעלת הנביאים\", \"מעלת החכמים\") — כי על מעלה זו אין לומר שהיא מעלת כל החכמים, ואדרבא כפי שממשיך \"ואין כל חכם זוכה לה\", אלא \"היא מעלת אברהם אבינו שקראו הקב\"ה אוהבו\", שכדי להגיע למעלה גדולה זו (\"עושה האמת מפני שהוא אמת\") צריך לעלות לדרגא נעלית מאד באהבה.\nח. וע\"פ כל הנ\"ל יש להסביר גם ב­נוגע למרגלים ודור המדבר:\nהמרגלים (ודור המדבר בכלל) היו כנ\"ל \"במדריגה גבוה מאד\", \"ולא רצו להשפיל א\"ע\"<sup data-n=\"775\">57</sup> להכנס לא\"י, בסדר ה­עבודה דשש שנים תזרע שדך גו', אדם חורש אדם זורע (כנ\"ל ס\"ב), משום ש­סדר עבודה זה אינו מניח להם לעסוק בתורה כו' \"כהוגן\", שהרי רוב ימיהם יהיו עסוקים \"בדברים שהגוף צריך להן\"<sup data-n=\"776\">58</sup>, והם רצו להשאר ולהמשיך ו­לנסוע ולעלות<sup data-n=\"777\">59</sup> בסדר החיים דמדבר, שהטובה מושפעת הרבה<sup data-n=\"778\">60</sup> כנ\"ל (מן מן השמים, מים מבארה של מרים, וענני הכבוד שהלכו עמהם, כנ\"ל) — ולא היו שום בלבולים בעבודת ה', ויכלו לישב פנויים למצוא להם מרגוע ולהרבות בחכמה לזכות לחיי עוה\"ב. וע\"ד מה ש\"נתאוו כל ישראל נביאיהם וחכמיהם כו' כדי שינוחו כו' וימצאו להם מרגוע כו'\".\nאבל אף שרצונם ותאוותם לכהנ\"ל ב­מדבר היא דרגא נעלית בדביקות בה'<sup data-n=\"779\">*60</sup>, עבודה מאהבה, מ\"מ הכניסה לא\"י מבי­אה לדרגא נעלית יותר, והוא קיום ציווי ה' בלי שום מבוקש כלל, \"עושה האמת מפני שהוא אמת\".\nאלא שכדי להגיע לדרגא זו דרושה אהבה נעלית עוד יותר, ומכיון שהמרג­לים ודור המדבר רצו להשאר במדבר ולא רצו להכנס לארץ, הרי זאת אומרת שעדיין לא הגיעו לדרגא זו דשלימות הדביקות והעלי' דאהבה.\nולכן נשארו בנ\"י במדבר במצב ד­העדר כל הדברים המונעים מלימוד התורה ודביקות בה' בתכלית, אופן ד­",[["775","57","לקו\"ת פרשתנו לז, רע\"א."],["776","58","רמב\"ם שם פ\"ט ה\"א."],["777","59","דפשיטא שצ\"ל מעלין בקודש."],["778","60","ראה רמב\"ם שם ובסוף הל' מלכים."],["779","*60","להעיר מלקו\"ת ראה לב, ג בפי' (פרשתנו יד, לה) במדבר הזה יתמו גו' (ע\"פ זהר פרשתנו קסג, ב)."]]],[1301430150,"מנוחה ומרגוע בכדי \"שירבו בחכמה\", שעי\"ז הגיעו לשלימות דביקות הנפש כו'<sup data-n=\"780\">61</sup>. ולאחרי זה, בדור הבא, בדור ו­דרגא חדשה, נכנסו לא\"י לקיים ציווי ה', הן בעצם הכניסה והן בקיום המצות מעשיות שבארץ, שדוקא בזה נרגש ענין \"עושה האמת מפני שהוא אמת\".\nוי\"ל שזהו גם תוכן דברי יהושע ו­כלב במענה אל כל עדת בנ\"י<sup data-n=\"781\">*61</sup> \"אם חפץ בנו ה' והביא אותנו גו'\" — שהכ­ניסה לארץ קשורה עם \"חפץ בנו<sup data-n=\"782\">62</sup> ה'\", זהו חפץ ורצון ה', ובמילא בקיומו מתג­לה \"חפץ בנו ה'\", דביקות בנ\"י בה' ב­אופן נעלה יותר מהדביקות שע\"י \"ירבו בחכמה\" שבמדבר.\nט. והנה הרמב\"ם בדברו על זה ש­\"עושה האמת מפני שהוא אמת\" מסיים \"וסוף הטובה לבוא בגללה\". ולכאורה מה ענין סיום זה לכאן — הרי מדובר בחכם כזה שאינו חושב כלל על הטובה שמגיע לו מעבודתו.\nויש לומר, שזה מובן מדיוק לשון הרמב\"ם \"וסוף הטובה לבוא בגללה\"<sup data-n=\"783\">63</sup>, והיינו דכאשר עבודתו היא באופן כזה ש\"עושה האמת מפני שהוא אמת\", אזי גם הטובה הבאה היא נעלית יותר<sup data-n=\"784\">64</sup> מטובת עוה\"ב ע\"ד הרגיל<sup data-n=\"785\">65</sup>, ובמילא גם מצד ענין ההתקשרות ודביקות נפשו בה' ה\"ה מגיע לשלימות נעלית יותר<sup data-n=\"786\">66</sup> בזה — ממי שלימוד התורה וקיום המצות שלו הוא באופן שיש לו מבוקש של התקשרות ודביקות בה'.\nועפ\"ז יש לבאר המשך דברי יהושע וכלב, שאמרו (לפנ\"ז<sup data-n=\"787\">67</sup>) \"טובה הארץ מאד מאד\"<sup data-n=\"788\">68</sup>, אף שע\"י אופן העבודה ב­מדבר, לימוד התורה באופן שהיו פנויים בחכמה, זוכים \"לראות<sup data-n=\"789\">69</sup> בטוב ה' ב­ארץ<sup data-n=\"790\">70</sup> חיים\" — עוה\"ב שהוא \"טובה גדו­לה עד מאד ואין לה ערך בטובות ה­עוה\"ז\", אשר \"אותה הטובה גדולה עד אין חקר ואין לה ערך ודמיון הוא שאמר",[["780","61","ועפ\"ז יש לבאר גם להפירוש דהעשרה מאמרות (הנ\"ל הערה 28) דדור המדבר אין להם צורך לעוה\"ב, אף שנת\"ל שרצונם ותאוותם להשאר במדבר הוא בדוגמת \"נתאוו כל ישראל כו' כדי שיזכו לחיי העוה\"ב\" — כי ע\"י היותם במדבר מ' שנה בפועל, שנסעו ונתעלו מחיל אל חיל עד שהגיעו למעלה עליונה יותר בהיותם למטה נשמה בגוף, הרי דרגת חיי עוה\"ב לנשמות (ע\"ד הרגיל) ש\"צדיקים יושבים. . ונהנין כו'\" (רמב\"ם הל' תשובה פ\"ח ה\"ב) הוא השפלה וירידה לגביהם ואין להם צורך לזה (ולהעיר משער מאמרי רז\"ל לר\"פ חלק בחילוקי דרגות בעוה\"ב. ואכ\"מ) — משיחת ש\"פ שלח תשמ\"ז."],["781","*61","פרשתנו יד, ח. וראה לקו\"ת פרשתנו לח, ג."],["782","62","להעיר מתורת הבעש\"ט עה\"פ כי תהיו אתם ארץ חפץ (\"היום יום\" י\"ז אייר. כתר שם טוב (הוצאת קה\"ת) הוספות סמ\"ד. וש\"נ)."],["783","63","בכמה גי' \"בכללה\" (ראה רמב\"ם ספר המדע שם)."],["784","64","משא\"כ בנדרים סב, א: למוד מאהבה וסוף הכבוד לבוא (ותו לא)."],["785","65","משא\"כ בנדרים שם שאין מדובר בטובת עוה\"ב וכיו\"ב כ\"א שלא יאמר אדם אקרא שיקראוני חכם אשנה שיקראוני רבי כו' (שכ' הרמב\"ם בפ\"י ה\"ד), וע\"ז מסיים: סוף הכבוד לבוא."],["786","66","כמ\"ש הרמב\"ם שם (פ\"ט ה\"א) לענין עוה\"ב: ולפי גודל מעשיו ורוב חכמתו הוא זוכה [וכן לדעת הרמב\"ן (בשער הגמול. וכ\"ה ההכרעה בתורת החסידות — ראה לקו\"ת צו טו, ג. דרמ\"צ יד, ב) שעוה\"ב הוא לנשמות בגופים — דישנם בזה חילוקי דרגות (ראה ב\"ב עה, א. תענית בסופה. לקו\"ש חי\"ט ע' 67 ואילך. חכ\"ד ע' 66 הערה 76). ואכ\"מ]."],["787","67","יד, ז."],["788","68","ראה לקו\"ת פרשתנו לז, א. לח, ג. לקו\"ש ח\"ד פ' שלח. ובכ\"מ."],["789","69","תהלים כז, יג. רמב\"ם שם פ\"ח ה\"ז."],["790","70","וראה רמב\"ם שם פ\"ג סוף ה\"ח."]]],[1301430151,"דוד<sup data-n=\"791\">71</sup> מה רב טובך אשר צפנת ליראיך וגו'\" (כמ\"ש הרמב\"ם בהל' תשובה<sup data-n=\"792\">72</sup>)\n— כי ע\"י הכניסה לא\"י וקיום המצוות שם — היינו אופן העבודה ד\"חפץ בנו ה'\" — \"עושה האמת מפני שהוא אמת\" — זוכים לטובה גדולה עוד יותר, לא רק \"מאד\" פ\"א (שמורה על טובה גדולה שלמעלה מיכולת האדם לקבל בעוה\"ז והיא טובת עוה\"ב) הבאה ע\"י עבודת ה' בבחי' \"מאד\", \"אהבה גדולה יתירה עזה מאד עד שתהא נפשו קשורה באהבת ה' ונמצא שוגה בה תמיד\", אלא \"מאד מאד\" ב\"פ, וכמ\"ש הרמב\"ם<sup data-n=\"793\">73</sup> ש\"עושה האמת מפני שהוא אמת וסוף הטובה לבא בגללה\", שישנה טובה הבאה דוקא ע\"י עבודה נעלית זו, שגם לגבי אהבה גדו­לה יתירה עזה מאד היא בבחי' מאד, כי זה מורה על ביטול האדם לגמרי לגבי הקב\"ה.\nי. והנה מזה שבתורה, שהיא (הוראה) נצחיית — מסופר ע\"ד המרגלים ודור המדבר ומענה יהושע וכלב על טענתם, מובן, שיש בכח כאו\"א מישראל להתנהג כפי דרישת יהושע וכלב, שלמעלה ממדריגה של \"במדריגה גבוה מאד\" של עבודת המרגלים (ודור המדבר).\nכלומר: מעלה זו דקיום מצות מעשיות בארץ שבאים ל\"טובה הארץ מאד מאד\" (ב\"פ), אינה רק עבור אלו ש­כניסתם לארץ באה לאחרי היותם במד­בר (וארבעים שנה), אלא ישנה בכאו\"א מישראל, דכאשר מקיים מצות בקב\"ע מפני שכן צווה ה', יש בקב\"ע זו מעלה יתירה על הדביקות שמצד האהבה.\nויש לומר, שגם זה מרומז בלשון ה­רמב\"ם:\nבהמשך לדבריו ע\"ד \"מעלת אברהם אבינו שקראו הקב\"ה אוהבו כו'\" כותב הרמב\"ם \"והיא המעלה שצונו בה הקב\"ה ע\"י משה שנא'<sup data-n=\"794\">74</sup> ואהבת את ה\"א ובזמן שיאהוב אדם את ה' אהבה הראוי' מיד יעשה כל המצות מאהבה\" (ובהלכה של­אח\"ז ממשיך לבאר \"כיצד היא האהבה הראוי'\") — ולכאורה אינו מובן: לאחרי כתבו ש\"מעלה זו היא מעלה גדולה מאד ואין כל חכם זוכה לה\", איך מתאים לומר \"והיא המעלה שצונו בה. . ע\"י משה\", היינו שנצטוו בה כל ישראל?\nאלא שהרמב\"ם בא להשמיענו, דמ\"ש \"ואין כל חכם זוכה לה\" היינו מכח עצמו ועבודתו, אבל (ע\"י ו)בכח ציווי השם (ע\"י משה) יכול כאו\"א להגיע לזה.\nיא. אמנם לכאורה יש לעיין עוד, ד­הרי אהבה היא מדה שבלב, שמגיעים אלי' ע\"י התבוננות בגדלות ה', כפי ש­האריך הרמב\"ם בסוף הפרק (וכן בהל' יסוה\"ת<sup data-n=\"795\">75</sup>), ומהו הפירוש שכאו\"א מ­ישראל יכול להגיע ל\"אהבה הראוי'\" ע\"ד מעלת אהבת אברהם אבינו?\nויובן זה בהקדם מ\"ש הרמב\"ם ב­הלכה ד \"אמרו חכמים הראשונים שמא תאמר הריני למד תורה בשביל שאהי' עשיר בשביל שאקרא רבי בשביל ש­אקבל שכר בעולם הבא ת\"ל<sup data-n=\"796\">76</sup> לאהבה את ה' כל מה שאתם עושים לא תעשו אלא מאהבה ועוד אמרו חכמים כו', וכן היו גדולי החכמים מצווים לנבוני תלמי­דיהם כו' אל תהיו כעבדים כו'\".",[["791","71","תהלים לא, כ."],["792","72","פ\"ח ה\"ו."],["793","73","הטעם שהרמב\"ם הביאו כאן בכלל — ראה לקו\"ש ח\"כ ע' 45 ואילך."],["794","74","ואתחנן ו, ה."],["795","75","רפ\"ב."],["796","76","עקב יא, יג."]]],[1301430152,"ולכאורה תמוה, מדוע המתין הרמב\"ם לשלול הכוונה \"בשביל שאהי' עשיר וכו'\" עד לאחרי הביאור בגודל מעלת העבודה מאהבה (מעלת אהבת אברהם אבינו (בהלכה ב) ותיאור ה\"אהבה הראוי'\" (בהלכה ג)), ולא כללה בהלכה א גבי עובד מיראה, ד\"אל יאמר אדם הריני עושה מצות התורה כו' כדי שאקבל כל הברכות כו'\"?\n[דכיון שזוהי דרגא פחותה יותר בעובד שלא לשמה (כנ\"ל סעיף ו) — הרי הו\"ל לשלול דרגא זו בשלא לשמה לפני האריכות ע\"ד גודל מעלת אברהם אבינו ו\"אהבה הראוי'\"].\nויש לומר, שבזה מדגיש הרמב\"ם שה­עבודה מאהבה \"שצונו בה הקב\"ה על ידי משה\" שייכת לכאו\"א מישראל, גם למי שהוא עדיין בדרגא פחותה מאד, שמצ\"ע הי' \"לומד תורה בשביל שאהי' עשיר כו'\".\nביאור הדבר:\nב\"אהבה הראוי'\" יש שתי מדריגות:\n(א) הרגש האהבה שבלב, ו\"מעלה זו היא מעלה גדולה מאוד\" והיא מעלת אברהם ביחוד, וכפי שמאריך בה\"ג \"וכי­צד היא האהבה הראוי' הוא שיאהב את ה' אהבה גדולה יתירה עזה מאוד עד שתהא נפשו קשורה באהבת ה' כו'\".\n(ב) גם מי שלא הגיע לידי מדריגת אברהם לאהוב את ה' אהבה הראוי' (המביאה את האדם ש\"עושה האמת מפני שהוא אמת\"), ואדרבה, מצ\"ע הוא בדרגא זו שאומר \"הריני למד תורה בשביל ש­אהי' עשיר כו'\" — גם לו ניתנה הוראת התורה \"לאהבה את ה', כל מה שאתם עושים לא תעשו אלא מאהבה\", דהיינו אף שאינו מרגיש בלבו אהבה הראוי', מ\"מ יכול לפעול בעצמו לעשות מ­אהבה<sup data-n=\"797\">77</sup>, היינו מחמת זה שצוה הקב\"ה, בדוגמת דרגא זו ב\"מעלה גדולה מאוד\" \"שעושה האמת מפני שהוא אמת\".\nוזהו מה שממשיך בהלכה שלאח\"ז (לאחרי שמבאר הענין דעבודה לשמה ושלא לשמה, \"ואמרו חכמים לעולם יעסוק אדם בתורה ואפילו שלא לשמה שמתוך שלא לשמה בא לשמה\") — \"לפי­כך כשמלמדין את הקטנים ואת הנשים וכלל עמי הארץ אין מלמדין אותן אלא לעבוד מיראה וכדי לקבל שכר עד ש­תרבה דעתן ויתחכמו חכמה יתירה מגלים להם רז זה מעט מעט ומרגילין אותן לענין זה בנחת עד שישיגוהו וידעוהו ויעבדוהו מאהבה\" — דלכאורה, הרי כבר כתב בהלכה א' שמחנכין אותן לעבוד מיראה עד שתרבה דעתן ויעבדו מאהבה, ולמה חזר ושנה ענין זה שוב?\nאלא שבזה בא להדגיש, שגם \"רז זה\", היינו המעלה הכי עליונה ד\"אהבה ה­ראוי'\" דאברהם אוהבי, ביכולת קטנים ונשים וכלל עמי הארץ להגיע אלי' (אלא שצריכין להרגילן בזה \"מעט מעט. . בנחת\") — כי לאחרי ש\"צונו בה הקב\"ה על ידי משה\", הרי בלימוד התורה וקיום המצות<sup data-n=\"798\">*77</sup> דכ\"א מישראל מחמת זה שהם ציווי ה', אף שאין בו אהבה בהתגלות לבו, ודאי שיבוא לעסק ולימוד לשמה כו' ויעבדוהו מאהבה<sup data-n=\"799\">78</sup>.\n<span data-k=\"q\">(משיחת ש\"פ שלח תשמ\"ו)</span>",[["797","77","להעיר מהקדמה לתניא ח\"ב חינוך קטן (אבל שם הוא באופן אחר). וראה תניא פט\"ז. שם רפי\"ז."],["798","*77","להעיר מתו\"א ר\"פ יתרו."],["799","78","צירוף עבודה ואהבה. ובגילוי ה\"ה העבודה. ועיין פי' אדה\"ז (ועבודתו בזה) כמצויין לעיל בסוף הערה 28."]]],[1301430153,"<h3>שיחה ג</h3>\nא. כתב המחבר בשו\"ע הל' ציצית<sup data-n=\"800\">1</sup> \"עיקר מצות טלית קטן ללבשו על בגדיו כדי שתמיד יראה ויזכור המצות\". וב­מג\"א שם<sup data-n=\"801\">2</sup> \"ובכתבים (היינו כתבי ה­אריז\"ל), דטלית קטן דוקא תחת בגדיו\".\nובפשטות<sup data-n=\"802\">3</sup>, חילוק שיטות זה הוא ה­מקור לשינוי מנהגים שמצינו בלבישת ט\"ק: הנוהגים ללבוש הט\"ק על בגדיהם למעלה, אזלי כפסק המחבר בשו\"ע; וה­לובשים הט\"ק מתחת לבגדיהם, נוהגים כדעת המג\"א ע\"פ כתבי האריז\"ל.\nובחילוק מנהגים זה בענין הבגד (ה­טלית קטן), יש עוד חילוק בנוגע לה­ציציות — כמה מהלובשים הט\"ק תחת הבגדים, נוהגין שיהיו הציציות מבחוץ.\nויש לעיין, אם מנהג זה שיהיו (רק) ה­ציציות מבחוץ, הוא ג\"כ ע\"פ כתבי ה­אריז\"ל, היינו שע\"פ האריז\"ל הט\"ק צ\"ל מתחת להבגדים, אבל הציציות עצמן צ\"ל בחוץ, או שזהו בכדי לחוש לפסק המחבר, אבל ע\"פ האריז\"ל — גם ה­ציציות צ\"ל מכוסות תחת הבגדים.\nוהנה מהמשך לשון המג\"א \"ונ\"ל דצריך שיהיו הציצית מבחוץ כו'\", אין לדייק לכאורה, שגם לה\"כתבים\" צריכין להיות מבחוץ — כי [מלבד זאת שי\"ל שגם כוונת המג\"א היא שיש להחמיר לצאת גם לדעת המחבר, הנה י\"ל ש]­עיקר<sup data-n=\"803\">4</sup> כוונת המג\"א במ\"ש \"שיהיו ה­ציצית מבחוץ\" אינה שיהיו מחוץ לה­בגדים (באופן שיוכל לראותן תמיד), כ\"א — שיהיו מחוץ להכנפות, וכהמשך לשונו שם \"ודלא כאותם שתוחבין אותן בהכנפות, ע\"ד מ\"ש בגמ<sup data-n=\"804\">5</sup> אין ציצית אלא יוצא כו'\" (וכן משמע בשו\"ע אדה\"ז<sup data-n=\"805\">6</sup> ש­לא הביא מ\"ש ב\"כתבים\" (כבמג\"א), ומ\"מ העתיק דברי המג\"א בסעיף בפ\"ע \"צריך שיהיו הציצית מבחוץ שנאמר<sup data-n=\"806\">7</sup> וראיתם אותו ודלא כאותן שתוחבין אותו בה­כנפות\")<sup data-n=\"807\">8</sup>.",[["800","1","או\"ח ס\"ח סי\"א. והובא בשו\"ע אדה\"ז שם סי\"ח (כדלקמן בפנים)."],["801","2","סקי\"ג."],["802","3","וזאת למודעי: כל הביאור שבהשיחה לא בא לקבוע ולהוכיח איך שצ\"ל המנהג בלבישת הטלית קטן, כי נהרא נהרא ופשטי', אלא רק להסביר טעמי חילוקי המנהגים הקיימים בזה.\nלכללות השאלה — ראה שו\"ת יחוה דעת (לה­גר\"ע שי' יוסף) ח\"ב ס\"א ובס' שנסמנו שם."],["803","4","ראה לקמן הערה 8."],["804","5","מנחות מא, ב ובפרש\"י שם — ראה מחה\"ש ופרמ\"ג (א\"א) למג\"א שם."],["805","6","או\"ח שם סי\"ט."],["806","7","פרשתנו טו, לט."],["807","8","אלא שמסיום הלשון במ\"א (ואדה\"ז) שם \"לכן נ\"ל דאנשים ההולכים בין העכו\"ם יוצאין בזה אך בשעת הברכה יהיו מגולין כדי הילוך ד\"א\" משמע דכוונתו לב' הענינים: שיהיו יוצאין ולא תחובין בתוך הכנפות, ושיהיו מגולין לא מכוסין.\nאבל מזה שאדה\"ז כ' ענין הנ\"ל (לא בהמשך ההלכה שצריך ללובשו על בגדיו שיראו הציצית תמיד (שבסי\"ח), אלא) בסעיף בפ\"ע (סי\"ט) \"צריך שיהיו הציצית מבחוץ וכו' ודלא כאותן שתוחבין אותו בהכנפות\", משמע לכאורה שהו\"ע בפ\"ע, שהם ב' ענינים ב\"וראיתם אותו\": א) שילבשו אותו באופן שיראו הציצית תמיד (שכ' בסעיף יח), ב) שיהיו הציצית מחוץ להכנפות — כי מצד דין הא' אם הכנפות והציצית אינן מכוסות, גם כשהציצית הם בתוך הכנפות, מתקיים \"וראיתם אותו\" — דהרי רואים הקשרים וכו' שיוצאים מהכנפות אף שאין רואים החוטים התלויים מחוץ להקשרים כו'. ולכן מוסיף בסי\"ט לימוד מיוחד \"צריך שיהיו הציצית מבחוץ שנאמר וראיתם אותו ודלא כאותן שתוחבין אותו בהכנפות\". ועצ\"ע."]]],[1301430154,"וגם לכאורה אין להכריע כן ממה ש­הביא אדה\"ז<sup data-n=\"808\">9</sup> (מהלבוש<sup data-n=\"809\">10</sup>) \"וכיון שטעם לבישת הציצית הוא כדי לזכור המצות, לפיכך הלובש<sup data-n=\"810\">11</sup> טלית קטן יזהר ללובשו על בגדיו כדי שתמיד יראוהו ויזכור ה­מצות, ואותן הלובשים אותו תחת הבגדים יזהרו שילבשו אותו באופן שיראו הציצית תמיד שע\"י ראייתן יזכרו המצות תמיד\" — כי גם בזה לכאורה אינו ברור אם זהו לפי שעיקר הקפידא שבכתבי האריז\"ל אינה אלא על הט\"ק ולא על הציצית, או שזהו רק כדי לחוש לפסק ההלכה (דברי המחבר בשולחנו) שיהיו הציציות מחוץ להבגדים.\nב. ולכאורה יש לפתור הספק ע\"פ מ\"ש במקור הדברים בכתבי האריז\"ל, ד­\"הי'<sup data-n=\"811\">12</sup> נוהג מורי (האר\"י) זלה\"ה כשהי' לובש הציצית. . הטלית גדול הוא למע­לה מכל המלבושים והט\"ק הוא תחת כל המלבושים<sup data-n=\"812\">13</sup> ושלא כדעת קצת המקו­בלים שמניחין אותו למעלה מכל המל­בושים והוא שיבוש<sup data-n=\"813\">14</sup>, אמנם יניחנו על החלוק\". ובטעם הדבר מבואר שם, כי \"ענין<sup data-n=\"814\">15</sup> ציצית ט\"ק שהוא בחי' הפנימית כו' וט\"ג הוא<sup data-n=\"815\">16</sup> כו'\".\nומובן, דטעם הנ\"ל בנוגע לט\"ק הוא (גם ובעיקר) על הציצית \"שהוא בחי' הפנימית\" (ובפרט, שהבגד עצמו אין בו קדושה וכו'<sup data-n=\"816\">17</sup>). ולפי זה, הרי גם ה­ציציות שבט\"ק צריכות להיות מכוסות<sup data-n=\"817\">18</sup> —",[["808","9","שם סי\"ח."],["809","10","שם סיו\"ד (כנסמן עה\"ג)."],["810","11","בלבוש שם לא הביא דין הנ\"ל שבשו\"ע (שיזהר ללובשו על בגדיו וכו') כאן (וכתבו בסי' כד) — אלא כותב \"וכיון שטעם. . המצות לפיכך אותם הלובשים הט\"ק תחת הבגדים יזהרו כו'\"."],["811","12","לשון הפע\"ח שער הציצית פ\"א. ועד\"ז הוא בשער הכוונות (ענין הציצית דרוש ו' ודרושי תפלת השחר פ\"ג) ועוד — הובאו במאסף לכל המחנות לשו\"ע או\"ח ס\"ח שם. וראה גם בהנסמן בהערות הבאות."],["812","13","ועד\"ז הוא בנגיד ומצוה וסידור האריז\"ל (סידור הר\"ש מרשקוב; זאלקווא תקמ\"א; סידור ר' אשר). וראה גם אור צדיקים (להר\"מ פאפריש) ס\"ז (הל' ציצית) ס\"ט. — ראה מאסף לכל המחנות שם."],["813","14","ובשער הכוונות שם: וטעות גדול הוא בידם הפך האמת."],["814","15","לשון הפע\"ח שם. ועד\"ז הוא בשער ה­כוונות, נגיד ומצוה וסידור האריז\"ל שם. וראה הערה הבאה."],["815","16","בפע\"ח שם \"פנימית של ג\"ת דיצירה וט\"ג הוא בחי' חיצונות שלהם\". וראה בהמשך הענין שם בפע\"ח, מה שמתרץ ממ\"ש דציצית קטן, אינו רק בעשי' — דציצית קטן הוא בחי' עיבור. ע\"ש ובשער הכוונות שם (הובא הענין גם בתו\"א תולדות יז, רע\"א (בל' אדמו\"ר נ\"ע בעצמו)). וראה נהר שלום ב\"כוונות הב' טליתות\". ואכ\"מ."],["816","17","אלא שע\"פ האריז\"ל הכוונה בזה שאין בו קדושה, היינו ש\"אין בנו כח להשיגו ולכן אין הקדושה חלה על הטלית עצמו. . אבל הציציות הנמשכים ויוצאים מן הטלית הזה יש לנו בהם יותר השגה ולכן נק' תשמישי מצוה\" — ראה שער הכוונות שם דרוש ב' בתחלתו. פע\"ח שם פ\"ג (ראה שמן ששון לשם). תו\"א מג\"א ק, א. לקו\"ת פרשתנו מד, ב."],["817","18","ועפ\"ז, מ\"ש בשער הכוונות שם (בדרוש ז'. ועד\"ז בפע\"ח שם ספ\"ו. והובא בסידור האריז\"ל הנ\"ל, אור צדיקים שם. ועוד) \"כי האדם צריך להסתכל בציציות בכל שעה ורגע כמש\"ה וראיתם אותו כו'\", קאי בעיקר לא בט\"ק אלא בט\"ג [וכהמשך הלשון שם דב\"ההסתכלות יש ב' כוונות. . המסתכל בהם בעת תפלת שחרית בק\"ש. . המסתכל בהם שלא בזמן התפלה\", דכמו שההסתכלות בעת תפלת שחרית בק\"ש, הכוונה להט\"ג שבו מתעטף בתפלה, עד\"ז הוא ההסתכלות שלא בזמן תפלה (דק\"ש וברכות הק\"ש. ואולי גם נוסף ע\"ז — כי בימיהם היו כמה שהיו לובשים ט\"ג לא רק בשעת ק\"ש ותפלה — ראה מ\"ח מסכת ציצית פ\"ה מ\"ג)]. וכ\"מ בפע\"ח שם שכ' בסיום כוונת ההסתכלות \"ולכן ביום נוהגין הציצית שאז יכולין להמשיך הראי' משא\"כ בלילה שהדינין גוברין ואז אין בידינו כח להמשיך הראי'\". והרי זה שרק \"ביום נוהגין הציצית\" הוא רק בט\"ג משא\"כ ט\"ק הוא תמיד כמ\"ש בפע\"ח שם ספ\"א ועוד (הובא לקמן בפנים ס\"ז).\nואת\"ל שקאי בט\"ק (וכ\"מ במצת שמורים הל' ציצית, סוד הסתכלות בציציות תמיד), אולי י\"ל דכוונתו לא בראי' כפשוטו אלא בהסתכלות, היינו התבוננות וכוונות כו'. וראה לקמן ס\"ח. ועצ\"ע."]]],[1301430155,"תחת הלבושים ולא מבחוץ<sup data-n=\"818\">19</sup>.\n[וכן מוכח ממש\"כ בזהר<sup data-n=\"819\">20</sup> ש\"בר נש\" אחד פגע בר' חייא ור' יוסי ולא ראה אותם לובשים ציצית, היינו שהציציות שלהם לא היו נראים בחוץ<sup data-n=\"820\">21</sup>, ועד כדי כך, דגם כאשר ה\"בר נש\" חשד בהם ש­הנהגתם אינה כדבעי — לא ביארו לו (גם אחר שראה שהם \"זכאין\") למה מתנהגים כן<sup data-n=\"821\">22</sup>, כי לפי דעתם פשוט שגם הציציות צ\"ל מכוסות].\nולפי זה, הרי הנוהגים לגלות ה­ציציות זהו רק לצאת גם לדעת המחבר, אבל ע\"פ כתבי האריז\"ל אין צורך בדבר<sup data-n=\"822\">23</sup>, ואדרבה, זהו טעם הנוהגים ללבוש הט\"ק תחת הבגדים<sup data-n=\"823\">*23</sup> באופן ש­גם הציצית הן מכוסות<sup data-n=\"824\">24</sup>.\nג. ויל\"ע בנוגע לכמה מההולכים ל­אור תורת אדמו\"ר הזקן בשולחנו הזהב, וביניהם גם מחסידי חב\"ד — שהציציות אצלם לא היו מגולין בחוץ. ולכאורה אינו מובן, שהרי דברי אדה\"ז בשולחנו ברורים ד\"אותן הלובשים אותו תחת ה­",[["818","19","בסידור הרש\"ר (ועוד. ועד\"ז באור צדיקים שם) \"בטלית קטן יעשה הציצית שלפניו ארוכים שיהיו מזומנים לו בכל עת לראותן\". אבל יש לפרש, דאין הכוונה שיהיו גלויים בפועל, אלא שיהיו מזומנים לו בכל עת שרוצה באופן שיוכל בקל להגבי' בגד העליון שלו לראותן. גם — לא הובא ענין זה בשער הכוונות ופע\"ח שם.\nובמאמר מרדכי (להר\"מ כרמי) או\"ח סכ\"ד ס\"א בסופו, ג\"כ תפס שפשוט שגם הציצית מכוסות דלא כהב\"י, ומסיים \"הלכך יותר נכון. . וכן נוהגין העולם ללובשו תחת הבגדים. וכ\"כ המ\"א. . בשם האריז\"ל, דט\"ק דוקא תחת בגדיו\".\nוכ\"מ מהראי' שבמקור חיים (להר\"ח הכהן) להל' ציצית ס\"ח סי\"א — הובא בס' יפה ללב (להר\"י פאלאג'י) לאו\"ח שם."],["819","20","ח\"א רד, סע\"ב ואילך."],["820","21","וראה ניצוצי אורות וניצוצי זהר (להרב מרגליות) לזהר שם."],["821","22","ע\"ד המסופר בזח\"ג (קפו, א), שר' יצחק ור' יהודא תרצו והסבירו למה לא קראו ק\"ש."],["822","23","וכ\"מ קצת מהנהגת אנשי מעשה (הובא בלקוטי מהרי\"ח מצות ציצית) שלובשים שני ט\"ק, א' תחת הבגדים על חלוקו כדעת האריז\"ל וא' על הבגדים כדעת הטושו\"ע. — ולא ראיתי נוהגין כן במדינתנו."],["823","*23","אבל ללבוש ט\"ק על הכתונת ולמעלה ממנה, בגד קצר (זשילעט), לכאורה אין יוצאים עי\"ז לפי כתהאריז\"ל, שהרי בכתהאריז\"ל מדייק \"תחת כל המלבושים. . יניחנו על החלוק\" (פע\"ח שם פ\"א), \"למטה משאר מלבושיו ע\"ג חלוקו\" (שער הכוונות שם דרוש ו), ועד\"ז בשאר מקומות הנ\"ל, וכהובא במג\"א שם \"תחת בגדיו\", ובסי' קול יעקב: האריז\"ל הי' נוהג ללבוש הטלית קטן בביתו על חלוקו בלי הפסק שום מלבוש."],["824","24","וכ\"מ מפשטות דברי הב\"י או\"ח סכ\"ג<sup data-n=\"e18\">*</sup>; פרישה שם. ומפורש בב\"ח (וש\"ך) יו\"ד סשס\"ז (סק\"ד) \"נהגו העולם היתר בטליתות קטנים תחת בגדיהם כיון שהציצית מכוסים\".\nזה שהט\"ק הוא תחת הבגדים, מפורש בכמה פוסקים — בעל העיטור הל' ציצית סוף החלק השלישי; ספר היראה לרבינו יונה קרוב לתחלתו; מרדכי הל' ציצית סתתקמ\"ג (בשם מהר\"ם מרוטנבורג) ותענית סי' תרלז; שו\"ת הרדב\"ז ח\"ה ב' אלפים קו; שם ב'קס. ועוד. אלא שבכל הנ\"ל א) אין מבואר שכ\"ה בנוגע להציצית. ב) לא נאמר שכצ\"ל ע\"פ הלכה, אלא שבכמה מהם מעשה רב. ואכ\"מ."],["e18","*","ובשו\"ע אדה\"ז שם לא משמע כן. ואכ\"מ."]]],[1301430156,"בגדים יזהרו שילבשו אותו באופן ש­יראו הציצית תמיד כו'\".\n[ואין לתרץ ע\"ד שמצינו<sup data-n=\"825\">25</sup> לענין \"המספר קומי\" שהוא \"מדרכי האמורי\", ד\"אבטולמוס בר ראובן התירו לו לספר קומי מפני שהוא קרוב למלכות\" — כי כמה מהנ\"ל מצאנו ראינו שלא היו ה­ציציות שלהם גלויות הגם שלא היו \"קרובין למלכות\" (וגם באלו שהיו צרי­כים להשתדל עבור בנ\"י אצל המלכות — עשו כן גם בזמן שלא עסקו בזה).\nגם מובן שאין הטעם בזה לפי שב­אותו הזמן היו הולכים בין הגוים כו'<sup data-n=\"826\">26</sup>, כי המדובר גם בחסידים שקיימו כל מנהגי ישראל, ופשיטא — פס\"ד של אדה\"ז בשולחנו!]\nואולי י\"ל בזה ע\"פ המסופר<sup data-n=\"827\">27</sup> \"מפי הרה\"ג החסיד המפורסם ר' הלל פּאַריטשער זי\"ע אשר פעם אחד שאלו את אדמו\"ר הזקן איך לנהוג בדבר שה­מקובלים מחולקים עם הפוסקים, והשיב אדמו\"ר מסתמא יש לנהוג כהמקובלים. ושאלו אותו הלא הוא בעצמו בשו\"ע שלו<sup data-n=\"828\">28</sup> כתב שיש לילך אחר הפוסקים, והשיב כן כותבים הפוסקים (ובשו\"ע נמשך אחר הפוסקים) אבל המקובלים כותבים לילך אחר המקובלים נגד הפוסקים<sup data-n=\"829\">29</sup> (שהכריעו נגד המקובלים, ומובן שאין לומר שהמקובלים יהיו נגד התלמוד (או הפוסקים שלמדו דבריהם מן הגמ', שבזה כל ישראל שווים) כ­מבואר בשו\"ע סימן ס\"ח)\"<sup data-n=\"830\">30</sup>.\nועפ\"ז, ההנהגה דאלה שלבשו הט\"ק וגם הציצית בפנים, שיסודה ע\"פ מ\"ש בכהאריז\"ל (כנ\"ל) — ה\"ה ע\"פ הוראת אדה\"ז עצמו, לנהוג כהמקובלים (ה­אריז\"ל וכו') במקום שאינו כפי ה­פוסקים.\nועדיין יש מקום עיון בדבר: לפי הנ\"ל הי' צ\"ל כן מנהג כל אלה ההולכים לאור תורת אדה\"ז, שיהיו הציציות מכו­סות ביחד עם הט\"ק<sup data-n=\"831\">31</sup>, ולמעשה רואים שכו\"כ נוהגין כפסק אדה\"ז בשולחנו, ללבוש הט\"ק תחת הבגדים באופן שיראו הציציות — שלא ע\"פ כתבי האריז\"ל הנ\"ל<sup data-n=\"832\">32</sup>.\nד. ואולי י\"ל בהקדם הביאור בעצם הענין דלבישת ציצית מתחת להבגדים, דלכאורה יש לתמוה — שהרי הטעם לכך שע\"פ נגלה הציציות צריכות להיות מגולות — הוא ע\"פ הכתוב מפורש (שהוא תוכן מצות ציצית) \"וראיתם אותו",[["825","25","ב\"ק פג, א. סוטה מט, ב. רמב\"ם הל' ע\"ז פי\"א ה\"א וה\"ג. טושו\"ע יו\"ד סקע\"ח ס\"א וב'."],["826","26","ראה ערוך השלחן או\"ח ס\"ח סי\"ז. מ\"ב שם סקכ\"ו."],["827","27","שער הכולל פ\"א סק\"א (נעתק גם בשו\"ע אדה\"ז (קה\"ת) או\"ח ח\"א בסופו (קפד, ב))."],["828","28","או\"ח סכ\"ה סכ\"ח."],["829","29","וכן הכריע בסידורו בד\"כ — כהמקובלים ולא כהפוסקים (ודלא כבשו\"ע שלו) — שער הכולל שם בריש הפרק. ולהעיר משו\"ת צ\"צ או\"ח סי\"ח אות ד'. שו\"ת דברי נחמי' או\"ח סכ\"א."],["830","30","ומסיים בשער הכולל שם: וכ\"ה בשערי תשובה סכ\"ה סקי\"ד בשם הרדב\"ז והחכם צבי."],["831","31","להעיר ממכתב כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע, באג\"ק אדמו\"ר מהוריי\"צ ח\"ז ע' קלא. סה\"ש תש\"ה ע' 115."],["832","32","ואולי מנהג כו\"כ בדורנו, שלא רק שהט\"ק הוא למטה מתחת לבגדים<sup data-n=\"e19\">*</sup>, אלא שהט\"ק תחוב במכנסיים, ורק הציציות מוציאין אותן, וע\"ז עוד לובשים בגד עליון — הוא לחוש לדעת כתבי האריז\"ל."],["e19","*","כבימיהם, שכל השקו\"ט הי' אם ישנו בגד עליון המכסה הט\"ק והציצית."]]],[1301430157,"וזכרתם את כל מצות ה' גו'\"<sup data-n=\"833\">33</sup>, וגם דרשינן בגמ'<sup data-n=\"834\">34</sup> \"וראיתם אותו וזכרתם ועשיתם — ראי' מביאה לידי זכירה כו'\",\nוכיון שטעם לבישת ציצית הוא בכדי לזכור כל המצות כמ\"ש וראיתם אותו וזכרתם גו', וכלשון אדה\"ז בשו\"ע שם — יש להבין למה ע\"פ כתהאריז\"ל אין הציציות צריכות להיות מגולות?\nואף שבפע\"ח שם נאמר בזה טעם ע\"פ קבלה כנ\"ל — טעמא בעי, שהרי (כמובא לעיל) לא יצוייר שהמקובלים יהיו נגד התלמוד כו'.\nה. ואולי י\"ל הביאור בכל זה:\nמ\"ש \"וראיתם אותו וזכרתם את כל מצות ה'\", יש לפרש בשני אופנים: ד­\"וראיתם אותו וזכרתם\" הוא מגוף מצות ציצית (כדמשמע לכאורה מזה שנאמר בכתוב \"והי' לכם לציצית וראיתם אותו גו'\"), או ד\"וראיתם אותו גו'\" הוא דבר נוסף הבא כתוצאה מקיום מצות ציצית.\nונפק\"מ לדינא, דלאופן הא' כיון ד­קיום מצות ציצית (כתיקונה) הוא כאשר ישנו ה\"וראיתם אותו\" בפועל, או שישנה האפשרות לראות הציצית<sup data-n=\"835\">35</sup>, הרי אם חסר בזה — לא קיים מצות ציצית (כתי­קונה); משא\"כ לאופן הב' דקיום מצות ציצית הוא בעצם (עשייתן ו)לבישתן, הרי גם כשא\"א להיות \"וראיתם אותו\" קיים מצות ציצית כתיקונה, אלא שחסר דבר הנוסף — השלימות שיש במצות ציצית — קיום ענין \"וראיתם אותו ו­זכרתם את כל מצות ה' גו'\".\nולכאורה תלוי בב' הפירושים (ש­הביא רש\"י<sup data-n=\"836\">36</sup>) בתיבת \"ציצית\"<sup data-n=\"837\">37</sup>: א) \"ע\"ש הפתילים התלויים בה כמו<sup data-n=\"838\">38</sup> ויקחני ב­ציצית ראשי\"; ב) \"ציצית על שם וראיתם אותו כמו<sup data-n=\"839\">39</sup> מציץ מן החרכים\"<sup data-n=\"840\">40</sup>:\nדלפי' הב' דשם \"ציצית\" הוא ע\"ש ו­ראיתם אותו, מובן ד\"וראיתם אותו\" הוא גדר מצות ציצית<sup data-n=\"841\">41</sup>, וכשחסר \"וראיתם אותו\" חסר בחפצא דציצית, ולא קיים מצות ציצית כתיקונה; משא\"כ לפי' הא' שהוא ע\"ש הפתילים, הרי החפצא ד­ציצית אינו אלא הפתילים עצמם, וא\"כ קיום המצוה הוא כשלובש בגד עם ה­פתילים התלויים ויוצאים ממנה.\nו. וי\"ל דבזה פליגי הרמב\"ם והטור:\nבסוף הל' ציצית<sup data-n=\"842\">42</sup> כתב הרמב\"ם, ש­\"אע\"פ שאין אדם מחוייב לקנות לו טלית ולהתעטף בה כדי שיעשה בה ציצית,",[["833","33","כהובא בשו\"ע אדה\"ז ס\"ח, וכפשטות הלשון בשו\"ע \"שתמיד יראהו ויזכור המצות\". וכן בטושו\"ע ר\"ס כד.\nבב\"י לטור ס\"ח שם כ' \"וכן כתב נמ\"י בשם הריטב\"א\". ובנמוק\"י להלכות ציצית בשם הריטב\"א שם כ' \"ואפילו אותם שאין נוהגין אלא בט\"ק ראוי ללבוש אותו על מלבושיהם לקיים בו יפה ולא תתורו אחרי לבבכם ואחרי עיניכם\" (וראה לקמן הערה 78)."],["834","34","מנחות מג, ב."],["835","35","ראה לקמן הערה 61."],["836","36","פרשתנו טו, לח."],["837","37","גם בעוד מפרשי התורה נאמרו ב' פירושים אלה (ראה רשב\"ם, ר\"י בכור שור ועוד), אבל הם פירשו זה בב' כתובים נפרדים שבציצית, בפסוק לח פי' \"כמו בציצית ראשי קבוצת פתילים כו'\", ובפסוק לט (בו נאמר וראיתם אותו) פי' \"והי' לכם לציצית הציצית הזה יהי' לכם לראי' שתראו אותו כמו מציץ מן החרכים\" (ל' הרשב\"ם). וא\"כ אין מזה ראי' (כ\"כ) על גוף מצות ציצית."],["838","38","יחזקאל ח, ג."],["839","39","שה\"ש ב, ט."],["840","40","וכ\"ה בספרי עה\"פ."],["841","41","להעיר מאוה\"ת פרשתנו ע' תרד, שמביא ממ\"כ לרבות סוף פרשתנו \"והי' לכם לציצית שתהא נראית\" — \"פי' שצריך שיהיו הציצית על בגדיו כו' כמ\"ש הפוסקים כו'\". — ראה לקמן ס\"ז."],["842","42","פ\"ג הי\"א."]]],[1301430158,"אין ראוי לאדם חסיד שיפטור עצמו מ­מצוה זו אלא לעולם ישתדל להיות עטוף בכסות המחוייבת בציצית כדי ש­יקיים מצוה זו כו'\", ובהלכה שלאח\"ז<sup data-n=\"843\">43</sup> \"לעולם יהא אדם זהיר במצות ציצית שהרי הכתוב שקלה ותלה בה כל המצות כולן שנאמר וראיתם אותו וזכרתם את כל מצות ה'\".\nוהטור הביא ג\"כ בספרו<sup data-n=\"844\">44</sup> מעלת ה­זהירות במצות ציצית, וז\"ל: \"אע\"פ שאין אדם חייב לקנות טלית. . כדי שיתחייב בציצית כו' מ\"מ טוב ונכון להיות כל אדם זהיר וזריז במצות ציצית שיהי' לו בגד קטן מצוייץ שילבש אותו כל היום כי עיקר מצותה על זכירת המצות ובכל שעה ובכל רגע צריך לכך כו'\".\nחזינן, שהרמב\"ם חילק ההשתדלות והזהירות במצות ציצית לב' פרטים בב' הלכות. תחלה מדבר אודות מצות ציצית עצמה, ש\"אין ראוי כו' שיפטור עצמו ממצוה זו כו' לעולם ישתדל כו' כדי שיקיים מצוה זו\", ובהלכה בפ\"ע מבאר הזהירות הבאה מזה, שהציצית מביאה לידי זכירת כל המצות — \"שהרי הכתוב שקלה ותלה בה כל המצות כולן\"<sup data-n=\"845\">45</sup>,\nמשא\"כ הטור כללן ביחד כענין והמשך אחד, ולא הזכיר ע\"ד ההשתדלות בקיום מצות ציצית בפ\"ע, כ\"א הזהירות במצות ציצית מצד זכירת כל המצות שבה, ומדייק שענין זה הוא \"עיקר מצותה\" דציצית.\nוע\"פ הנ\"ל מובן, דלהרמב\"ם \"וראיתם אותו וזכרתם את כל מצות ה' גו'\" (ש\"הכתוב שקלה ותלה בה כל המצות כולן\") הוא דבר נוסף<sup data-n=\"846\">46</sup> על עצם מצות<sup data-n=\"847\">*46</sup> ציצית<sup data-n=\"848\">47</sup>, שלכן חלקם לב' פרטים בב' הלכות, ומדגיש חילוקם: חיוב ההשתד­לות במצות ציצית עצמה \"קיום מצוה זו\"; הזהירות במצות ציצית לפי שיש בה עוד ענין<sup data-n=\"849\">48</sup> (מלבד עצם המצוה) — \"שהרי",[["843","43","שם הי\"ב."],["844","44","או\"ח סכ\"ד."],["845","45","ראה לקו\"ש חכ\"ט ע' 4­63."],["846","46","וי\"ל שהמקור לזה הוא ממנחות מג, ב \"ורבנן האי וראיתם אותו מאי עבדי לי' כו'\", ומשמע דס\"ל שאינו מעיקר המצוה. ויתירה מזו, שא\"צ שיראו אותן כפשוטו. וכ\"מ גם מזה ש\"מבעי' לי' לכדתניא וראיתם אותו וזכרתם ראה מצוה זו וזכור מצוה אחרת התלוי' בו ואיזו זו זו קרית שמע\", דלפי דרשה זו (וכן לפי הדרשות שלהלן שם: תניא אידך. . ראה מצוה זו וזכור מצוה אחרת הסמוכה לה ואיזו זו זו מצות כלאים. . תניא אידך וראיתם אותו. . כיון שנתחייב אדם במצוה זו נתחייב בכל מצות כולן), פי' \"וראיתם אותו וזכרתם גו'\" אינו שיראו אותן כפשוטו כו'. וראה לקמן הערה 48. ועצ\"ע."],["847","*46","וכ\"מ בגמ' ברכות (יב, ב) \"פרשת ציצית. . יש בה חמשה דברים מצות ציצית. . עול מצות. . דכתיב וראיתם אותו וזכרתם את כל מצות ה' ציצית דכתיב ועשו להם ציצית וגו'\". ומשמע, שעול מצות, שהוא \"וראיתם אותו וגו'\", הוא דבר נוסף במצות ציצית.\nועפ\"ז יומתק ל' הרמב\"ם (הל' ק\"ש פ\"א ה\"ב) \"ואח\"כ פרשת ציצית שגם היא יש בה ציווי זכירת כל המצות\", ולא כפרש\"י ברכות שם שפי' \"עול מצות — ועשיתם כל מצותי\". כי להרמב\"ם גם זכירת המצות, הכתוב \"וראיתם אותו וזכרתם את כל מצות ה'\", אינה מגוף מצות ציצית אלא דבר נוסף — עול מצות שנאמר ב\"פרשת ציצית\" [ובפרש\"י י\"ל שכתב מה שלכו\"ע, דגם להדיעה ד\"וראיתם אותו וזכרתם גו'\" הוא מגוף מצות ציצית (כמו להפי' דציצית הוא ע\"ש וראיתם אותו שהביא בפי' עה\"ת כנ\"ל ס\"ה) יש בה גם \"עול מצות\", והוא מ\"ש בכתוב שלאח\"ז \"ועשיתם את כל מצותי\". וראה לקמן ע' 154 הערה 50].\nולהעיר מזהר הרקיע אזהרה כ."],["848","47","והרמב\"ם בריש הל' ציצית פי' לשון ציצית \"שהוא דומה לציצית של ראש שנא' ויקחני בציצית ראשי\", ולא פי' שהוא מלשון ראי'."],["849","48","שלכן גם לדעת הרמב\"ם, למידין (שם פ\"ג ה\"ז) מ\"וראיתם אותו\" שאין לילה זמן ציצית. ולהעיר שמלשונו שם \"חובת הציצית ביום ולא בלילה שנא' וראיתם אותו בשעת ראי'\", משמע דלהרמב\"ם אין מצוה בראייתו בפועל, אלא פי' וראיתם אותו היינו בזמן ראי'."]]],[1301430159,"הכתוב שקלה ותלה בה כל המצות כולן\".\nמשא\"כ הטור ס\"ל ד\"וראיתם אותו וזכרתם את כל מצות ה'\" הוא מגוף<sup data-n=\"850\">49</sup> מצות ציצית<sup data-n=\"851\">50</sup>.\n[וכמו שביאר הב\"ח<sup data-n=\"852\">51</sup> דברי הטור בזה שמקדים להתעטף בציצית לפני הנחת תפלין \"לפי שציצית באים כדי לזכור כל המצות<sup data-n=\"853\">52</sup>, אבל התפילין היא מצוה יחי­דית כו'\".\nולהעיר מדברי הב\"ח<sup data-n=\"854\">53</sup>, בהטעם ש­הביא הטור הכוונה במצות ציצית \"ויכוין בהתעטפו שציונו המקום להתעטף כדי שנזכור כל מצותיו לעשותם\" (אף \"שאין זה מדרכו בחיבורו זה לבאר כוונה לשום מקרא שבתורה\"<sup data-n=\"855\">54</sup>), \"דלפי שכתוב בפרשת ציצית<sup data-n=\"856\">55</sup> למען תזכרו גו' יורה כי עיקר המצוה וקיומה תלויות בכוונתה שיכוין בשעת קיום המצוה\"<sup data-n=\"857\">56</sup>, \"שלא<sup data-n=\"855\">54</sup> קיים המצוה כתיקונה אם לא יכוין אותה הכוונה\"<sup data-n=\"859\">57</sup>].\nולכן אין לחלקם לב' ענינים, וכ­מפורש בלשונו \"להיות כל אדם זהיר וזריז במצות ציצית. . כי עיקר מצותה על זכירת המצות\"<sup data-n=\"860\">58</sup>.\nז. והנה כ\"ז הוא בקיום מצות ציצית מעיקר הדין, היינו בטלית גדול, דגם ל­הדיעה שאין \"וראיתם אותו\" מגוף ה­מצוה, ה\"ה פרט בהמצוה, ובמילא פשוט דמצות טלית גדול היא ללובשו ע\"ג ה­",[["850","49","ומה שהביא הטור בריש ס\"ח \"ונק' ציצית ע\"ש החוטין הנפרדים\", כ' בנוגע להלכה ש\"ע\"כ צריך להפרידם זמ\"ז\" (כמ\"ש הב\"ח שם), ולא כברמב\"ם שבזה התחיל כל הל' ציצית — כהגדרה על מצות ציצית (וראה רמב\"ם שם פ\"א סה\"ח)."],["851","50","וכמפורש בזהר פרשתנו (רע\"מ) קעד, ב: ציצית פקודא דא איהו לאדכרא כל פקודי אורייתא כו'."],["852","51","ר\"ס כה."],["853","52","ולהעיר שגם בסכ\"ד שם, במ\"ש הטור \"גדולה מצות ציצית ששקולה כנגד כל המצות דכתיב וראיתם אותו וזכרתם את כל מצות ה' ציצית עולה ת\"ר וח' חוטין וה' קשרים י\"ג הרי תרי\"ג\" — מפרש הב\"ח שם שהכל \"הוא גורם לזכרון, דע\"י שיעלה על מחשבתו דציצית עולה כו' תרי\"ג ע\"י כך יזכור כל תרי\"ג מצות\". ע\"ש בפרטיות. והוא דלא כפשטות הפי', שהיא מצ\"ע שקולה (וע\"ד שנאמר בע\"ז ושבת בפרש\"י סוף פרשתנו הלשון שקולה). וראה לקו\"ש ח\"ח ע' 97 ואילך."],["854","53","או\"ח ס\"ח ד\"ה ונקראים ציצית. סתרכ\"ה קרוב לתחלתו."],["855","54","ל' הב\"ח שם סתרכ\"ה."],["856","55","פרשתנו טו, מ."],["857","56","לשונו שם ס\"ח."],["855","54","ל' הב\"ח שם סתרכ\"ה."],["859","57","וי\"ל שזהו רק לשיטת הטור ד\"וראיתם אותו וזכרתם את כל מצות ה'\" הוא מגוף מצות ציצית. אבל לדיעה הב' הנ\"ל דאינו מגוף המצוה, י\"ל ד(אף אם נדייק בתיבת \"למען\" כדברי הב\"ח שם גבי תפלין וסוכה) שאני ציצית מתפילין וסוכה, דבתפילין וסוכה נאמרה תיבת \"למען\" על קיום המצוה, \"והי' לך לאות גו' למען תהי' תורת ה' בפיך כי ביד חזקה הוציאך ה' ממצרים\" (בא יג, ט), \"בסוכות תשבו גו' למען ידעו דורותיכם גו'\" (אמור כג, מב­ג), ואילו בציצית — הכתוב \"למען תזכרו ועשיתם את כל מצותי\" בא בהמשך להכתוב \"וראיתם אותו וזכרתם את כל מצות ה' ועשיתם אותם\", שלדיעה הנ\"ל אינו מגוף קיום המצוה. וראה עולת תמיד או\"ח שם סקי\"א."],["860","58","וכ\"מ מדברי רבינו יונה בספר היראה קרוב לתחלתו, וכמו שהביא בביאורי הגר\"א בשו\"ע שם רסכ\"ד.\nוראה גם שו\"ת הריב\"ש ח\"ב סקכ\"ו (הובא בב\"י שם סכ\"ד). ולהעיר מפסקי דינים להצ\"צ לאו\"ח ס\"ח (אות ז): אבל בציצית נזהרין כל העולם ואין זה מדת חסידות לבד כ\"א מצוה דאורייתא כמ\"ש וראיתם אותו וזכרתם כו'. ע\"ש."]]],[1301430160,"בגדים באופן שיש בו \"וראיתם אותו וזכרתם גו'\".\nאבל לענין ט\"ק, פליגי הפוסקים — אם תקנו שהאדם יקיים כל הזמן מצות ציצית בפני עצמה כמצוה פרטית (נוסף על קיום מצות ציצית בט\"ג, שמקיים בו (גם) וראיתם אותו), או — שכל עיקר התקנה דט\"ק היתה כדי לזכור את כל המצות תמיד:\nלדעת המחבר, \"עיקר מצות טלית קטן ללובשו על בגדיו כדי שתמיד יראהו ויזכור המצות\", לפי שקאי בשיטת הטור הנ\"ל, וכמפורש בחיבורו ב\"י<sup data-n=\"861\">59</sup>, שדין הנ\"ל הוא — \"ממה שאמר (הטור<sup data-n=\"862\">60</sup>) בסימן כד כי עיקר מצותה על זכירת המצות ובכל שעה ובכל רגע צריך שיזכור נראה שעיקר מצות טלית קטן ללובשו מלמעלה כדי שתמיד יראהו<sup data-n=\"863\">61</sup> ויזכור המצות\"<sup data-n=\"864\">62</sup>.\nובשיטה זו קאי אדה\"ז בשלחנו, שב­תחלה כ'<sup data-n=\"865\">63</sup> \"כשיתעטף בציצית יכוין ש­ציונו הקב\"ה להתעטף בציצית כדי שנז­כור כל מצותיו לעשותם שנאמר וראיתם אותו וזכרתם את כל מצות ה'\", ואח\"ז ממשיך \"וכיון שטעם לבישת הציצית הוא כדי לזכור המצות לפיכך הלובש טלית קטן יזהר ללובשו על בגדיו כדי שתמיד יראוהו ויזכור המצות\", וממשיך \"ואותן הלובשים אותו תחת הבגדים יזהרו ש­ילבשו אותו באופן שיראו הציצית תמיד שע\"י ראייתן יזכרו המצות תמיד\", ש­מדייק \"יזהר\" \"יזהרו\", כי בלי זה חסר בגוף מצות ציצית.\nאבל לפי מ\"ש בכהאריז\"ל, ענין הט\"ק אינו אלא בשביל קיום מצות ציצית לבד, ומה\"ט הי' מניחן למטה תחת כל הלבושים<sup data-n=\"866\">64</sup>, לפי שבט\"ק אינו נוגע (ואינו שייך) הענין ד\"וראיתם אותו וגו'\".\n[וכמודגש גם בהחילוק בנוגע לציצית בלילה: ע\"פ הפסק בשו\"ע<sup data-n=\"867\">65</sup> \"לילה לאו זמן ציצית הוא דאמעיט מוראיתם אותו\" — אתמעט כל מה שלובש בלילה או כסות לילה וכו'; ואילו בפע\"ח<sup data-n=\"868\">66</sup> מחלק בזה: \"אין טלית וציצית בלילה. . אך הט\"ק צריך שישכב עמו אפי' במטה. . לעולם לא יתבטל. . אפילו בלילה אינו נפסק רק של גדלות לבדו הוא שמתבטל אבל ציצית (דט\"ק). . לעולם לא יתבטל אפי' בלילה לכן נקרא ט\"ג וט\"ק ולכן ראוי ליזהר שלא להסיר מעליו ט\"ק",[["861","59","או\"ח ס\"ח ד\"ה ומתוך מה שאמר."],["862","60","וכ\"כ בשו\"ע ר\"ס כד \"ונכון ללובשו על המלבושים\" בהמשך לתוכן דברי הטור שהביא שם [וכבר העירו על הכפל והסתירות בדברי המחבר, דכאן כתב \"עיקר מצות ט\"ק\" ובסי' כד כתב רק \"נכון\" — ראה מאמר מרדכי ס\"ח וכ\"ד. ועוד. ואכ\"מ]."],["863","61","ומ\"ש בשו\"ע שם סכ\"ד ס\"ג רק \"טוב ל­הסתכל בציצית בשעת עטיפה כשמברך\" (וראה ביאורי הגר\"א שם סק\"ז), דלכאורה לפי הנ\"ל הרי זה מגוף מצות ציצית — י\"ל, כי הראי' והסתכלות בפועל אינה מעכבת, והרי המדובר בשעת העטיפה שאז הרי זה גלוי ונראה לפניו (וראה ביאורי הגר\"א שם סק\"ח)."],["864","62","וכמפורש בשל\"ה קיא, סע\"ב ואילך (ע\"פ זהר פרשתנו קעד, ב), דעיקר מצות ט\"ק לקיים תמיד וראיתם אותו וזכרתם (ולכן \"עיקר העונש הוא על בלתי זהיר בט\"ק אשר הוא לבוש בכל עת\")."],["865","63","ס\"ח סי\"ז."],["866","64","וכהלשון באור צדיקים ועוד (הנ\"ל הערה 13) עיקר מצות ט\"ק על החלוק כו'."],["867","65","או\"ח ר\"ס יח ובנו\"כ שם. שו\"ע אדה\"ז שם."],["868","66","שם ספ\"א. מהר\"י צמח בהגהותיו כו' (הובא בברכ\"י או\"ח שם ס\"ח סי\"א). וראה גם בסידורי האריז\"ל הנ\"ל. ועוד."]]],[1301430161,"בשום זמן אפילו בהיותו ישן<sup data-n=\"869\">67</sup> רק ב­כניסתו למרחץ, לכך ראה דוד עצמו ערום במרחץ ולא בהיותו ישן כי אז הי' לו ט\"ק כנ\"ל\"<sup data-n=\"870\">68</sup>.\nוהיינו כי ע\"פ כתהאריז\"ל אין תקנת הט\"ק בעיקרה בשביל קיום מצות \"וראי­תם אותו<sup data-n=\"871\">69</sup> וזכרתם את כל מצות ה'\"].\nח. ועוד י\"ל בזה, ע\"פ דיוק בלשון כהאריז\"ל שם: בשער הכוונות<sup data-n=\"872\">70</sup> מביא ענין זה בתור הנהגת האריז\"ל עצמו אבל לא הורה בפירוש שכן צריך לנהוג כאו\"א<sup data-n=\"873\">71</sup>. וגם בפע\"ח כתב \"הי' נוהג מורי. . כשהי' לובש הציצית קטן כמו בשעה שהי' עולה כו' אז הי' מעטף בו ומורידו מן הגוף כדרך לבישתו, אמנם זה השינוי הנ\"ל הוא כי הט\"ג הוא למעלה כו' וה­ט\"ק הוא תחת כל המלבושים\", וממשיך \"שלא כדעת קצת מקובלים כו'\". והיינו, דגם לפי המקובלים יש מקום ללבוש הט\"ק למעלה מן הלבושים, אלא ש­הנהגת האריז\"ל עצמו לא היתה כן<sup data-n=\"874\">72</sup>.\nובטעם הדבר י\"ל: גם לפי מ\"ש בכת­האריז\"ל, ישנו גם בט\"ק הענין ד\"וראיתם אותו\", אלא שחלוק גדר \"וראיתם אותו\" בט\"ק מבט\"ג<sup data-n=\"875\">73</sup>:\nבט\"ג \"שהוא בחי' חיצוניות כו'\", גדר \"וראיתם אותו\" הוא כפשוטו — ראי' בחיצוניות, כי זה נוגע להנהגה חיצונית \"שלא יזדמן חטא לידו\"<sup data-n=\"876\">74</sup>, ויבוא לידי שמירת כל המצות; משא\"כ בט\"ק ש\"הוא בחי' הפנימיות\"<sup data-n=\"877\">75</sup>, גדר \"וראיתם אותו\" הוא ראי' פנימית, והיינו ראי' והסתכלות בפנימיותו, קדושת ועליית האדם עצמו למעלה נעלית יותר במצות.\nועפ\"ז מובן מה שכו\"כ מבנ\"י, וגם מהחסידים לובשים הט\"ק תחת הבגדים — ונזהרין שהציצית יראו מבחוץ, ב­התאם לפס\"ד אדה\"ז בשלחנו, ולא כפי הוראת אדה\"ז עצמו שיש לנהוג כה­מקובלים נגד הפוסקים\n— כי הנהגה זו של האריז\"ל, אינה הוראה לרבים<sup data-n=\"873\">71</sup>, כי בנ\"י זקוקים לזכירת כל המצות כפשוטה<sup data-n=\"879\">76</sup>, הן בסו\"מ שלא יזדמן חטא על ידו<sup data-n=\"880\">77</sup>, כבהמשך הכתוב \"ולא תתורו אחרי לבבכם ואחרי עיניכם אשר אתם זונים אחריהם\"<sup data-n=\"881\">78</sup>, והן בוע\"ט,",[["869","67","הובא במג\"א שם סכ\"א סק\"ב (מ\"כתבי האר\"י\")."],["870","68","במג\"א הקשה על הראי' שבכתבי האריז\"ל הנ\"ל. וראה נו\"כ השו\"ע שם. ובארוכה בברכ\"י ס\"ח שם. ואכ\"מ."],["871","69","ראה פע\"ח (הנ\"ל הערה 18). וראה סידור האריז\"ל (קול יעקב) שם \"אף בלילה אף שהוא זמן פטור מהברכה מוראיתם אותו כו'\"."],["872","70","ב\"ענין ציצית\", משא\"כ בדרושי תפלת שחרית שם. ואולי י\"ל דקאי אדלעיל מיני'. וצ\"ע."],["873","71","להעיר מברכ\"י שם ד\"ה ומ\"ש דאין ראי', בחילוק אם הרח\"ו כותב מנהג האריז\"ל לחוד או לשון סתמי שאז הוא לכאו\"א."],["874","72","ומ\"ש בשער הכוונות \"שלא כאותם ה­מתייהרים ללבשו ע\"כ בגדיו\" אין הכוונה לחשש יוהרא (ע\"ד מ\"ש בשו\"ת מהר\"י ברונא סצ\"ו), אלא הכוונה דיוהרא הוא חיצוניות וט\"ק הוא פנימיות. ועצ\"ע."],["875","73","וראה לעיל הערה 18."],["876","74","ל' שער הכוונות שם דרוש ז. פע\"ח שם פ\"ו."],["877","75","ולהעיר גם מל' אדמו\"ר (מהורש\"ב) נ\"ע שצויינה בהערה 31."],["873","71","להעיר מברכ\"י שם ד\"ה ומ\"ש דאין ראי', בחילוק אם הרח\"ו כותב מנהג האריז\"ל לחוד או לשון סתמי שאז הוא לכאו\"א."],["879","76","ומה שהבגד גופא לובשים תחת כל ה­בגדים, היינו בכדי שיהי' להם גם הענין ד\"פנימי\". וראה בהנסמן בהערה הקודמת."],["880","77","כמעשה רב במנחות מד, א. ובכו\"כ דרז\"ל. וראה בארוכה במפרשי התורה פרשתנו — אבר­בנאל, ספורנו. ובכ\"מ."],["881","78","ועפ\"ז יומתק מה שהביא הנמוק\"י (הנ\"ל הערה 33) הכתוב הנ\"ל, שהוא המקור לדברי הב\"י בשלחנו כמ\"ש בב\"י ס\"ח שם."]]],[1301430162,"קיום כל המצות, והוא ע\"י \"וראיתם אותו (שאז) וזכרתם את כל מצות ה' ועשיתם אותם\".\nורק בחלק מהם — שייך מעין הנהגת האריז\"ל — שהט\"ק וגם הציציות יהיו מכוסות, כי אין צריכים (כ\"כ) לגדר \"וראיתם אותו\" כפשוטו (במשך כל היום וכל רגע) בשביל זהירות וקיום מצות כפשוטו, ואצלם מאיר יותר ענין הראי' בפנימיות.\nומה\"ט גם בדור שלפנינו לא ראינו הנהגה זו ללבוש ט\"ק תחת כל הבגדים באופן שהציציות תהיינה מכוסות בכל בנ\"י כ\"א בחלק מהם, וי\"ל מפני שזהו \"אפס קצהו ושמץ מנהו\" מהעבודה ה­נעלית של האריז\"ל.\nט. ויהי רצון, שהזהירות במצות ציצית — לפי שינוי המנהגים שבזה<sup data-n=\"882\">79</sup>\n— אלה שמוציאים הציציות מבחוץ להבגדים, ש\"נושא חותם אדונו קבוע בכסותו\"<sup data-n=\"883\">80</sup>, ואחינו בנ\"י שאין הולכים ב­ציצית בגלוי, ע\"פ הנהגת האריז\"ל (שאז היא הנהגה (הראוי') ע\"פ תורה) —\nתזרז קיום מצות ציצית של הקב\"ה — בלשון תפלתנו<sup data-n=\"884\">81</sup> \"והביאנו לשלום מ­ארבע כנפות הארץ. . לארצנו\", בביאת משיח צדקנו בקרוב ממש.\n<span data-k=\"q\">(משיחות ש\"פ פקודי תשמ\"א. ש\"פ מקץ תשמ\"ג)</span>",[["882","79","ולהעיר, שבהנהגת כ\"ק מו\"ח אדמו\"ר ראינו, שאף שהי' לובש הט\"ק, באופן שכאשר הבגד העליון הי' פתוח, היו הט\"ק והציציות נראים — אמנם בכמה זמנים במשך היום הי' הבגד העליון סגור (מכופתר) ומכסה הט\"ק והציצית. — אבל לא שמענו ממנו — בכ\"ז."],["883","80","ל' החינוך מצוה שפו. וראה גם נמוק\"י שם. ספורנו פרשתנו. ועוד."],["884","81","בברכת אהבת עולם. ולהעיר שתיבות אלו שייכות במיוחד לאחיזת הציצית — ראה אור צדיקים שם. מקו\"ח סכ\"ד סוס\"א. שם ס\"ה. וראה גם \"היום יום\" כ\"ב סיון."]]],[1301430163,"<h3>שיחה א</h3>\nא. בפסוק<sup data-n=\"885\">1</sup> \"ויחר למשה מאד ויאמר אל ה' אל תפן אל מנחתם גו'\", מעתיק רש\"י \"אל תפן אל מנחתם\" ומפרש \"לפי פשוטו הקטורת שהם מקריבים לפניך מחר אל תפן אליהם<sup data-n=\"886\">2</sup>. והמדרש<sup data-n=\"887\">3</sup> אומר<sup data-n=\"888\">4</sup> יודע אני שיש להם חלק בתמידי צבור אף חלקם לא יקובל לפניך לרצון תני­חנו האש ולא תאכלנו\"<sup data-n=\"889\">5</sup>.\nוכתבו המפרשים<sup data-n=\"890\">6</sup> הטעם שהוצרך רש\"י להביא את פירוש המדרש ולא הסתפק בפירוש הפשוט — דקאי על \"הקטורת שהם מקריבים לפניך מחר (ש)אל תפן אליהם\" — דקשה לי' איך סלקא אדעתי' של משה שהקטורת ש­הקריבו רשעים הללו תקובל לרצון לפני הקב\"ה והי' צריך לבקש ע\"ז מ­הקב\"ה \"אל תפן\"? ולכן מביא רש\"י את פירוש המדרש דקאי על חלקם בתמידי צבור, שעל זה יש צורך לתפלה מיוחדת ש\"חלקם לא יקובל לפניך לרצון וכו'\".\nאבל צ\"ע בזה, שהרי קושי זה שב­פירוש הפשוט אינו בפרט (צדדי) שבו, אלא בכללות הפירוש, ולכן, לכאורה אין לפירוש זה מקום כלל מעיקרא, וא\"כ מדוע מביא רש\"י פירוש זה בכלל, ויתרה מזה — כפירוש ראשון ועקרי — והו\"ל להביא רק פירוש המדרש לחוד (כדמצינו בכו\"כ מקומות שרש\"י מביא רק פירוש המדרש).\nלכאורה יש לומר, שלכן מקדים רש\"י (לפני הפירוש הראשון) \"לפי פשוטו ה­קטורת כו'\" [ולא כדרכו בכל מקום שכשמפרש (תחילה) את פירושו הפשוט בהכתוב, אינו מזכיר שזהו \"לפי פשוטו\"] — להדגיש, דאע\"פ שמוכח מיד כי פי' זה קשה מעיקרו, מ\"מ זהו פירוש הכתוב \"לפי פשוטו\" (היינו לפי פשטות לשון הכתוב הזה).\nאבל פירוש זה בדברי רש\"י אינו מסתבר כלל, כי פשיטא שרש\"י לא יביא (וכ\"ש שלא יקדים) פירוש כזה שהוא מופרך ומוקשה מחמת תוכן הענין (אף שזהו פשוטו של לשון הכתוב). וכיון שלמרות הקושי הנ\"ל מביא רש\"י את ה­פירוש \"לפי פשוטו\", ולא עוד אלא ש­מקדימו לפירוש \"המדרש\", הרי עכצ\"ל שפירוש זה קרוב יותר לפשש\"מ (לא רק מצד שטחיות לשון הכתוב, אלא גם) מצד תוכנו, והיינו שהוא קרוב יותר ליישב דברי המקרא מאשר המדרש.\nב. ויובן זה בהקדים הדיוק בלשון רש\"י \"הקטורת שהם מקריבים לפניך מחר אל תפן אליהם\" — כלומר, אל ה­אנשים המקריבים — ולא כתב \"אל תפן אלי'\", שזה (א) מתאים יותר להתחלת דבריו: \"הקטורת. . אל תפן אלי'\"; וב­עיקר (ב) מתאים לתוכן הבקשה בהכתוב \"",[["885","1","פרשתנו טז, טו."],["886","2","ברמב\"ן כאן העתיק מפרש\"י \"אלי'\". וכ\"ה בדפוס ראשון ודפוס שני וכו\"כ כת\"י רש\"י. וראה לקמן סעיף ב."],["887","3","תנחומא פרשתנו ז. במדב\"ר פי\"ח, י. וראה לקמן סעיף ה."],["888","4","ברמב\"ן \"(ומדרשו) אמר\". וכ\"ה בעוד כת\"י רש\"י (שתח\"י). וראה לקמן הערה 29."],["889","5","ברמב\"ן ליתא סיום פרש\"י \"תניחנו האש כו'\", וכן ליתא בדפוס ראשון. וראה לקמן הערה 28."],["890","6","גו\"א. הואיל משה. דבק טוב. אמרי שפר. ועוד. וראה גם פענח רזא כאן: לא שחשש משה ח\"ו שהקב\"ה יקבל מנחת שוא אלא שלא ישרף חלקם כו'."]]],[1301430164,"אל תפן אל מנחתם\", שהפני' (תפן) היא אל המנחה ולא אל האנשים המקריבים.\n[ברמב\"ן אכן העתיק בפירש\"י \"אלי'\", וכ\"ה לכמה גירסאות בפרש\"י<sup data-n=\"891\">7</sup>. אמנם מזה שמצינו בכמה מקומות כהנוסחא שלפנינו \"אליהם\"<sup data-n=\"892\">8</sup>, מקום להכריע שכ\"ה הנוסח העיקרי, וכמבואר כ\"פ, שכאשר מוצאים ב' גירסאות ברש\"י — גירסא המובנת בפשטות וגירסא שלכאורה קשה להבינה ולהולמה — אזי מסתבר, אדרבה, שהגירסא הבלתי מובנת ובכ\"ז הובאה — היא היא הנכונה. ומובן ג\"כ — המעתיקים (או המדפיסים) שינו, שבודאי כוונתם רצוי' וכשרה, אלא שלדעתם ה­שינוי תיקון הוא, כי רק עפ\"ז יובן הכתוב והלשונות בהכתובים].\nוי\"ל שדייק רש\"י וכתב \"אליהם\" ולא \"אלי'\", כדי להסביר את פירוש הכתוב כאן.\nוהביאור בזה: בדברי משה אל קרח ואל כל עדתו<sup data-n=\"893\">9</sup> \"זאת עשו קחו לכם מחתות קרח וכל עדתו ותנו בהן אש ושימו עליהן קטורת לפני ה' מחר והי' האיש אשר יבחר ה' הוא הקדוש\", פרש\"י: \"זאת עשו קחו לכם מחתות — מה ראה לומר להם כך אמר להם כו' אנו אין לנו אלא כו' כה\"ג אחד ואתם מאתים וחמשים איש מבקשים כהונה גדולה אף אני רוצה בכך הא לכם תשמיש חביב מכל היא הקטורת החביבה מכל הקרבנות וסם המות נתון בתוכו שבו נשרפו נדב ואביהוא לפיכך התרה בהם כו' מי שיבחר בו יצא חי וכולכם אובדים\".\nולפ\"ז מובן שהבירור שאהרן \"הוא הקדוש\" בא עי\"ז שאהרן \"יצא חי וכול­כם אובדים\"<sup data-n=\"894\">10</sup>, כי מאחר ש\"אין לנו כו' אלא כה\"ג אחד\", שרק לו שייכת עבודת הקטורת ולא לאחרים, נמצא שהקטורת של \"כולכם\" היא קטורת זרה<sup data-n=\"895\">11</sup> — וזר שמקטיר קטורת ה\"ה במיתה, בדוגמת נדב ואביהוא שנשרפו על ידה — ולכן \"כולכם אובדים\" וזה ש\"יצא חי\" בו בחר ה'.\nאבל כ\"ז הי' בתחלה, כשחשב משה שאותם חמשים ומאתים איש מבקשים כהונה גדולה (דבר ש\"אף אני רוצה בכך\"). אבל לאחרי השקו\"ט והדברים הרכים<sup data-n=\"896\">12</sup> ודברי שלום שדיבר משה אל קרח ובני לוי (\"המעט מכם כי הבדיל וגו'\"<sup data-n=\"897\">13</sup>), ולאחר ששלח משה \"לקרוא לדתן ולאבירם גו'\" — \"שהי' משה מחזר אחריהם להשלימם בדברי שלום\"<sup data-n=\"898\">14</sup> — וכל דבריו והשתדלותו לא הועילו כלל, אלא עמדו במרדם, אז — \"ויחר למשה מאד — נצטער עד למאד\"<sup data-n=\"899\">15</sup>, ואז אמר \"אל תפן אל מנחתם\": \"הקטורת שהם",[["891","7","ראה לעיל הערה 2."],["892","8","וכן הובא בכמה מפרשי רש\"י."],["893","9","טז, ו­ז."],["894","10","פרש\"י שם."],["895","11","כמפורש בהמשך הפרשה (יז, ה) \"למען אשר לא יקרב איש זר אשר לא מזרע אהרן הוא ל­הקטיר קטורת לפני ה'\". וכן משמע במפרשי רש\"י כאן ובכמה מפרשי התורה (ראה רמב\"ן טז, ח. חזקוני שם, ו. ועוד). וראה ת\"י יומא (מז, א ד\"ה הכא מחתה). תוד\"ה נאמרה שם (מה, ב). ועוד.\nובצפע\"נ (עה\"ת פרשתנו טז, ז. שם, יז. שו\"ת צפע\"נ נ. י. סרמ\"ז) \"גם הקטורת הוי של חול וזרה ולית בי' שום חיוב של זרות וגם על הכנסה ליכא חיוב מיתה ביד\"ש. . החיוב שלהם הוי רק בשביל שהם לקחו אש מן המזבח\". ע\"ש בארוכה. וראה לקמן ס\"ג."],["896","12","פרש\"י שם, ח."],["897","13","טז, ט."],["898","14","טז, יב ובפרש\"י."],["899","15","ראה בארוכה במפרשי רש\"י במה שכ' \"נצטער עד למאוד\" ולא פי' ש\"כעס\" וכיו\"ב."]]],[1301430165,"מקריבים לפניך מחר אל תפן אליהם\", והיינו שעונשם לא יהי' בדוגמת מיתת נדב ואביהוא, עונש ע\"ז שהקטירו אש זרה, אלא \"אל תפן (כלל) אליהם\", ש­ימותו מחמת פשעם ומרדם הם.\nועפ\"ז יומתקו דברי משה \"אל תפן אל מנחתם\", ולא \"אל תקבל את גו'\", או \"אל תקח את גו'\", וכיו\"ב, כי כאן אין הכוונה שלא יקבל הקרבת הקטורת שלהם, דפשיטא הוא ומאי קמ\"ל<sup data-n=\"900\">16</sup> (כנ\"ל ס\"א) — אלא שלא יפנה אליהם כלל, שעי\"ז יהי' ניכר שמיתתן לא באה כתוצאה מזה שהקטירו קטורת (אלא שהייתה שלא כהלכה).\nוהטעם על זה מובן: מתחלה כאשר הי' מקום לחשוב שהמאתים וחמשים איש רוצים כהונה גדולה בחשבם שראויים הם לכך, אמר להם משה שע\"י הקטורת יבחר ה' מי הוא הראוי לכהונה, וכולם אובדים מחמת סם המות שבקטורת; אבל<sup data-n=\"901\">17</sup> לאחרי שראה שכל ערעורם של הר\"ן איש נשיאי העדה אינו אלא חלק מכללות מחלוקתם של קרח ודתן ואבירם על משה ואהרן וכו' כנ\"ל — אין להענש עבור פרט הקרבת קטורת זרה, אלא צ\"ל עונש כזה שיבטל את הכלל והעיקר, כללות הערעור על שליחותו של משה וכהונתו של אהרן.\nודבר זה מוכח מהמשך הכתובים, ש­הכתוב שבו נאמר עונשם של הר\"ן איש — \"ואש יצאה מאת ה' ותאכל את החמשים ומאתים איש מקריבי הקטו­רת\"<sup data-n=\"902\">18</sup> — לא בא בהמשך לסיפור הקטרת הקטורת שלהם<sup data-n=\"903\">19</sup>, אלא<sup data-n=\"904\">*19</sup> בהמשך לעונש הבליעה ד\"כל<sup data-n=\"905\">20</sup> האדם אשר לקרח ואת כל הרכוש\"<sup data-n=\"906\">21</sup>.\nוזהו שמדייק רש\"י \"אל תפן אליהם\" ולא \"אלי'\" להמנחה (קטורת), כי בקשת משה לא היתה ביחס להקטורת — כ\"א (בעיקר) לשלילה ביחס להגברא, כנ\"ל.\nג. ובזה יש לבאר השינוי בלשון הכתובים בציוויי משה ע\"ד הקרבת הקטורת, שציווי זה הי' פעמיים:\nבפעם הא' אמר משה \"זאת עשו קחו לכם מחתות קרח וכל עדתו ותנו בהן אש ושימו עליהן קטורת לפני ה' מחר והי' האיש אשר יבחר ה' הוא הקדוש גו'\", אבל לאחרי ש\"ויחר למשה מאד גו' אל תפן אל מנחתם גו'\", אמר להם פעם שני'<sup data-n=\"907\">22</sup> \"אתה גו' ואהרן גו' וקחו איש מחתתו גו' והקרבתם לפני ה'\" — ושני שינויים (עיקריים) ביניהן: (א) בפעם הא' נאמר רק \"ותנו גו' ושימו גו' לפני ה'\", אבל בפעם השני' נאמר ציווי גם על ההקרבה — \"והקרבתם לפני ה'\", (ב) בפעם הא' לא נזכר שגם אהרן נצטווה להקטיר קטורת, משא\"כ בפעם הב'<sup data-n=\"908\">23</sup>.",[["900","16","ועפי\"ז יובן דמש\"כ בשפ\"ח כאן \"אפילו העשן אל תעלה לפניך\", וכן מש\"כ במשכיל לדוד כאן שהכוונה (ע\"ד פי' המדרש) שהאש לא ישרוף את הקטורת — ג\"כ דוחק בפשוטו של מקרא, דסו\"ס מאי קמ\"ל."],["901","17","ראה גם אוה\"ח כאן."],["902","18","טז, לה."],["903","19","טז, יח."],["904","*19","וראה רש\"י יז, ג \"שנחלקו על הכהונה ונשרפו\"."],["905","20","טז, לב­ג."],["906","21","ומש\"כ בפרש\"י (יז, יג) שאמרו בנ\"י \"על ידו מתו נדב ואביהוא על ידו נשרפו חמשים ומאתים איש\", ה\"ז מה שישראל היו \"מליזין ומרננים אחר הקטורת\", וסו\"ס שריפתם באה בשייכות ובהמשך להקטורת, וכמ\"ש (טז, לה) \"ואש יצאה גו' ותאכל את גו' מקריבי הקטורת\" (וראה לעיל הערה 11). וצע\"ק."],["907","22","טז, טז­יז."],["908","23","ראה ראב\"ע ורמב\"ן שם, טז. אוה\"ח שם, יז. ועוד."]]],[1301430166,"וע\"פ הנ\"ל יש לומר, שהשינוי בפעם הב' הוא בהמשך לבקשת משה \"אל תפן אל מנחתם\".\nוהביאור בזה:\nלאחרי ש\"ויחר למשה מאד ויאמר גו' אל תפן אל מנחתם\", שהכוונה בזה (כנ\"ל בארוכה) ש\"אל תפן (כלל) אליהם\", שלא יענשו מפני שהקטירו קטורת זרה אלא מחמת מרדם כו' — קס\"ד לומר, שע\"י בקשה זו פעל משה שלא יהא נחשב כלל כמעשה של הקטרת קטורת (אפילו קטורת זרה)<sup data-n=\"909\">*23</sup>, ולכן הוצרך הכתוב ל­הדגיש שאעפ\"כ הי' כאן מעשה של הקרבת קטורת — \"והקרבתם לפני ה'\"<sup data-n=\"910\">24</sup> (ולכן מפרש הכתוב שגם אהרן הקטיר קטורת, שזה מדגיש שזהו גדר של עבודת הקטורת, השייכת לכהונה).\nוההכרח שהי' בגדר הקטרת קטורת — כי מפורש אח\"כ בפרשה שהמחתות שבהן הקריבו הקטורת נתקדשו, כדיבור ה' למשה<sup data-n=\"911\">*24</sup>: \"אמור אל אלעזר בן אהרן הכהן וירם את המחתות גו' כי קדשו\", ובפרש\"י \"כי קדשו — המחתות ואסורין בהנאה שהרי עשאום כלי שרת\"<sup data-n=\"912\">25</sup>, ואת\"ל שבפועל לא היתה הקטרתם אפילו בגדר קטורת זרה, איך נתקדשו המחתות, ולכן זקוק הכתוב להודיע כאן שמ\"מ היתה כאן פעולה של הקרבת קטורת<sup data-n=\"913\">*25</sup>.\n[משא\"כ בציווי הא' בתחילת הענין, הרי שם אין צורך להדגיש שזוהי עבודת הקטורת, כי עדיין לא ביקש משה \"אל תפן גו'\". וי\"ל, דשם נוגע להדגיש רק המציאות של קטורת, כי עצם הענין של קטורת (גם לולא העבודה שבזה) יש בו כדי לבחון מיהו \"הקדוש\" אשר בו \"יבחר ה'\", וכדיוק לשון רש\"י<sup data-n=\"914\">26</sup> שמשה אמר לקרח ועדתו \"הא לכם תשמיש חביב מכל. . וסם המות נתון בתוכו\", כלומר, המעלה היא שהוא \"תשמיש חביב\", ולאידך \"סם המות נתון בתוכו\", שלכן אלה שלא בחר בם השם — \"(כול­כם) אובדים\"].\nד. אמנם רש\"י אינו מסתפק בפירוש זה, כי עדיין ישנם כמה קשיים ביישוב דברי הכתוב:\nמפשטות המשך הכתוב \"ויחר למשה מאד ויאמר אל ה' אל תפן אל מנחתם\", משמע שבקשה זו יש בה חידוש כללי לגבי הענין המדובר בפרשה דהיינו ה­ערעור על כהונת אהרן, ומסתבר שאין משה צריך לבקש בקשה מיוחדת ש­הקב\"ה יעשה ככל הדרוש לשלול את המחלוקת והערעור על הכהונה.\nולכן מתאים יותר לפרש שהיתה זו בקשה מיוחדת על ענין שאינו שייך (מצ\"ע) לעצם פעולתם ומחלוקתם על אהרן.\nובכלל דוחק לומר שכל בקשת משה היתה רק על אופן שלילת קבלת ה­קטורת שלהם.\nובגלל קשיים אלה (שאינם רק קשיים",[["909","*23","ראה צפע\"נ הנ\"ל הערה 11."],["910","24","ולהעיר מל' רש\"י כאן: הקטורת שהם מקריבים לפניך."],["911","*24","יז, ב."],["912","25","וראה רמב\"ן שם. בכור שור שם. באר מים חיים (לאחי המהר\"ל) ודברי דוד (להט\"ז) על פרש\"י שם. ועוד."],["913","*25","ואולי י\"ל, שזה שהי' נחשב כהקרבת קטו­רת הוא מצד המעשה, שהי' כאן מעשה של הקטרה, וכן מצד ציווי משה, שלכן נתקדשו המחתות; אבל לא בשייכות להגברא, שלא נחשב שהם הקטירו הקטורת (שע\"ז ביקש משה \"הקטורת שהם מקריבים לפניך מחר אל תפן אליהם\", כנ\"ל). אבל ראה לעיל הערה 11, 21. ועצ\"ע."],["914","26","טז, ו."]]],[1301430167,"פרטיים בפירוש זה, אלא יש בהם דוחק בכללות משמעות הכתובים) מקדים רש\"י שפירוש זה הוא \"לפי פשוטו\", שאף שפירוש זה קשה ליישבו בהמשך הכתוב — הרי לפי פשוטו זהו תוכן הכתוב.\nומטעם קושי זה מוסיף רש\"י עוד פירוש: \"והמדרש אומר יודע אני שיש להם חלק בתמידי צבור אף חלקם לא יקובל לפניך לרצון כו'\", שענין זה — \"חלק בתמידי צבור\" א) הו\"ע בפ\"ע שאינו שייך להקרבת הקטורת שלהם, ולא למחלוקת וערעור על כהונת אהרן בכלל, ב) הוא דבר חיובי, שכ\"א מבנ\"י יש לו חלק בתמידי צבור.\nוע\"ז באה הבקשה המיוחדת (דמשה) \"אל תפן אל מנחתם\", שגם חלקם ב­תמידי צבור לא יקובל לרצון ש\"תניחנו האש ולא תאכלנו\".\nובזה התכוון משה (לא (רק) להביא עליהם עוד עונש מיוחד, אלא) להוסיף עי\"ז בשלילת המחלוקת והערעור על ה­כהונה. והיינו, דלא רק שאינם שייכים לכהונה ומגיע להם עונש עבור זה, אלא שהם כאילו נבדלים ר\"ל מכלל ישר­אל<sup data-n=\"915\">27</sup>, שבדבר שכל ישראל משותפים בו — תמידי צבור, הרי בנוגע אליהם — חלקם אינו מקובל ברצון.\nאמנם מובן שפירוש זה אינו לפי פשוטו ורק מדברי ה\"מדרש\" — כי<sup data-n=\"916\">28</sup> ב­כתוב זה ובכל פרשה זו לא נזכר (אפילו ברמז) הענין ד\"תמידי צבור\"<sup data-n=\"917\">29</sup>.\nה. מענינים מופלאים בהלכה שב­פרש\"י זה:\nבמדרש<sup data-n=\"918\">30</sup> איתא \"יודע אני שיש לאלו חלק באותה מנחה<sup data-n=\"919\">31</sup> שהקריבו שנאמר<sup data-n=\"920\">32</sup> מלבד עולת התמיד ומנחתה\", ורש\"י משנה וכ' \"יודע אני שיש להם חלק ב­תמידי צבור\".\nויש לומר, דרש\"י אזיל בזה לשיטתו, דס\"ל שפחות משוה פרוטה אינו נחשב \"שלו\" (כמ\"ש במס' סוכה<sup data-n=\"921\">33</sup>), ועפ\"ז אא\"ל שיש לעדת קרח חלק באותה מנחה, שהרי חלקם אינו שוה פרוטה ובמילא אין שייך בזה \"שלהם\"<sup data-n=\"922\">34</sup>, ולכן שינה",[["915","27","וכלשון המדרש שבהערה 3 \"הואיל ופירשו אלו מבניך אל תסתכל בחלקם\"."],["916","28","ונוסף ע\"ז גם תוכן הפירוש \"חלקם לא יקובל לפניך לרצון תניחנו האש ולא תאכלנו\" הו\"ע של דרש, שהרי בקרבן (תמיד) שלכל ישראל יש חלק בו — חלק של אנשים אחדים (ואפילו ר\"ן וקצת יותר) בזה הוא משהו, וקשה לומר על משהו שיחול ע\"ז \"תניחנו האש ולא תאכלנו\". ואולי זה טעם הגירסא (דלעיל הערה 5) שליתא הסיום בפרש\"י \"תניחנו האש כו'\", והכוונה ב\"חלקם לא יקובל\" היא ל\"חלק\" בציור במחשבה ולא חלק גשמי. וראה לקמן סעיף ה."],["917","29","ואולי י\"ל שפירוש ה\"מדרש\" ברש\"י כאן כוונתו שהמדרש מוסיף על פירוש הפשוט, ולא כבמדרשו ברש\"י בכלל, שבא לומר פירוש שני ולא כפירוש הפשוט, שעפ\"ז יובן: א) מה שלא כ' רש\"י \"ורבותינו דרשו\", או \"ומדרשו\"<sup data-n=\"e20\">*</sup> וכיו\"ב, כ\"א \"וה­מדרש אומר\". ב) ל' רש\"י \"אף<sup data-n=\"e21\">**</sup> חלקם לא יקובל כו'\", והיינו שלא רק שלא יפנה אל הקטורת שלהם (שע\"ז אין צריך בקשה), כ\"א דאף חלקם בתמידי צבור לא יקובל."],["918","30","במדב\"ר שם."],["919","31","וראה תנחומא: שיש להם חלק באותה מנחה שישראל מקריבים לפניך בכל יום."],["920","32","פינחס כט, יט. שם, כב. ועוד."],["921","33","כז, ב ד\"ה כל האזרח."],["922","34","ראה במפרשים לסוכה שם. והאריכו בזה באחרונים. וראה גם לקו\"ש (חלק לד) עקב תשמ\"ז ס\"ד ואילך ובהנסמן שם. ואכ\"מ."],["e20","*","וראה גירסא כזו לעיל הערה 4."],["e21","**","וראה אמרי שפר דשקו\"ט בפי' \"אף\" בפרש\"י כאן. וכ' דלכמה גירסאות ליתא \"אף\"."]]],[1301430168,"רש\"י מלשון המדרש \"באותה מנחה ש­הקריבו\" (שבמנחה אחת ודאי אין להם שווה פרוטה) וכתב \"שיש להם חלק בתמידי ציבור\", שכוונתו בזה (לא לה­מנחה או קרבן תמיד של אותו היום, אלא) לתמידי (ל' רבים) ציבור של כל השנה, שאותו החלק שיש להם (לר\"ן איש) בתמידי ציבור של כל השנה כולה — יחד הוא דבר דשפיר שייך לקרותו בשם \"חלק\". וע\"ז ביקש משה ש\"חלקם בתמידי ציבור (דכל השנה) לא יקובל לפניך לרצון\".\nויש להוסיף ב\"ענינים מופלאים\" ע\"ד הרמז שבפרש\"י — שבדיוק לשונו \"יש להם חלק בתמידי ציבור\" יש למצוא רמז לדברי האריז\"ל<sup data-n=\"923\">35</sup> שקדושה אינה זזה ממקומה, וכמ\"ש אדמו\"ר הזקן<sup data-n=\"924\">36</sup> ש­זהו \"גם לאחר שנתעלה למעלה למעלה\" — שמ\"מ \"אינו נעקר לגמרי מכל וכל ממקומו ומדרגתו הראשונה\".\nובהקדם השאלה בדברי רש\"י \"יש להם חלק בתמידי צבור\", דלכאורה, מלבד השאלה (הנ\"ל) מצד שווי הדבר ודין ממון שבו (כיון שחלקם אינו שווה פרוטה) — הרי אתינן כאן להשקו\"ט הידועה בנוגע לקרבן ציבור, דכיון דהוי דבר של ציבור אין בו שום שייכות להיחיד<sup data-n=\"925\">37</sup>, כי הגדר דציבור הוא לא שותפות של כמה וכמה יחידים, אלא מציאות חדשה, באופן שאין שייכות להיחידים בתור יחידים, ובמילא אין שייך לומר בזה \"חלק\" לכמה יחידים בפ\"ע.\nויש לומר הביאור בזה:\nכוונת רש\"י (שיש להם חלק בתמידי צבור) בפשטות היא — דכיון שכל ישר­אל נתנו מחצית השקל שמהם קנו קר­בנות ציבור (כמפורש בפרש\"י לעיל<sup data-n=\"926\">38</sup>), נמצא, שיש לכאו\"א מישראל חלק ב­קרבנות ציבור<sup data-n=\"927\">39</sup>.\nואף שצריכים למוסרו לציבור יפה יפה<sup data-n=\"928\">40</sup>, כדי שתהא נעשית מציאות חדשה דממון ציבור וחלות דקרבן ציבור, ולא השתתפות של כמה יחידים — מ\"מ כיון שהמציאות של \"צבור\" וקופת הצבור נוצרה ע\"י נתינת מחצית השקל דכל יחיד, א\"א שתתבטל ותעקר לגמרי שיי­כות היחיד להקרבן<sup data-n=\"929\">41</sup> (שהיא ע\"י מחצית השקל שנתן, שזוהי מצותו הפרטית, וב­פרט שנתינת מחצית השקל היתה לכפר על נפשותיכם<sup data-n=\"930\">42</sup>), ובלשון אדה\"ז הנ\"ל ד\"גם לאחר שנתעלה למעלה למעלה\" להיות גדר של צבור, מ\"מ לא \"נעקר לגמרי מכל וכל\" המעלה (והקדושה) שנפעלה על ידי נתינת היחיד, ולכן אפשר לומר בזה \"שיש להם חלק ב­תמידי ציבור\".\nו. ע\"פ כל הנ\"ל יש לבאר גם דיוק הלשון \"יודע אני (שיש להם חלק בתמידי",[["923","35","ראה ע\"ח שער ד פ\"ג. של\"ד פ\"ג. שער לה פ\"א. וראה פרדס שי\"ד פ\"א. וראה לקו\"ש חל\"ב ע' 25­24. וש\"נ."],["924","36","אגה\"ק ביאור לסי' זך (קמז, א)."],["925","37","ראה זבחים ד, סע\"א ובפרש\"י ותוס' שם. תוד\"ה או (מנחות עח, ב). וראה מפענח צפונות פ\"ד ס\"ב וס\"ד. וש\"נ."],["926","38","תשא ל, טו."],["927","39","וכמפורש בבחיי כאן: ודעת רז\"ל שהתפלל משה שלא יתקבל חלקם בתמידי צבור שכל אחד ואחד מישראל יש לו חלק בהם על ידי השקלים."],["928","40","ראה ר\"ה ז, סע\"א. וש\"נ. משנה למלך להל' כלי המקדש פ\"ו ה\"ט."],["929","41","וראה ספר המאמרים תיש\"א ע' 31 ובהערה שם. לקו\"ש חי\"ח ע' 113 ואילך."],["930","42","תשא שם. ובפרש\"י שם \"ועל אותה תרומה (לקנות מהם קרבנות צבור) נאמר לכפר על נפשו­תיכם\"."]]],[1301430169,"צבור)\" — דלכאורה מיותר, והול\"ל \"יש להם חלק בתמידי צבור\" וכיו\"ב.\nאך הביאור בזה: ענין הנ\"ל, שגם ל­אחרי שמחצית השקל נעשית חפצא ד­ממון ציבור, יש שייכות להיחיד עם הקרבן ציבור שנקנה ע\"י נתינת מחצית השקל שלו, אינו דבר שניתן לכאו\"א להבין מצ\"ע, אלא רק ע\"י משה רבינו, שהוא נשיא הדור,\nכי ע\"פ סדר וטבע הדברים, הרי צבור ויחיד הם שני גדרים וסוגים הפ­כיים, וכמו בקרבנות, דקרבן יחיד וקרבן ציבור הם שני מינים שונים, ולא הרי זה כהרי זה<sup data-n=\"931\">43</sup> [ומזה נשתלשל גם בסדר ה­עולם, שישנן שני הנהגות כלליות בסדרי החיים של קיבוצי בני אדם (מדינות וכיו\"ב): יש משטר המדגיש את צרכי הציבור והכלל, גם כשהם על חשבון הפרט והיחיד וגורע או גם שולל אותם, וישנה הנהגה המדגישה את חירות וטובת ותועלת הפרט, כל יחיד בפ\"ע (ועד של­פעמים דוחים את טובת הציבור והכלל עבור תועלת היחיד), כי בסדר הנהגה זו, מעלת הפרט והיחיד היא המכרעת וקובעת את סדר החיים].\nאבל כל זה הוא מצד גדר של \"סדר\", סדר דציבור וסדר דיחיד מצ\"ע. אבל כפי שהוא מצד \"נשיא הדור\", ש\"הנשיא הוא הכל\"<sup data-n=\"932\">44</sup> — הרי בכחו ופעולתו לאחד את שתי המעלות. וכמו שהוא בנוגע למציאות הנשיא עצמו — ששני ענינים אלה נכללים בהנשיא גופא: מצד אחד הרי הוא איש אחד, ולאידך, כל עניניו ופעולותיו שייכים ונוגעים להכלל כולו. ועד\"ז הוא בענין הנשיאות שבו גופא, שהנשיאות היא לא רק נשיאות על הכלל כולו, אלא הוא הנשיא של כל אחד ואחד בפרט בפני עצמו [ויש לומר שזהו דיוק לשון הרשב\"א<sup data-n=\"933\">45</sup> \"המלך כצבור ש­הצבור וכל ישראל תלויין בו\", שהתלות במלך היא לא רק תלות הצבור והכלל, שהיא מציאות אחת, אלא גם התלות דכל ישראל, כל אחד בפני עצמו (ריבוי יחידים)].\nולכן דוקא מצד משה, \"נשיא הדור\", נמשכת ובאה הידיעה (הפועלת ועושה פירות בפועל), שגם בתמידי ציבור, ש­כל כולם הוא גדר של קרבן ציבור ולא קרבן שותפין, השתתפות של יחידים, לא יתבטל חלק היחיד, ובמילא המעות שישנן ב(קרבן) ציבור שהוא נעלה יותר ובשלימות אחרת לגמרי, יש להם שיי­כות וקשר גם ליחיד, לא רק כפי שהוא חלק מהציבור, אלא גם כפי שהוא חלק ופרט בפני עצמו.\nז. פ' קרח חלה בכמה שנים בסמיכות לג' תמוז, היום אשר \"חופשה ניתנה לו\" לכ\"ק מו\"ח אדמו\"ר, נשיא הדור, ממאסרו אשר נאסר על הרבצת התורה וחיזוק הדת.\nונקודה ותוכן הנ\"ל מצינו ב\"עבודה הגדולה\" אשר עבד \"בהרבצת התורה וחיזוק הדת\"<sup data-n=\"934\">46</sup>, שאף שהי' בממדים גדו­לים ורחבים הנוגעים להצבור וכלל ישראל (הן במדינה ההיא וכ\"ש וק\"ו",[["931","43","ראה פיה\"מ להרמב\"ם הקדמה לסדר קדשים (נעתק בלחם משנה ריש הל' מעשה ה­קרבנות)."],["932","44","פרש\"י חוקת כא, כא."],["933","45","בשו\"ת שלו ח\"א סקמ\"ח."],["934","46","ל' כ\"ק מו\"ח אדמו\"ר במכתבו לחגיגת י\"ב תמוז הראשונה — בשנת תפר\"ח (נדפס בסה\"מ תש\"ח ע' 263. אגרות קודש שלו ח\"ב ע' פ. ועוד), בו כותב \"ראוי הוא לקובעו ליום התועדות והתעוררות לחיזוק התורה והיהדות בכל אתר ואתר לפי ענינו כו'\"."]]],[1301430170,"לאחר צאתו ממדינה ההיא), מ\"מ לא נגרע עי\"ז ח\"ו מההתענינות וההשתדלות בטובת היחיד והפרט ברוחניות וגם ב­גשמיות, ועד שהניח את עצמו בשביל טובתו של איש פרטי, אף שהאיש שהי' מטיב עמו הנה לא זו בלבד שלא הי' כלל בסוג של \"חבירו בתורה ומצות\"<sup data-n=\"935\">47</sup>, אלא שהי' שלא בערכו כלל.\nומעלה זו ממשיך נשיא הדור לכאו\"א ההולכים בדרכיו, ועוסקים בהרבצת ה­תורה וחיזוק הדת, שיוכלו לעסוק ולפ­עול בהפצת היהדות והמעינות לכלל ולצבור, וביחד עם זה שלא לגרוע בה­השתדלות לטובת הפרט.\nועל ידי העבודה באופן הנ\"ל פועלים הגאולה לא רק דכלל ישראל כולו אלא גם דכל אחד ואחת בפרט [וכמו שהי' בגאולת כ\"ק מו\"ח אדמו\"ר בי\"ב י\"ג תמוז, כמו שמדייק במכתבו הידוע<sup data-n=\"936\">48</sup> \"לא אותי בלבד גאל הקב\"ה בי\"ב תמוז כי אם גם את כל מחבבי תורתנו הק', שומרי מצוה, וגם את אשר בשם ישראל יכונה, כי כל איש ישראל (מבלי התחשב עם מצבו הפרטי בשמירת וקיום המצות) לבו תמים עם ד' ותורתו\"] —\nשהקב\"ה גואל לא רק את כלל ישראל, אלא את כאו\"א, כמ\"ש<sup data-n=\"937\">49</sup> \"ואתם תלוקטו לאחד אחד בני ישראל\", כל יחיד בפני עצמו, וכפרש\"י<sup data-n=\"938\">50</sup> שהקב\"ה \"אוחז בידיו ממש איש איש\", וכולם מתאחדים יחד ב\"קהל גדול\" ש\"ישובו הנה\"<sup data-n=\"939\">51</sup> בגאולה האמיתית והשלימה, בעגלא דידן ממש.\n<span data-k=\"q\">(משיחות ש\"פ קרח תשמ\"ז, י\"א ניסן תשל\"א)</span>",[["935","47","ראה תניא פרק לב ובהנסמן בקיצורים והערות לשם."],["936","48","הנ\"ל הערה 46."],["937","49","ישעי' כז, יב."],["938","50","נצבים ל, ג."],["939","51","ירמי' לא, ז."]]],[1301430171,"<h3>שיחה ב</h3>\nא. ממש\"נ גבי חיוב הפרשת תרומה<sup data-n=\"940\">1</sup> \"כן תרימו גם אתם תרומת ה'\" למדו חז\"ל<sup data-n=\"941\">2</sup> \"גם אתם, מה אתם בני ברית אף שלוחכם (ד\"גם אתם (בא) לרבות את ה­שליח\"<sup data-n=\"942\">3</sup>) בני ברית\", שאין שליחות ל­נכרי.\nומצינו בגמ'<sup data-n=\"943\">4</sup> שקו\"ט בגדרי דין זה: רב אשי אמר כי אמרינן אין שליחות ל­נכרי הני מילי בתרומה אבל בכל התורה כולה יש שליחות לנכרי (ומסיק בגמ') והא דרב אשי ברותא<sup data-n=\"944\">5</sup> היא מאי שנא תרומה דלא, דכתיב אתם גם אתם מה אתם בני ברית אף שלוחכם נמי בני ברית, שליחות דכל התורה כולה נמי (שיהא שלוחו כמותו. רש\"י<sup data-n=\"945\">6</sup>) מתרומה גמרינן לה (בקידושין. רש\"י<sup data-n=\"945\">6</sup>).\nבפשטות משמע<sup data-n=\"947\">7</sup>, דטעמו של ר\"א דדין \"אין שליחות לנכרי\" הוא רק ב­תרומה ולא בכל התורה כולה הוא מפני שס\"ל שלא גמרינן שליחות כל התורה כולה מתרומה<sup data-n=\"948\">8</sup>.\nאבל לכאורה דוחק לומר שהפלוגתא כאן היא אם גמרינן שליחות כל התורה כולה מתרומה<sup data-n=\"949\">9</sup>. ויותר מסתבר לומר, ש­החילוק בין ר\"א ומסקנת הגמ' הוא ב­סברא:\nרב אשי ס\"ל דדין זה \"מה אתם בני ברית כו'\" הוא גזירת הכתוב, כי מצד הסברא היינו אומרים שגם נכרי יכול להיות שליח לישראל, ולכן אין לך בו אלא חידושו, ורק בתרומה אמרינן הכי ולא בכל התורה כולה.\nמשא\"כ למסקנת הגמ', ה\"ז דבר שב­סברא, שהשליח צ\"ל דומה למשלח — \"מה אתם כו' אף שלוחכם כו'\", והיינו דמ\"ש גבי תרומה \"גם אתם\" הוא רק גילוי מילתא, שגדר השליחות מחייב ש­השליח יהי' דומה להמשלח — ולכן אין דין שליחות לנכרי (גם) בכל התורה כולה.\nב. ונראה דפליגי בעצם גדר השלי­חות — ובהקדם החקירה הידועה<sup data-n=\"950\">10</sup> בענין",[["940","1","פרשתנו יח, כח."],["941","2","קידושין מא, ב. וש\"נ. רמב\"ם הל' אישות פ\"ג הי\"ז (וראה לח\"מ שם). הל' תרומות רפ\"ד. הל' שלוחין ושותפין רפ\"ב."],["942","3","קידושין שם ריש ע\"ב (וראה רש\"י שם ד\"ה גם וד\"ה לכדר' ינאי). וראה רמב\"ם הל' אישות והל' תרומות שם. וש\"נ."],["943","4","ב\"מ עא, ב."],["944","5","או \"בדותא\" (ראה על הגליון בב\"מ שם. יד מלאכי כללי הב' אות קיג)."],["945","6","ראה תורת חיים לב\"מ שם ד\"זה תימה דבריש פ\"ב דקידושין איתא בהדיא דאדרבא הא דשליחות מהניא בתרומה גמרינן לה משאר מילי\". ובכוס ישועות (ב\"מ שם) מפרש דברי הגמ' \"דילפינן כל התורה כולה מתרומה (רק) לענין זה דאין שליחות לנכרי. . וגם ברש\"י אפשר לדחוק ולפרש כזה\".\nאבל ראה טורי אבן לחגיגה י, ב (ד\"ה מה התם). ועוד. ואכ\"מ."],["945","6","ראה תורת חיים לב\"מ שם ד\"זה תימה דבריש פ\"ב דקידושין איתא בהדיא דאדרבא הא דשליחות מהניא בתרומה גמרינן לה משאר מילי\". ובכוס ישועות (ב\"מ שם) מפרש דברי הגמ' \"דילפינן כל התורה כולה מתרומה (רק) לענין זה דאין שליחות לנכרי. . וגם ברש\"י אפשר לדחוק ולפרש כזה\".\nאבל ראה טורי אבן לחגיגה י, ב (ד\"ה מה התם). ועוד. ואכ\"מ."],["947","7","וכ\"כ בכוס ישועות שם."],["948","8","כהסוגיא בקידושין שם (כנ\"ל הערה 6)."],["949","9","ובכוס ישועות שם מפרש, שמסקנת הגמ' היא שלמדין הדין דאין שליחות לנכרי (בכל התורה) מתרומה. וראה לעיל הערה 6."],["950","10","ראה לקח טוב להר\"י ענגל כלל א בארוכה (והביא ראיות לכל הצדדים). ולהעיר מל' אדה\"ז (קו\"א לשו\"ע או\"ח סרס\"ג סכ\"ה): כעושה בעצמו ממש כו' ה\"ז כאילו אוחז ידו של חבירו כו' שנעשית כידו אריכתא."]]]]});
